מב. עִקַּר הַבְּרִיאָה הוּא רַק בִּשְׁבִיל הָאֱמֶת, כְּמוֹ שֶׁכָּתוּב: "בְּרֵאשִׁית בָּרָא אֱלֹקִים אֵת וְגוֹ'", וְדָרְשׁוּ רַבּוֹתֵינוּ זַ"ל שֶׁסּוֹפֵי־תֵבוֹת - "אֱמֶת", שֶׁבּוֹ נֶחְתְּמוּ שָׁמַיִם וָאָרֶץ. כִּי הַקָּדוֹשׁ־בָּרוּךְ־הוּא עֶצֶם הָאֱמֶת, וְחוֹתָמוֹ אֱמֶת, וְעִקַּר הִשְׁתּוֹקְקוּתוֹ יִתְבָּרַךְ הוּא רַק אֶל הָאֱמֶת, וְכָל הַבְּרִיאָה כֻּלָּהּ מֵרֹאשׁ וְעַד סוֹף הוּא רַק בִּשְׁבִיל זֶה כְּדֵי לְגַלּוֹת הָאֱמֶת, כְּמוֹ שֶׁאָמְרוּ בַּזֹּהַר הַקָּדוֹשׁ, שֶׁהַבְּרִיאָה הָיְתָה "בְּגִין דְּיִשְׁתְּמוֹדְעִין לֵהּ", שֶׁזֶּהוּ עִקַּר הָאֱמֶת שֶׁיַּכִּירוּ וְיֵדְעוּ אֲמִתַּת אֱלָקוּתוֹ יִתְבָּרַךְ כְּמוֹ שֶׁהוּא בֶּאֱמֶת; כִּי הַשֵּׁם יִתְבָּרַךְ עֶצֶם הָאֱמֶת כִּבְיָכוֹל. אַךְ מֵחֲמַת שֶׁהָעוֹלָמוֹת אִי אֶפְשָׁר לָהֶם לִסְבֹּל וּלְקַבֵּל עֶצֶם אוֹר הָאֱמֶת, כִּי יִתְבַּטְּלוּ בַּמְּצִיאוּת, עַל־כֵּן צִמְצֵם הַשֵּׁם יִתְבָּרַךְ אוֹר הָאֱמֶת וְהִסְתִּיר וְהִצְפִּין וְהִלְבִּישׁ אוֹר הָאֱמֶת וּמִעֲטוֹ בְּאֹפֶן שֶׁיּוּכְלוּ לְקַבְּלוֹ. וּמֵחֲמַת שֶׁמִּעֵט וְצִמְצֵם אוֹר הָאֱמֶת, שֶׁזֶּה בְּחִינַת מִעוּט הַיָּרֵחַ, עַל־כֵּן מִשָּׁם אֲחִיזַת כָּל הַסִּטְרָא־אָחֳרָא, שֶׁהִיא בְּחִינַת חשֶׁךְ וָשֶׁקֶר, שֶׁאֲחִיזָתָהּ רַק מִמִּעוּט אוֹר הַיָּרֵחַ, הַיְנוּ מִמִּעוּט וְצִמְצוּם אוֹר הָאֱמֶת, שֶׁמִּשָּׁם עִקַּר אֲחִיזַת הַשֶּׁקֶר שֶׁהוּא הַסִּטְרָא־אָחֳרָא. כִּי בְּוַדַּאי אִם לֹא הָיָה רַק עֶצֶם אוֹר הָאֱמֶת בְּעַצְמוֹ, בְּוַדַּאי לֹא הָיָה לְהַסִּטְרָא־אָחֳרָא שֶׁהוּא הַשֶּׁקֶר שׁוּם אֲחִיזָה, כִּי מֵאַחַר שֶׁהָיוּ הַכֹּל יוֹדְעִין עֶצֶם הָאֱמֶת - אֵיךְ הָיָה אֶפְשָׁר לְחַפּוֹת הָאֱמֶת וְלַהֲפֹךְ הָאֱמֶת לְשֶׁקֶר? כִּי בְּוַדַּאי מִי שֶׁיּוֹדֵעַ הָאֱמֶת לַאֲמִתּוֹ, אִי אֶפְשָׁר לְהַטְעוֹתוֹ בְּשׁוּם שֶׁקֶר שֶׁבָּעוֹלָם; אַךְ מֵאַחַר שֶׁנִּתְמַעֵט וְנִתְצַמְצֵם הָאֱמֶת, אַף־עַל־פִּי שֶׁעֲדַיִן הוּא אֱמֶת גָּמוּר, עִם־כָּל־זֶה כְּבָר יֵשׁ לָהֶם אֵיזֶה אֲחִיזָה, מֵאַחַר שֶׁאֵין יוֹדְעִין עֶצֶם הָאֱמֶת, רַק שֶׁרוֹאִין הָאֱמֶת מֵרָחוֹק דֶּרֶךְ כַּמָּה חַלּוֹנוֹת וּלְבוּשִׁין, עַל־יְדֵי־זֶה יֵשׁ לָהֶם אֲחִיזָה לְהַטְעוֹת וּלְחַפּוֹת הָאֱמֶת בְּשֶׁקֶר וְלַהֲפֹךְ הַשֶּׁקֶר לֶאֱמֶת, חַס וְשָׁלוֹם. וְעַל־כֵּן עִקַּר עֲבוֹדָתֵנוּ וִיגִיעָתֵנוּ לְמַלֹּאת פְּגִימַת הַלְּבָנָה, הַיְנוּ לְבָרֵר הָאֱמֶת מִן הַשֶּׁקֶר. וְעַל־ כֵּן עִקַּר הָעֵצָה וְהַתַּקָּנָה בִּכְלָלִיּוּת הָעֲבוֹדָה שֶׁאָנוּ צְרִיכִין בְּזֶה הָעוֹלָם, הָעִקָּר הוּא רַק אֱמֶת, דְּהַיְנוּ שֶׁלֹּא לְהַטְעוֹת אֶת עַצְמוֹ, חַס וְשָׁלוֹם, רַק לְהִסְתַּכֵּל בְּכָל דָּבָר עַל הָאֱמֶת לַאֲמִתּוֹ, וּלְהִשְׁתַּדֵּל בִּתְפִלָּתוֹ, שֶׁאֲפִלּוּ אִם אֵינוֹ יָכוֹל לְהִתְפַּלֵּל כְּלָל, עַל־כָּל־פָּנִים יִרְאֶה שֶׁיּוֹצִיא הַדִּבּוּר מִפִּיו בֶּאֱמֶת לְפִי מַדְרֵגָתוֹ; וְאַף־עַל־פִּי שֶׁעֲדַיִן אֵין הָאֱמֶת בָּרוּר וָזַךְ, עִם־כָּל־זֶה מֵאַחַר שֶׁחָפֵץ בָּאֱמֶת וּמוֹשֵׁךְ עַצְמוֹ רַק אֶל הָאֱמֶת וּמַכְרִיחַ עַצְמוֹ לְדַבֵּר דִּבּוּרֵי אֱמֶת, עַל־כֵּן זֶה הָאֱמֶת הוּא עַל־כָּל־ פָּנִים בִּבְחִינַת חַלּוֹן וְיוּכַל אַחֵר לְהָאִיר בּוֹ, דְּהַיְנוּ הַצַּדִּיקֵי־אֱמֶת, שֶׁהֵם נֶגְדֵּנוּ בִּבְחִינַת עֶצֶם הָאֱמֶת, וְהֵם מְאִירִים בְּכָל תְּפִלּוֹת יִשְׂרָאֵל וּמַעֲלִים אוֹתָם כְּפִי הָאֱמֶת שֶׁבְּכָל תְּפִלָּה שֶׁל כָּל אֶחָד שֶׁהוּא בִּבְחִינַת חַלּוֹן עַל־כָּל־פָּנִים; וּכְפִי בְּהִירוּת וְצַחוּת הַחַלּוֹן, דְּהַיְנוּ הַדִּבּוּר אֱמֶת, כֵּן הַצַּדִּיק שֶׁהוּא עֱצֶם הָאֱמֶת יוּכַל לְהָאִיר בּוֹ (שם אותיות ז ח). 
מג. עִקַּר הַגְּאֻלָּה הוּא עַל־יְדֵי אֱמֶת, שֶׁהוּא מְשִׁיחַ צִדְקֵנוּ שֶׁיָּבוֹא בִּמְהֵרָה בְיָמֵינוּ, שֶׁנִּקְרָא אֱמֶת, כְּמוֹ שֶׁכָּתוּב: "שְׁלַח אוֹרְךָ וַאֲמִתְּךָ וְגוֹ'", וּפֵרְשׁוֹ רַשִׁ"י עַל מָשִׁיחַ, כִּי עִקַּר בִּיאַת הַמָּשִׁיחַ הוּא לְגַלּוֹת הָאֱמֶת בָּעוֹלָם, כִּי עַכְשָׁו הָאֱמֶת בְּגָלוּת גָּדוֹל וְהָאֱמֶת נַעֲשֶׂה עֲדָרִים עֲדָרִים וְכָל אֶחָד אוֹמֵר שֶׁאֶצְלוֹ הָאֱמֶת, וְעִקַּר הָאֱמֶת יִתְגַּלֶּה עַל־יְדֵי מָשִׁיחַ, כְּמוֹ שֶׁכָּתוּב: "שְׂפַת אֱמֶן תִּכּוֹן לָעַד וְגוֹ'", וְדָרְשׁוּ רַבּוֹתֵינוּ זַ"ל: "כּוֹנַנְתָּ

). 
מו. אֵין שְׁתֵּי נְשָׁמוֹת שָׁווֹת בָּעוֹלָם בְּמַדְרֵגָתָן, רַק אֶחָד גָּדוֹל מֵחֲבֵרוֹ. וְעִקַּר הַחִלּוּק וְהַמַּעֲלָה שֶׁבֵּין הַנְּשָׁמוֹת הוּא רַק בִּבְחִינַת הֶאָרַת הָאֱמֶת הַנַּ"ל; כִּי הַנְּשָׁמָה נִקְרֵאת אוֹר, כְּמוֹ שֶׁכָּתוּב: "נֵר ה' נִשְׁמַת אָדָם", וְעִקַּר אוֹר הַנְּשָׁמָה הוּא אֱמֶת, שֶׁהוּא עִקַּר אוֹר הַמֵּאִיר. וְכָל נְשָׁמָה שֶׁיֵּשׁ לָהּ אֱמֶת בְּיוֹתֵר - הִיא גְדוֹלָה בְּיוֹתֵר וּמְאִירָה בְּיוֹתֵר, וְהַקָּטָן צָרִיךְ לְקַבֵּל מֵהַגָּדוֹל מִמֶּנּוּ, כִּי כָל הַנְּשָׁמוֹת מְקַבְּלִין זֶה מִזֶּה מִמַּדְרֵגָה לְמַדְרֵגָה (שם). 
מז. בְּוַדַּאי בְּזֶה הָעוֹלָם לָאו כָּל אָדָם זוֹכֶה לִבְחִינַת אֱמֶת הַבָּרוּר לְגַמְרֵי בִּשְׁלֵמוּת, אַךְ הָעִקָּר כָּל זְמַן שֶׁשּׁוֹמְרִין הָאֱמֶת שֶׁלֹּא יִתְהַפֵּךְ לְשֶׁקֶר, חַס וְשָׁלוֹם, רַק מִסְתַּכְּלִין עַל נְקֻדַּת הָאֱמֶת לַאֲמִתּוֹ, אֲזַי אַף־עַל־פִּי שֶׁאֵין זוֹכִין עֲדַיִן לָאֱמֶת הַבָּרוּר לְגַמְרֵי, לִבְחִינַת עֶצֶם הָאֱמֶת, אַף־עַל־פִּי־כֵן יָכוֹל אַחֵר לְהָאִיר בּוֹ עַל־כָּל־פָּנִים, וִיכוֹלִין ע

). 
פ. צִיצִת וּתְפִלִּין הֵם בְּחִינַת אוֹר הָאֱמֶת כַּמְבֹאָר בִּפְנִים, וְעִקַּר מִצְוָתָם בַּיּוֹם, אֲבָל בַּלַּיְלָה שֶׁאָז תַּרְעֵי דְּגַן־עֵדֶן סְתִימִין וְהַחשֶׁךְ מִתְגַּבֵּר, וְאָז אֵין זְמַן צִיצִת וּתְפִלִּין, כִּי יֵשׁ חשֶׁךְ בְּחִינַת שֶׁקֶר, שֶׁאִי אֶפְשָׁר לְהַגִּיעַ לְשָׁם אוֹר הַצִּיצִת וּתְפִלִּין, וְאָז אֵין תַּקָּנָה כִּי־אִם עַל־יְדֵי הַדִּבּוּר־אֱמֶת, שֶׁזֶּה בְּחִינַת תְּפִלַּת־עַרְבִית שֶׁתִּקֵּן יַעֲקֹב אָבִינוּ דַּיְקָא, שֶׁהוּא עֶצֶם הָאֱמֶת, בְּחִינַת "תִּתֵּן אֱמֶת לְיַעֲקֹב"; וְהוּא הָיָה חָזָק בְּהָאֱמֶת כָּל־כָּךְ, עַד שֶׁהֵאִיר הָאֱמֶת גַּם בְּתֹקֶף חֶשְׁכַת לַיְלָה בְּהִתְגַּבְּרוּת הַחשֶׁךְ וְהַשֶּׁקֶר מְאֹד מְאֹד. וְעַל־ כֵּן תִּקֵּן תְּפִלַּת־עַרְבִית כְּשֶׁבָּרַח מֵעֵשָׂו הָרָשָׁע וְהָלַךְ לְלָבָן הָאֲרַמִּי, שֶׁשְּׁנֵיהֶם בְּחִינַת חשֶׁךְ עָצוּם וְנוֹרָא מְאֹד, וְרָאָה שֶׁהַחשֶׁךְ סְבָבוּהוּ מִכָּל צַד וּמִצִּדֵּי צְדָדִים, וְאָז דַּיְקָא הִתְגַּבֵּר וְתִקֵּן תְּפִלַּת־עַרְבִית, שֶׁעִקַּר תִּקּוּן הַתְּפִלָּה הוּא אֱמֶת, לְהוֹרוֹת שֶׁבְּתֹקֶף הָאֱמֶת שֶׁלּוֹ יָכוֹל לְהָאִיר גַּם בְּחֶשְׁכַת לָיְלָה. וְעַל־כֵּן זָכָה שֶׁהָיְתָה מִטָּתוֹ שְׁלֵמָה בִּבְחִינַת "כֻּלּוֹ זֶרַע אֱמֶת" - הֵפֶךְ יִשְׁמָעֵאל וְעֵשָׂו שֶׁהֵם זֶרַע שֶׁקֶר. וְזֶהוּ שֶׁאוֹמְרִים בַּלַּיְלָה קֹדֶם הַשֵּׁנָה: "בְּיָדְךָ אַפְקִיד רוּחִי, פָּדִיתָה אוֹתִי ה' אֵל אֱמֶת", כִּי בְּתֹקֶף חֶשְׁכַת לַיְלָה צְרִיכִין לְדַבֵּק אֶת עַצְמוֹ אֶל הָאֱמֶת בְּיוֹתֵר. וְעַל־כֵּן תְּפִלַּת־ עַרְבִית שֶׁתִּקֵּן יַעֲקֹב אָבִינוּ - בְּחִינַת עֶצֶם הָאֱמֶת, הוּא רְשׁוּת דַּיְקָא, כִּי עִקַּר תִּקּוּן הַתְּפִלָּה הוּא עַל־יְדֵי אֱמֶת כַּנַּ"ל. אֲבָל בְּתֹקֶף חֶשְׁכַת הַגָּלוּת אִי אֶפְשָׁר לְבָאֵר וּלְפָרֵשׁ הָאֱמֶת, רַק שֶׁכָּל אֶחָד צָרִיךְ לִפְנוֹת אֶל הָאֱמֶת כְּפִי מַה שֶּׁהוּא, בִּבְחִינַת "וְדוֹבֵר אֱמֶת בִּלְבָבוֹ", שֶׁזֶּהוּ בְּחִינַת רְשׁוּת, שֶׁאֵין הָאֱמֶת קָבוּעַ, רַק הַכֹּל כְּפִי הָעִנְיָן וְהַשָּׁעָה, וְכָל אֶחָד כְּפֻם מַה דִּמְשַׁעֵר בְּלִבֵּהּ. וְעַל־כֵּן כְּשֶׁנִּפְסְקָה הַהֲלָכָה 'תְּפִלַּת עַרְבִית - רְשׁוּת', נִתּוֹסְפוּ כַּמָּה מֵאוֹת סַפְסְלֵי בְּבֵית־הַמִּדְרָשׁ כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, כִּי עַל־יְדֵי בְּחִינַת 'תְּפִלַּת עַרְבִית רְשׁוּת', שֶׁתִּקֵּן יַעֲקֹב אָבִינוּ שֶׁהוּא עֶצֶם הָאֱמֶת שֶׁמֵּאִיר בְּתֹקֶף הַחשֶׁךְ לְכָל אֶחָד כְּפִי מַה שֶּׁהוּא בְּאוֹתָהּ הַשָּׁעָה, עַל־יְדֵי־זֶה יְכוֹלִין לְהִתְקָרֵב הַכֹּל לְהַשֵּׁם יִתְבָּרַךְ וּלְהַתּוֹרָה הַקְּדוֹשָׁה, כִּי אֵין שׁוּם חשֶׁךְ שֶׁיַּחְשִׁיךְ לָהֶם, כִּי הוּא מֵאִיר לָהֶם עַל־יְדֵי עֹצֶם אֲמִתָּתוֹ עַד שֶׁמְּקָרֵב כֻּלָּם לְהַשֵּׁם יִתְבָּרַךְ, שֶׁזֶּה בְּחִינַת הַתַּלְמִידִים רַבִּים שֶׁנִּתּוֹסְפוּ אָז (שם אותיות טו, כב). 
פא. עִקַּר הִתְגַּבְּרוּת הַשֶּׁקֶר וְהָרַע וְהַחשֶׁךְ הוּא בְּעִנְיַן הַזִּוּוּג וְהַפַּרְנָסָה, כִּי דַּיְקָא מֵחֲמַת שֶׁיֵּשׁ בָּהֶם קְדֻשָּׁה גְבוֹהָה מְאֹד וְהֵם בִּבְחִינַת אֱמֶת, עַל־כֵּן מִתְגַּבְּרִים הָרַע וְהַשֶּׁקֶר לְהַעְלִים הַקְּדֻשָּׁה וְעֶצֶם הָאֱמֶת שֶׁיֵּשׁ בָּזֶה לְגַמְרֵי. וְעִקַּר הַתִּקּוּן לָזֶה הוּא עַל־יְדֵי הַצַּדִּיק־אֱמֶת, שֶׁמֵּאִיר נְקֻדַּת הָאֱמֶת בְּלֵב כָּל אֶחָד מִיִּשְׂרָאֵל, שֶׁיִּמְשֹׁךְ עַצְמוֹ בְּכָל עֵת רַק אֶל נְקֻדַּת הָאֱמֶת לַאֲמִתּוֹ; וְעַל־יְדֵי־זֶה זוֹכִין לָצֵאת מִתּוֹךְ הַחשֶׁךְ לְאוֹר גָּדוֹל, וְזוֹכִין לְזִוּוּג וּפַרְנָסָה בִּ

). 
פד. עַל־יְדֵי צְדָקָה עוֹלִין וּמִתְקַדְּשִׁין מִטֻּמְאַת הַשֶּׁקֶר לְתַכְלִית הַקְּדֻשָּׁה, שֶׁהוּא בְּחִינַת קֹדֶשׁ (שם הלכות קידושין, הלכה ה). 
פה. עִקַּר תִּקּוּן שְׁלֵמוּת הָעֵצָה לֵידַע בְּאֵיזֶה דֶּרֶךְ לֵילֵךְ, הוּא עַל־יְדֵי הָאֱמֶת, הַיְנוּ שֶׁיִּמְשֹׁךְ עַצְמוֹ רַק אֶל הָאֱמֶת לַאֲמִתּוֹ וּלְבַקֵּשׁ מֵהַשֵּׁם יִתְבָּרַךְ שֶׁיּוֹלִיכֵהוּ וְיַד

). 
ח. מְבֹאָר בִּכְתָבִים שֶׁמַּלְכוּת שֶׁהוּא בְּחִינַת מַדְרֵגָה אַחֲרוֹנָה שֶׁל עוֹלָם הָעֶלְיוֹן, כְּגוֹן מַלְכוּת דִּבְרִיאָה, הוּא לְמַעְלָה וְהוּא שֹׁרֶשׁ כָּל בְּחִינַת עַתִּיק שֶׁהוּא מַדְרֵגָה הָעֶלְיוֹנָה שֶׁבָּעוֹלָם הַתַּחְתּוֹן מִמֶּנּוּ, בְּחִינַת עַתִּיק דִּיצִירָה, וְכֵן מֵעוֹלָם לְעוֹלָם. וּמַלְכוּת הוּא בְּחִינַת אֱמוּנָה, וְעַתִּיק שֶׁהוּא לְמַעְלָה וְשֹׁרֶשׁ כָּל הַמֹּחִין שֶׁבְּאוֹתוֹ עוֹלָם, הוּא בְּחִינַת דְּבֵקוּת נִפְלָא וְנוֹרָא לְהַשֵּׁם יִתְבָּרַךְ, בְּחִינַת רַעֲוָא דְּרַעֲוִין, רָצוֹן שֶׁבָּרְצוֹנוֹת, שֶׁהוּא בְּחִינַת הַדְּבֵקוּת הַנִּפְלָא וְהַנּוֹרָא לְהַשֵּׁם יִתְבָּרַךְ, בְּחִינַת "צָמְאָה לְךָ נַפְשִׁי וְגוֹ'", שֶׁזֶּה בְּחִינַת הַדְּבֵקוּת שֶׁל הַתְּפִלִּין, בְּחִינַת "שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ וְגוֹ' כִּי עַזָּה כַמָּוֶת אַהֲבָה... רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ וְגוֹ'" - אַשְׁרֵי הַזּוֹכֶה לָזֶה. אֲבָל הַדְּבֵקוּת הַזֹּאת שֶׁבְּאוֹתוֹ עוֹלָם וּמַדְרֵגָה הוּא לְמַטָּה מִבְּחִינַת מַלְכוּת, בְּחִינַת אֱמוּנָה שֶׁל מַדְרֵגָה וְעוֹלָם הַגָּבֹהַּ יוֹתֵר כַּנַּ"ל. עַל־כֵּן עִקַּר הַהַתְחָלָה הוּא אֱמוּנָה, וְהַסּוֹף הוּא דְּבֵקוּת וֶאֱמוּנָה שֶׁל מַעְלָה; כְּגוֹן לְמָשָׁל בְּעוֹלַם הָעֲשִׂיָּה, בְּוַדַּאי הַתְחָלַת עֲבוֹדַת יִשְׂרָאֵל הוּא אֱמוּנָה, וְעַל־יְדֵי־זֶה זוֹכֶה לֵילֵךְ מִדַּרְגָּא לְדַרְגָּא עַד שֶׁמַּגִּיעַ לִבְחִינַת עַתִּיק שֶׁבַּעֲשִׂיָּה, שֶׁהוּא בְּחִינַת רָצוֹן וּדְבֵקוּת, בְּחִינַת שֹׁרֶשׁ הַמֹּחִין שֶׁבַּעֲשִׂיָּה, וְעַל־יְדֵי מֹחִין וּדְבֵקוּת אֵלּוּ זוֹכֶה לָבוֹא לִבְחִינַת אֱמוּנָה שֶׁבָּעוֹלָם הַגָּבֹהַּ מִמֶּנּוּ, בְּחִינַת מַלְכוּת אֱמוּנָה שֶׁבִּיצִירָה; וְאַחַר־כָּךְ הוּא עוֹלֶה עוֹד מִדַּרְגָּא לְדַרְגָּא עַד שֶׁמַּשִּׂיג בְּחִינַת עַתִּיק שֶׁבִּיצִירָה וֶאֱמוּנָה שֶׁבִּבְרִיאָה, וְכֵן מֵעוֹלָם לְעוֹלָם; כִּי אֱמוּנָה בְּחִינַת מַלְכוּת שֶׁל עוֹלָם הָעֶלְיוֹן הוּא שֹׁרֶשׁ הַחַיּוּת שֶׁל בְּחִינַת עַתִּיק, שֶׁהוּא בְּחִינַת שֹׁרֶשׁ הַמֹּחִין שֶׁבָּעוֹלָם הַתַּחְתּוֹן מִמֶּנּוּ, וְהַמֹּחִין אֵלּוּ הֵם הַחַיּוּת שֶׁל בְּחִינַת מַלְכוּת וֶאֱמוּנָה שֶׁבְּזֶה הָעוֹלָם וְהַמַּדְרֵגָה (שם). 
ט. עַצְבוּת וְעַצְלוּת וּכְבֵדוּת נִמְשָׁךְ מֵהָרַע שֶׁבִּיסוֹד הֶעָפָר שֶׁהוּא עִקַּר נְשִׁיכַת הַנָּחָשׁ, בְּחִינַת "וְנָחָשׁ עָפָר לַחְמוֹ"; וְהַכְנָעָתוֹ עַל־יְדֵי יְסוֹד הֶעָפָר

). 
ל. שְׁלֵמוּת הָאֱמוּנָה צְרִיכִין לְהַמְשִׁיךְ עַל עַצְמוֹ בְּכָל יוֹם מֵחָדָשׁ, כִּי הַקָּדוֹשׁ־ בָּרוּךְ־הוּא מְחַדֵּשׁ בְּכָל יוֹם תָּמִיד מַעֲשֵׂה בְרֵאשִׁית, וְעִקַּר הַבְּרִיאָה הָיָה בְּגִין דְּיִשְׁתְּמוֹדְעוּן לֵהּ. וְכֵן גַּם עַכְשָׁו הַשֵּׁם יִתְבָּרַךְ מְסִבּוֹת מִתְהַפֵּךְ בְּתַחְבּוּלוֹתָיו וּמַזְמִין לְכָל אָדָם בְּכָל יוֹם תָּמִיד מַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה בְּאֹפֶן שֶׁיִּזְכֶּה עַל־יְדֵי־זֶה לְהִתְחַזֵּק בֶּאֱמוּנָה יוֹתֵר וּלְהַכִּיר אוֹתוֹ יִתְבָּרַךְ בְּהַכָּרָה יְתֵרָה בְּיוֹתֵר, וְרַק בִּשְׁבִיל זֶה הַשֵּׁם יִתְבָּרַךְ מְחַדֵּשׁ חִדּוּשׁ מַעֲשֵׂה בְרֵאשִׁית בְּכָל יוֹם כְּדֵי לְהַמְשִׁיךְ אֱמוּנַת חִדּוּשׁ הָעוֹלָם בְּכָל יוֹם בְּהִתְגַּלּוּת יוֹתֵר. וְזֶה בְּחִינַת "חֲדָשִׁים לַבְּקָרִים רַבָּה אֱמוּנָתֶךָ" - שֶׁהָאֱמוּנָה הַקְּדוֹשָׁה מִתְחַדֶּשֶׁת וּמִתְחַזֶּקֶת בְּכָל יוֹם כְּפִי חִדּוּשׁ מַעֲשֵׂה בְרֵאשִׁית שֶׁבְּאוֹתוֹ הַיּוֹם, אֲבָל אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹקִים בִּשְׁבִיל כֹּחַ הַבְּחִירָה; וְעַל־כֵּן הַסִּטְרָא־אָחֳרָא וְהַקְּלִפּוֹת מִתְגַּבְּרִין בְּכָל יוֹם גַּם־כֵּן לְהַעְלִים הָאֱמוּנָה הַקְּדוֹשָׁה וּלְבַלְבֵּל אוֹתָהּ, חַס וְשָׁלוֹם, כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל: בְּכָל יוֹם יִצְרוֹ שֶׁל אָדָם מִתְגַּבֵּר וּמִתְחַדֵּשׁ עָלָיו. וְעִקַּר הַיֵּצֶר הָרָע הוּא בְּחִינַת כְּפִירוֹת כַּיָּדוּעַ, וּבִשְׁבִיל זֶה צְרִיכִין לְהִשְׁתַּדֵּל מְאֹד לְהִתְקָרֵב בְּכָל דּוֹר לְהַצַּדִּיקִים אֲמִתִּיִּים שֶׁבְּזֶה הַדּוֹר דַּיְקָא, וְאֵין דַּי בְּהַסְּפָרִים שֶׁל הַצַּדִּיקִים הַקּוֹדְמִים וְכֵן בְּמַה שֶּׁכְּלַל יִשְׂרָאֵל זָכוּ לֶאֱמוּנָה שְׁלֵמָה עַל־יְדֵי משֶׁה רַבֵּנוּ, עָלָיו הַשָּׁלוֹם, בִּפְרָט עַל־יְדֵי קַבָּלַת־הַתּוֹרָה, שֶׁאָז נִתְבָּרֵר הַמְדַמֶּה עַל־יְדֵי שֶׁזָּכוּ כֻּלָּם לְרוּחַ־הַקֹּדֶשׁ וְעַל־יְדֵי־זֶה נִשְׁלְמָה הָאֱמוּנָה בְּאוֹר גָּדוֹל, אַף־עַל־פִּי־כֵן צְרִיכִין בְּכָל דּוֹר לְהִתְקָרֵב דַּיְקָא לְצַדִּיק־ אֱמֶת שֶׁבְּזֶה הַדּוֹר כְּדֵי שֶׁיְּבָרֵר לָנוּ הַמְדַמֶּה וִיזַכֶּה אוֹתָנוּ לֶאֱמוּנָה שְׁלֵמָה בְּכָל יוֹם וָיוֹם כְּפִי חִדּוּשׁ מַעֲשֵׂה בְרֵאשִׁית שֶׁבְּכָל יוֹם, וּלְבַטֵּל הַקְּלִפָּה וְהַסִּטְרָא־אָחֳרָא הַמִּתְגַּבֶּרֶת כְּנֶגֶד הָאֱמוּנָה הַקְּדוֹשָׁה בְּכָל יוֹם מֵחָדָשׁ כַּנַּ"ל. וְזֶה הָיָה הָעִנְיָן מַה שֶּׁאַחַר מַתַּן־תּוֹרָה בְּהִתְגַּלּוּת נִפְלָא כָּזֶה כְּתִיב: "וַיַּרְא הָעָם כִּי בשֵׁשׁ משֶׁה וְגוֹ', כִּי זֶה משֶׁה הָאִישׁ ... לֹא יָדַעְנוּ מֶה־הָיָה לוֹ", וְעַל־יְדֵי־זֶה נִכְשְׁלוּ בְּחֵטְא הָעֵגֶל. וְכָל זֶה מֵחֲמַת כִּי גָדוֹל כֹּחַ הַבְּחִירָה, כִּי כָל הַבְּרִיאָה הָיְתָה רַק בִּשְׁבִיל זֶה, וְהַבַּעַל־דָּבָר מִתְגַּבֵּר אֶת עַצְמוֹ עַל הָאָדָם בְּכָל יוֹם מֵחָדָשׁ. וְאָז בְּאוֹתוֹ הַיּוֹם דַּיְקָא שֶׁהָיָה יוֹם מוּכָן לְפֻרְעָנֻיּוֹת, הָיָה הִתְגַּבְּרוּת הַסִּטְרָא־אָחֳרָא כָּל־כָּךְ עַד שֶׁלֹּא הָיָה כֹּחַ לְבַטְּלָהּ כִּי־אִם משֶׁה בְּעַצְמוֹ אִם הָיָה שָׁם, שֶׁהוּא הָיָה הַצַּדִּיק הַדּוֹר אָז. וְעַל־כֵּן בֶּאֱמֶת כְּשֶׁיָּרַד משֶׁה מִן הָהָר הִכְנִיעַ וְשִׁבֵּר וּבִטֵּל אֶת הָעֵגֶל וְחָזַר וְקִבֵּל אֶת הַלּוּחוֹת הָאַחֲרוֹנוֹת וְחָזַר לְחַזֵּק הָאֱמוּנָה הַקְּדוֹשָׁה, אֲבָל גַּם אָז הַכֹּל הָיָה בְּכֹחַ הָרְשִׁימָה שֶׁנִּשְׁאֲרָה מִיסוֹד הָאֱמוּנָה שֶׁנִּקְבַּע בְּלֵב יִשְׂרָאֵל בִּשְׁעַת מַתַּן־תּוֹרָה, בִּשְׁעַת קַבָּלַת לוּחוֹת הָרִאשׁוֹנוֹת, כִּי עַל־יְדֵי יְסוֹד הָאֱמוּנָה הַזֹּאת יֵשׁ כֹּחַ לְכָל צַדִּיק וְצַדִּיק בְּדוֹרוֹ לְבָרֵר לְיִשְׂרָאֵל אֶת הָאֱמוּנָה הַקְּדוֹשָׁה, כִּי עַל־יְדֵי יְסוֹד אֱמוּנָה זֹאת זוֹכִין יִשְׂרָאֵל בְּכָל דּוֹר לְהִתְקָרֵב לְצַדִּיק־הָאֱמֶת וּלְבַקֵּשׁ וּלְחַפֵּשׂ אוֹתוֹ עַד שֶׁמּוֹצְאִין אוֹתוֹ כְּדֵי שֶׁנִּזְכֶּה לְבָרֵר לָנוּ הָאֱמוּנָה הַקְּדוֹשָׁה בְּכָל פַּעַם כְּפִי הַיּוֹם וְהַשָּׁעָה כַּנַּ"ל (שם אותיות לב לג). 
לא. עַל־יְדֵי אֱמוּנָה נִכְנָסִים אֶל הַשֵּׂכֶל וְנִשְׁלָם הַדַּעַת, וְעַל־יְדֵי־זֶה יְכוֹלִין לִדְרשׁ אֶת הַתּוֹרָה, כִּי כְּשֶׁאֵין אֱמוּנָתוֹ בִּשְׁלֵמוּת, אָז דַּעְתּוֹ וְשִׂכְלוֹ אָסוּר כְּמוֹ בְּכַבְלֵי בַרְזֶל בַּשִּׁבְיָה וּבְבֵית־הָאֲסוּרִים, כִּי שֵׂכֶל הָאֱנוֹשִׁי קָצָר מִלְּהַשִּׂיג שׁוּם דָּבָר עַל בֻּרְיוֹ וּמְכוֹנוֹ. וְעַל־כֵּן כָּל חַכְמֵי הַמְחַקְּרִים תּוֹעִים וּנְבוּכִים הַרְבֵּה בְּכָל הַחָכְמוֹת שֶׁלָּהֶם, כִּי עֲדַיִן אֵין שׁוּם חָכְמָה בְּרוּרָה אֶצְלָם, וְיֵשׁ בֵּינֵיהֶם סְפֵקוֹת וּמַחֲלֹקֶת הַרְבֵּה וּמְבוּכוֹת עֲצוּמוֹת בְּכָל חָכְמוֹתֵיהֶם כַּיָּדוּעַ לְבָקִי בָּהֶם, וְכָל זֶה מֵחֲמַת שֶׁעַל־יְדֵי שֵׂכֶל אֱנוֹשִׁי אִי אֶפְשָׁר לְהַשִּׂיג שׁוּם דָּבָר עַל בֻּרְיוֹ וַאֲמִתָּתוֹ. וְעַל־כֵּן כַּאֲשֶׁר נִכְנָס לְאֵיזֶה חָכְמָה בְּלִי אֱמוּנָה, חַס וְשָׁלוֹם, הֲרֵי שִׂכְלוֹ כְּמוֹ אָסוּר וְתָפוּס בִּתְפִיסָה שֶׁאֵינוֹ יָכוֹל לָצֵאת מִשָּׁם, כִּי דַּעְתּוֹ נִשְׁאָר נָבוֹךְ וְתָפוּס בְּמַה שֶּׁמְּעַיֵּן בּוֹ, וְאֵינוֹ יָכוֹל לָצֵאת מִשָּׁם בְּשָׁלוֹם; אֲבָל כְּשֶׁיֵּשׁ לוֹ אֱמוּנָה שֶׁהוּא בְּחִינַת שַׁבָּת, בְּחִינַת עוֹלַם הַחֵרוּת, אָז דַּעְתּוֹ בֶּן־חוֹרִין כִּי יוֹדֵעַ כָּל הַדְּבָרִים עַל בֻּרְיָן עַל־יְדֵי הָאֱמוּנָה לְבַד, עַל־יְדֵי שֶׁמַּאֲמִין לְדִבְרֵי רַבּוֹתֵינוּ וַאֲבוֹתֵינוּ הַקְּדוֹשִׁים שֶׁזָּכוּ לְהַשִּׂיג הַכֹּל עַל־יְדֵי נְבוּאָה וְשֶׁפַע אֱלֹקִי שֶׁהוּא לְמַעְלָה מְאֹד מִשֵּׂכֶל אֱנוֹשִׁי, וְאָז יֵשׁ לוֹ יְסוֹד לַעֲמֹד עָלָיו, שֶׁהוּא הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁעָלֶיהָ עוֹמֵד הַכֹּל, וְעַל־ יְדֵי־זֶה יָכוֹל לִכְנֹס לְכָל דְּרוּשֵׁי הַתּוֹרָה וְלָצֵאת מֵהֶם בְּשָׁלוֹם, מֵאַחַר שֶׁיֵּשׁ לוֹ יְסוֹדוֹת חֲזָקִים עַל־יְדֵי הָאֱמ

). 
לג. הַסִּטְרָא־אָחֳרָא מִתְעוֹרֶרֶת בְּכָל פַּעַם לַעֲקֹר, חַס וְשָׁלוֹם, אֶת הַכֹּל וְלַהֲרֹס עַד הַיְסוֹד, חַס וְשָׁלוֹם, אֲבָל הַשֵּׁם לֹא יַעַזְבֵנוּ בְּיָדוֹ, כִּי כְבָר יֵשׁ לָנוּ יְסוֹד חָזָק, שֶׁאָנוּ בְּנֵי אַבְרָהָם יִצְחָק וְיַעֲקֹב, וּכְבָר קִבַּלְנוּ אֶת הַתּוֹרָה הַקְּדוֹשָׁה וְאָנוּ חֲזָקִים בֶּאֱמוּנָתֵנוּ הַקְּדוֹשָׁה וּמִתְפָּאֲרִים בָּהּ מְאֹד וְאוֹמְרִים בְּכָל יוֹם: "אַשְׁרֵינוּ מַה טּוֹב חֶלְקֵנוּ וְכוּ'", עַל־כֵּן כָּל אֶחָד מִיִּשְׂרָאֵל צָרִיךְ לְהַחֲיוֹת וּלְחַזֵּק אֶת עַצְמוֹ עַל־יְדֵי יְסוֹד הָאֱמוּנָה שֶׁיֵּשׁ בּוֹ, שֶׁזֶּה עִקַּר הַיְסוֹד שֶׁעָלֶיהָ עוֹמֶדֶת כָּל הַתּוֹרָה כֻּלָּהּ, שֶׁזֶּה בְּחִינַת זְכִירַת יְצִיאַת־מִצְרַיִם וּמַתַּן־ תּוֹרָה שֶׁאָנוּ צְרִיכִין בְּכָל יוֹם, כִּי זֶה יְסוֹד קְדֻשָּׁתֵנוּ. וְכֵן בְּכָל דּוֹר וָדוֹר בָּאִים צַדִּיקִים גְּדוֹלִים וּמְיַסְּדִים לָנוּ יְסוֹדוֹת חֲזָקִים שֶׁאִי אֶפְשָׁר לְהָרְסָם בְּשׁוּם אֹפֶן, כִּי צַדִּיק יְסוֹד עוֹלָם, שֶׁזֶּהוּ בְּחִינַת קְדֻשַּׁת הַיְסוֹד שֶׁל מְקוֹם הַבֵּית־הַמִּקְדָּשׁ שֶׁהִתְיַגַּע דָּוִד הַרְבֵּה מְאֹד עַד שֶׁמְּצָאוֹ, כִּי הָעִקָּר הוּא הַיְסוֹד שֶׁל הַקְּדֻשָּׁה, כִּי אַף־עַל־פִּי שֶׁכְּבָר נֶחֱרַב הַבֵּית־הַמִּקְדָּשׁ פַּעֲמַיִם - לֹא נֶחֱרַב אֶלָּא הַבִּנְיָן שֶׁעַל הַיְסוֹד, אֲבָל הַיְסוֹד עַצְמוֹ אִי אֶפְשָׁר לַהֲרֹס לְעוֹלָם, וְזֶה כָּל נֶחָמוֹתֵינוּ וְתִקְווֹתֵינוּ שֶׁעַל יְסוֹד הַקְּדֻשָּׁה הַזֶּה יִבָּנֶה בִּמְהֵרָה בְיָמֵינוּ הַבַּיִת הָאַחֲרוֹן שֶׁיִּתְקַיֵּם לְעוֹלָם (שם אותיות סח סט). 
לד. כָּל זְמַן שֶׁלֹּא זָכָה הָאָדָם לֵידַע מִי הוּא הַצַּדִּיק הָאֱמֶת שֶׁצָּרִיךְ לְהִתְקָרֵב אֵלָיו וּלְהִתְדַּבֵּק בּוֹ, אֲזַי צָרִיךְ לְהַאֲמִין וּלְהִתְדַּבֵּק בְּכָל הַצַּדִּיקִים אַף־עַל־פִּי שֶׁחוֹלְקִין זֶה עַל זֶה; לֹא כְמוֹ הַלֵּיצָנִים שֶׁאוֹמְרִים, שֶׁמֵּאַחַר שֶׁחוֹלְקִים הַצַּדִּיקִים זֶה עַל זֶה, הוּא שׁוֹמֵעַ דִּבְרֵי שְׁנֵיהֶם וְחוֹלֵק עַל שְׁנֵיהֶם, כִּי זֶהוּ דִּבְרֵי לֵיצָנוּת וְנוֹגְעִין בִּכְפִירוֹת, רַחֲמָנָא לִצְּלַן, רַק הָאֱמֶת הוּא לְהֵפֶךְ, שֶׁצָּרִיךְ לְהַאֲמִין בְּכֻלָּם וְלִבְלִי לְהִסְתַּכֵּל כְּלָל עַל הַמַּחֲלֹקֶת שֶׁבֵּינֵיהֶם, מֵאַחַר שֶׁכֻּלָּם מַזְהִירִים אוֹתוֹ לְקַיֵּם תּוֹרַת משֶׁה שֶׁבִּכְתָב וְשֶׁבְּעַל־ פֶּה, כִּי רַק מֵהָאֲנָשִׁים הַכּוֹפְרִים הַהוֹלְכִים בְּדַרְכֵי הַחֲקִירוֹת הָרוֹצִים לְהַטּוֹת מִתּוֹרַת משֶׁה לִלְמֹד חָכְמוֹת חִיצוֹנִיּוֹת וְכוּ', מֵהֶן צְרִיכִין לְהִתְרַחֵק בְּתַכְלִית הָרִחוּק, אֲבָל כָּל מִי שֶׁמַּנְהִיג עַל־פִּי הַתּוֹרָה כְּפִי שֶׁמָּסְרוּ לָנוּ רַבּוֹתֵינוּ הַקְּדוֹשִׁים בִּגְמָרָא וּפוֹסְקִים וְסִפְרֵי יְרֵאִים הַמְיֻסָּדִים עַל פִּי דִּבְרֵיהֶם הַקְּדוֹשִׁים, בָּהֶם צְרִיכִים לְהִתְדַּבֵּק בְּכֻלָּם, כְּמוֹ שֶׁכָּתוּב: "וּבוֹ תִדְבָּק", וְאָמְרוּ רַבּוֹתֵינוּ זַ"ל: הִדָּבֵק בְּתַלְמִידֵי־חֲכָמִים. וְזֶה בְּחִינַת יוֹםשׂטוֹב שֵׁנִי גָּלֻיּוֹת, כִּי כְּמוֹ שֶׁמַּחְמִירִין מֵחֲמַת סָפֵק וְעוֹשִׂין שְׁנֵי יָמִים טוֹבִים, כְּמוֹ־כֵן צְרִיכִין מֵחֲמַת סָפֵק לְהִתְקָרֵב לְכָל הַצַּדִּיקִים הַהוֹלְכִים עַל־פִּי הַתּוֹרָה, כִּי קְדֻשַּׁת יוֹם־טוֹב הוּא בְּחִינַת קְדֻשַּׁת

). 
לה. כְּשֶׁמְּגָרְשִׁין אֶת הָאָדָם מֵהַגַּן־עֵדֶן, הַיְנוּ שֶׁכָּל מַה שֶּׁרוֹצֶה לַעֲשׂוֹת אֵיזֶה דָּבָר שֶׁבִּקְדֻשָּׁה שֶׁהוּא בְּחִינַת כְּנִיסָה לְגַן־עֵדֶן, מְגָרְשִׁין אוֹתוֹ וּמְבַלְבְּלִין אוֹתוֹ - עִקַּר תַּקָּנָתוֹ שֶׁיַּעֲמֹד עַצְמוֹ אֵצֶל אֱמוּנָה שֶׁהוּא בְּחִינַת שַׁבָּת, הַיְנוּ שֶׁאַף־עַל־פִּי־כֵן יַאֲמִין שֶׁהַשֵּׁם יִתְבָּרַךְ מוֹשֵׁל בַּכֹּל וְיָדוֹ עַל הָעֶלְיוֹנָה, וְסוֹף כָּל סוֹף יִגְמֹר אֶת שֶׁלּוֹ וְיִהְיֶה הַכֹּל כִּרְצוֹנוֹ יִתְבָּרַךְ, כִּי יֵשׁ תְּשׁוּבָה בָּעוֹלָם. וְאַף־עַל־פִּי שֶׁהוּא רָחוֹק עֲדַיִן מִתְּשׁוּבָה, אַדְּרַבָּא מִתְגָּרִין בּוֹ עַד שֶׁפּוֹגֵם בְּכָל יוֹם יוֹתֵר, חַס וְשָׁלוֹם, אַף־עַל־פִּי־כֵן עַל־כָּל־פָּנִים הוּא מַאֲמִין שֶׁיֵּשׁ בְּחִינַת תְּשׁוּבָה, בְּחִינַת שַׁבַּת־אֱמוּנָה, שֶׁעַל־יְדֵי־זֶה נִתְתַּקֵּן הַכֹּל, כִּי אֱמוּנָה מְתַקֵּן הַכֹּל, וְעַל־כֵּן צָרִיךְ לְהַעֲמִיד עַצְמוֹ אֵצֶל אֱמוּנָה שֶׁהוּא בְּחִינַת שַׁבָּת, וְאַחַר־כָּךְ זוֹכֶה לְהַשִּׂיג וּלְהָבִין אֵיךְ לְסַדֵּר וּלְתַקֵּן כָּל תִּקּוּנֵי הַשְּׁכִינָה בְּחִינַת "מִטָּה שֻׁלְחָן כִּסֵּא וּמְנוֹרָה" הַמִּתְתַּקְּנִים עַל־יְדֵי קְדֻשַּׁת שַׁבָּת (שם הל' שבת, הל' ד). 
לו. הָעִקָּר הוּא אֱמוּנַת חֲכָמִים, כִּי הָעִקָּר הוּא הַתַּכְלִית. וְצָרִיךְ כָּל אָדָם לָחוּס עַל עַצְמוֹ וְלַחְשֹׁב תָּמִיד בְּכָל יוֹם עַל תַּכְלִיתוֹ הַנִּצְחִי וּמַה יִּהְיֶה סוֹפוֹ וְכוּ'. וְלִזְכּוֹת לְתַכְלִית הַטּוֹב בֶּאֱמֶת אִי אֶפְשָׁר כִּי־אִם עַל־יְדֵי אֱמוּנַת חֲכָמִים, כִּי אִי אֶפְשָׁר לְהָאָדָם לְהַגִּיעַ וְלַחֲזֹר לִמְקוֹר נִשְׁמָתוֹ כִּי־אִם עַל־יְדֵי הַחֲכָמִים הַצַּדִּיקִים אֲמִתִּיִּים, כִּי אֲפִלּוּ כְּשֵׁרִים וִירֵאִים וְעוֹסְקִים בַּתּוֹרָה אֵינָם יְכוֹלִים לְהַגִּיעַ לִשְׁלֵמוּתָם כִּי־אִם עַל־יְדֵי הַחֲכָמִים וְהַצַּדִּיקִים אֲמִתִּיִּים. מִכָּל־שֶׁכֵּן מִי שֶׁפָּגַם אֵיזֶה פְּגָם, מִכָּל־שֶׁכֵּן מִי שֶׁפָּגַם וְעָבַר הַרְבֵּה, חַס וְשָׁלוֹם, כַּמָּצוּי עַכְשָׁו בַּעֲו?ֹנוֹתֵינוּ הָרַבִּים, בְּוַדַּאי אִי אֶפְשָׁר לְרַפֹּאתוֹ בְּגוּף וָנֶפֶשׁ כִּי־אִם עַל־יְדֵי הַצַּדִּיקִים הַגְּדוֹלִים וְהַנִּפְלָאִים בֶּאֱמֶת שֶׁיּוֹדְעִים לִדְרשׁ אֶת הַתּוֹרָה בִּשְׁלֵמוּת בֶּאֱמֶת וְיוֹדְעִים שָׁרְשֵׁי נְפָשׁוֹת שֶׁל כָּל כָּל אֶחָד מִיִּשְׂרָאֵל בְּהַתּוֹרָה, וְיוֹדְעִים לְפָרֵשׁ וּלְבָאֵר כָּל הַדְּרָכִים וְהָעֵצוֹת וְהַנְּתִיבוֹת וְהַתַּחְבּוּלוֹת שֶׁצָּרִיךְ כָּל אָדָם שֶׁבָּעוֹלָם הָרוֹצֶה לָגֶשֶׁת אֶל הַקֹּדֶשׁ, בְּאֹפֶן שֶׁיּוּכַל כָּל אֶחָד לְקַבֵּל רְפוּאָה לְכָל מִינֵי

). 
לז. לָבוֹא לֶאֱמוּנַת חֲכָמִים הוּא עַל־יְדֵי נֶדֶר. כִּי מַה שֶּׁהַרְבֵּה רְחוֹקִים מֵאֱמוּנַת חֲכָמִים אֲמִתִּיִּים הוּא רַק מֵחֲמַת חָכְמוֹת עוֹלָם הַזֶּה, שֶׁהֵם חָכְמוֹת שֶׁל הֶבֶל שֶׁיֵּשׁ לְכָל אֶחָד, וְכָל אֶחָד הוּא חָכָם בְּעֵינָיו. וּבֶאֱמֶת מִי שֶׁיֵּשׁ לוֹ מֹחַ בְּקָדְקֳדוֹ יָכוֹל לְהָבִין בְּקַל שֶׁכָּל הַחָכְמוֹת שֶׁל הָעוֹלָם הַזֶּה הֵם שְׁטוּתִים וַהֲבָלִים וְאֵינָם בִּכְלַל חָכְמָה כְּלָל, כִּי מֵאַחַר שֶׁעַל־יָדָם אֵינוֹ יָכוֹל לָבוֹא לְתַכְלִיתוֹ הָאֲמִתִּי וְהַנִּצְחִי שֶׁהוּא הָעִקָּר, כְּמוֹ שֶׁכָּתוּב: "הִנֵּה בִדְבַר ה' מָאָסוּ, וְחָכְמַת־מֶה לָהֶם", וּכְתִיב: "אַל יִתְהַלֵּל חָכָם בְּחָכְמָתוֹ וְגוֹ', כִּי אִם בְּזֹאת יִתְהַלֵּל הַמִּתְהַלֵּל הַשְׂכֵּל וְיָדֹעַ אוֹתִי". כִּי עִקַּר הַחָכְמָה הָאֲמִתִּית הִיא חָכְמַת הַצַּדִּיקִים הַגְּדוֹלִים שֶׁזָּכוּ לַחְשֹׁב בֶּאֱמֶת עַל תַּכְלִיתָם הַנִּצְחִי, כִּי זֶה עִקַּר הַחָכְמָה בֶּאֱמֶת, בִּבְחִינַת "אֵיזֶהוּ חָכָם? הָרוֹאֶה אֶת הַנּוֹלָד", שֶׁצָּרִיךְ כָּל אֶחָד לְהַשְׂכִּיל עַל דְּרָכָיו וּלְהִתְיַשֵּׁב הֵיטֵב מַה יִּהְיֶה נוֹלָד מִמַּעֲשָׂיו וַעֲסָקָיו בַּסּוֹף הָאַחֲרוֹן, אֲשֶׁר לָזֶה אֵין זוֹכִים בְּשׁוּם חָכְמָה שֶׁבָּעוֹלָם, כִּי־אִם עַל־יְדֵי חָכְמַת הַצַּדִּיקִים אֲמִתִּיִּים שֶׁעִקַּר חָכְמָתָם הוּא לְהִשְׁתַּדֵּל לִפְרשׁ אֶת עַצְמָם מִזֶּה הָעוֹלָם לְגַמְרֵי עַד שֶׁזָּכוּ לָזֶה בִּשְׁלֵמוּת, שֶׁשִּׁבְּרוּ כָּל הַתַּאֲווֹת בְּתַכְלִית עַד קָצֵה הָאַחֲרוֹן וְלֹא נִשְׁאַר לָהֶם שׁוּם נִדְנוּד רֵיחַ מִשּׁוּם תַּאֲוָה שֶׁל זֶה הָעוֹלָם, וְרַק צַדִּיקִים כָּאֵלּוּ הֵם יְכוֹלִין לְתַקֵּן כָּל הָעוֹלָם וּלְהַחֲזִירָם לְמוּטָב כָּל מִי שֶׁרוֹצֶה לְהִתְדַּבֵּק בָּהֶם; כִּי כָל אָדָם צָרִיךְ לְהַגִּיעַ לָזֶה, לְתַכְלִית הַפְּרִישׁוּת וְהַקְּדֻשָּׁה בֶּאֱמֶת, וְזֶה עִקַּר תַּכְלִיתוֹ לָנֶצַח, אֲבָל לָאו כָּל אָדָם זוֹכֶה לָזֶה, וּזְעִירִין אִנּוּן דְּזָכַיִן לָזֶה בִּשְׁלֵמוּת בֶּאֱמֶת, עַל־כֵּן עִקַּר הַתִּקּוּן שֶׁל שְׁאָר כָּל אָדָם הוּא עַל־יְדֵי הַהִתְקָרְבוּת לְצַדִּיקִים אֲמִתִּיִּים, לָהֶם וּלְתַלְמִידֵיהֶם וְכוּ', כִּי הַצַּדִּיקִים הָאֲמִתִּיִּים יְכוֹלִים לְתַקֵּן וּלְרַפֹּאת כָּל אָדָם שֶׁבָּעוֹלָם אַף־עַל־פִּי שֶׁהוּא חוֹלֶה גָדוֹל בְּנֶפֶשׁ וָגוּף, כִּי כְמוֹ שֶׁהַמְבַזֶּה תַּלְמִיד־חָכָם - אֵין לוֹ רְפוּאָה לְמַכָּתוֹ כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, כְּמוֹ־כֵן לְהֵפֶךְ, מִדָּה טוֹבָה מְרֻבָּה, שֶׁהַמַּאֲמִין בְּצַדִּיקִים וְתַלְמִידֵיהֶם שֶׁהֵם בֶּאֱמֶת תַּלְמִידֵי־חֲכָמִים אֲמִתִּיִּים - אֵין מַכָּה בָּעוֹלָם בְּגוּף וָנֶפֶשׁ שֶׁלֹּא יְקַבֵּל רְפוּאָה עַל־יָדָם בִּבְחִינַת "וּלְכָל בְּשָׂרוֹ מַרְפֵּא" הַנֶּאֱמָר בְּכָל הַתּוֹרָה; כִּי עִקַּר הַתּוֹרָה אֵין יוֹדְעִין כִּי־אִם הַצַּדִּיקֵי־אֱמֶת שֶׁפֵּרְשׁוּ אֶת עַצְמָם מִתַּאֲווֹת עוֹלָם הַזֶּה לְגַמְרֵי לְגַמְרֵי, רַק הֵם יוֹדְעִים לִדְרשׁ אֶת הַתּוֹרָה וּלְפָרֵשׁ וּלְבָאֵר כָּל הַדְּרָכִים וְהַנְּתִיבוֹת שֶׁבָּהּ בְּאֹפֶן שֶׁיּוּכַל כָּל אֶחָד לְקַבֵּל רְפוּאָה לְכָל מִינֵי חֳלִי הַנֶּפֶשׁ וְהַגּוּף שֶׁבָּעוֹלָם כַּנַּ"ל. אֲבָל מֵחֲמַת שֶׁלָּאו כָּל אָדָם יוֹדֵעַ הֵיכָן הֵם הַצַּדִּיקִים הָאֵלּוּ וְאֵיךְ זוֹכִין לְהַאֲמִין בָּהֶם וּלְהִתְקָרֵב אֲלֵיהֶם בֶּאֱמֶת. עַל־כֵּן הָעֵצָה לָזֶה הוּא נֶדֶר - שֶׁיִּדֹּר אֵיזֶה נֶדֶר וִיקַיֵּם מִיָּד, כִּי נְדָרִים סְיָג לַפְּרִישׁוּת, כִּי כָל הַנְּדָרִים הֵם בְּחִינַת פְּרִישׁוּת שֶׁרוֹצֶה לִפְרשׁ אֶת עַצְמוֹ מֵאֵיזֶה תַּאֲוָה כְּדֵי לְהִתְקָרֵב לְהַשֵּׁם יִתְבָּרַךְ; וַאֲפִלּוּ נִדְרֵי צְדָקָה וְהֶקְדֵּשׁ הֵם גַּם־כֵּן בְּחִינַת פְּרִישׁוּת, כִּי בְּעַד זֶה הַמָּמוֹן הָיָה יָכוֹל לִקְנוֹת לְעַצְמוֹ אֵיזֶה דָּבָר שֶׁהַגּוּף נֶהֱנֶה מִמֶּנּוּ, וְהוּא מְשַׁבֵּר תַּאֲוָתוֹ וְנוֹתֵן זֶה הַמָּמוֹן לִצְדָקָה, וְעַל־כֵּן עַל־יְדֵי־זֶה עוֹלֶה וּמְקַשֵּׁר אֶת עַצְמוֹ לְהַצַּדִּיקִים אֲמִתִּיִּים שֶׁזָּכוּ לְתַכְלִית הַפְּרִישׁוּת בֶּאֱמֶת וְזוֹכֶה לֶאֱמוּנַת חֲכָמִים וּלְהִתְקָרֵב אֲלֵיהֶם, כִּי מֵאַחַר שֶׁהַשֵּׁם יִתְבָּרַךְ רוֹאֶה שֶׁמַּמְשִׁיךְ עַצְמוֹ לְדַרְכֵיהֶם וּמְקַבֵּל עַל עַצְמוֹ אֵיזֶה בְּחִינַת פְּרִישׁוּת עַל־יְדֵי נֶדֶר שֶׁהוּא בְּחִינַת פֶּלֶא, בִּבְחִינַת "כִּי יַפְלִא לִנְדֹּר וְגוֹ'", עַל־יְדֵי־זֶה זוֹכֶה לְהַאֲמִין בְּהַחֲכָמִים וְצַדִּיקִים הַנִּפְלָאִים שֶׁזָּכוּ לִפְלִיאוֹת חָכְמָה עַל־יְדֵי שֶׁפֵּרְשׁוּ עַצְמָן מֵהָעוֹלָם הַזֶּה לְגַמְרֵי (שם). 
לח. עִקַּר פְּגַם אֱמוּנַת חֲכָמִים הוּא מֵחֲמַת אֵלּוּ שֶׁהֵם חֲכָמִים בְּעֵינֵיהֶם בְּחָכְמוֹת הַהֶבֶל שֶׁל זֶה הָעוֹלָם, וְהֵם חוֹלְקִים עַל הָחֲכָמִים אֲמִתִּיִּים הַנַּ"ל, וְעַל־יְדֵי קְדֻשַּׁת שַׁבָּת נִכְנָעִים וְנוֹפְלִים כָּל הָאוֹיְבִים וְהַחוֹלְקִים הַנַּ"ל וְאָז נִתְתַּקֵּן הָאֱמוּנַת חֲכָמִים. וּבֶאֱמֶת עִקַּר הַחִלּוּק שֶׁבֵּין הַחֲכָמִים אֲמִתִּיִּים וּבֵין הַחֲכָמִים בְּעֵינֵיהֶם שֶׁהֵם חֲכָמִים שֶׁל שֶׁקֶר - הֵן חֲכָמִים בְּחָכְמוֹת חִיצוֹנִיּוֹת מַמָּשׁ, שֶׁהֵם הַפִילוֹסוֹפִים וְהַמְחַקְּרִים, הֵן כָּל הַחָכְמוֹת שֶׁל הֶבֶל שֶׁהֵם נֶגֶד נְקֻדַּת הָאֱמֶת - עִקַּר הַחִלּוּק שֶׁבֵּינֵיהֶם הוּא בִּבְחִינַת זֶה הַחִלּוּק שֶׁיֵּשׁ בֵּין אֲכִילַת שַׁבָּת לַאֲכִילַת יְמֵי הַחֹל. כִּי מֵאֲכִילַת חֹל, הַכָּבֵד נִזּוֹן תְּחִלָּה, שֶׁמִּשָּׁם שֹׁרֶשׁ כָּל תַּאֲווֹת הַגּוּף; וַאֲכִילַת שַׁבָּת, הַמֹּחַ נִזּוֹן תְּחִלָּה. כְּמוֹ־כֵן אֵלּוּ הַחֲכָמִים שֶׁל הֶבֶל, שֹׁרֶשׁ כָּל חָכְמָתָם הוּא רַק בִּשְׁבִיל תַּאֲווֹת עוֹלָם הַזֶּה, כַּנִּרְאֶה בְּחוּשׁ שֶׁהֵם מְלֵאִים כָּל הַתַּאֲווֹת וּמִדּוֹת רָעוֹת, וְכָל יְגִיעָתָם בְּהַחֲקִירוֹת וְהַחָכְמוֹת הוּא גַּם־כֵּן בִּשְׁבִיל תַּאֲווֹת וּמִדּוֹת רָעוֹת, לְהַשִּׂיג עַל־יְדֵי־זֶה עשֶׁר אוֹ כָּבוֹד וְכַיּוֹצֵא, עַד שֶׁנִּשְׁתַּלְשֵׁל כָּל־כָּךְ עַד שֶׁאֲפִלּוּ בֵּין יִשְׂרָאֵל בְּעַצְמָן כָּל הַחָכְמוֹת שֶׁל שֶׁקֶר, כֻּלָּם הֵם רַק בִּשְׁבִיל תַּאֲווֹת הַגּוּף, עַד שֶׁיֵּשׁ שֶׁנּוֹסְעִים לְצַדִּיקִים וּמְפֻרְסָמִים, וְכָל כַּוָּנָתָם בִּשְׁבִיל תַּאֲווֹת הַגּוּף, לְהַשִּׂיג לָהֶם אֵיזֶה רַבָּנוּת וּמַנְהִיגוּת וְכַיּוֹצֵא. וְכָל זֶה הוּא בְּחִינַת הַכָּבֵד נִזּוֹן תְּחִלָּה וְאַחַר־כָּךְ הַמֹּחַ, כִּי כָל כַּוָּנָתָם גַּם בְּחָכְמָתָם הוּא רַק בִּשְׁבִיל תַּאֲווֹת הַגּוּף שֶׁשָּׁרְשָׁם מֵרְתִיחַת הַדָּמִים הַבָּאִים מִן הַכָּבֵד; אֲבָל הַחֲכָמִים דִּקְדֻשָּׁה הֵם בִּבְחִינַת עֹנֶג־שַׁבָּת, שֶׁאָז הַמֹּחַ נִזּוֹן תְּחִלָּה, הַיְנוּ שֶׁכָּל כַּוָּנָתוֹ בְּכָל עֲסָקָיו הוּא רַק בִּשְׁבִיל הַמֹּחַ וְהַדַּעַת דִּקְדֻשָּׁה, בִּשְׁבִיל לְהַגִּיעַ לְתַכְלִית הָאֱמֶת הַנִּצְחִי. וְכֵן כָּל הַמַּאֲמִינִים בָּהֶם וְהַמִּתְקָרְבִים אֲלֵיהֶם, כָּל כַּוָּנָתָם לַשָּׁמַיִם לְבַד, לִפְרשׁ אֶת עַצְמָם מִתַּאֲווֹת הַגּוּף וּלְהַשִּׂיג אֵיזֶה תִּקְוָה נִצְחִיִּית לָעוֹלָם הַבָּא, שֶׁזֶּה

). 
מה. עִקַּר הַתּוֹרָה נִתְּנָה לִבְנֵי־אָדָם בְּזֶה הָעוֹלָם מֵחֲמַת שֶׁהֵם בַּעֲלֵי בְּחִירָה. וְכָל הַתּוֹרָה וְהַמִּצְו?ֹת תְּלוּיִים בֶּאֱמוּנָה, כְּמוֹ שֶׁכָּתוּב: "כָּל מִצְו?ֹתֶיךָ אֱמוּנָה", וְאָמְרוּ רַבּוֹתֵינוּ זַ"ל: בָּא חֲבַקּוּק וְהֶעֱמִידָן עַל אֱמוּנָה; אִם־כֵּן, עִקַּר הַבְּחִירָה שֶׁל הָאָדָם הוּא בְּהָאֱמוּנָה, וְעִקַּר הַבְּחִירָה שֶׁיֵּשׁ לְהָאָדָם בְּעִנְיַן הָאֱמוּנָה נִמְשָׁךְ בְּשָׁרְשׁוֹ מִסּוֹד מַה שֶּׁמְּבֹאָר בְּכִתְבֵי הָאֲרִ"י זַ"ל בְּכַוָּנַת קְרִיאַת־ שְׁמַע וּבִשְׁאָר מְקוֹמוֹת, כִּי יֵשׁ יִחוּד עֶלְיוֹן שֶׁל אַבָּא וְאִמָּא [שֶׁהֵם בְּחִינַת חָכְמָה וּבִינָה כַּיָּדוּעַ], וְיֵשׁ בִּבְחִינַת זֶה הַיִּחוּד שְׁנֵי מִינֵי יִחוּד: כִּי יֵשׁ בְּחִינַת יִחוּד הַחִיצוֹן שֶׁל אַבָּא וְאִמָּא, וְהַיִּחוּד הַזֶּה תְּדִירִי וְאֵינוֹ נִפְסָק לְעוֹלָם, כִּי הוּא לְצֹרֶךְ חַיּוּת כָּל הָעוֹלָמוֹת וְקִיּוּמָם, וְאִם יִתְבַּטֵּל רֶגַע אַחַת, חַס וְשָׁלוֹם, אָז הָיוּ מִתְבַּטְּלִין כָּל הָעוֹלָמוֹת. וְיֵשׁ עוֹד בְּחִינַת יִחוּד הַפְּנִימִי שֶׁל אַבָּא וְאִמָּא, וְהוּא כְּדֵי לָתֵת מֹחִין אֶל זָכָר וּנְקֵבָה כְּדֵי לְהוֹלִיד נְשָׁמוֹת בְּעוֹלָם שֶׁהוּא פְּנִימִיּוּת הָעוֹלָמוֹת; וְזֶה הַיִּחוּד אֵינוֹ תְּדִירִי, כִּי אִי אֶפְשָׁר לְיַחֵד הַיִּחוּד הַזֶּה כִּי־אִם עַל־יְדֵי הַעֲלָאַת מַיִּין נֻקְבִּין שֶׁהוּא עַל־יְדֵי שֶׁאָנוּ מַמְשִׁיכִין בִּשְׁעַת קְרִיאַת־שְׁמַע הֶאָרָה לַמֹּחִין מֵהַיִּחוּד הַחִיצוֹן הַנַּ"ל כְּדֵי שֶׁיּוּכְלוּ לַעֲלוֹת בְּסוֹד הַעֲלָאַת מַיִּין נֻקְבִּין, וְאַחַר־כָּךְ עוֹלִין בְּסוֹד מַיִּין נֻקְבִּין עַל־יְדֵי מְסִירַת־נֶפֶשׁ עַל קְדֻשַּׁת הַשֵּׁם, וְעַל־יְדֵי־זֶה מְיַחֲדִין יִחוּד הָעֶלְיוֹן הַפְּנִימִי הַנַּ"ל שֶׁהוּא לְצֹרֶךְ הַמְשָׁכַת הַנְּשָׁמוֹת. וּמְבֹאָר עוֹד שָׁם, שֶׁהַהֶאָרָה שֶׁמְּקַבְּלִין הַמֹּחִין מֵהַיִּחוּד הַחִיצוֹן הוּא כְּפִי מַדְרֵגַת הַמֹּחִין אָז, וּכְפִי הַהֶאָרָה שֶׁמְּקַבְּלִין, כְּמוֹ־כֵן נַעֲשֶׂה הַיִּחוּד הַפְּנִימִי וְהַמְשָׁכַת הַנְּשָׁמוֹת הַנַּ"ל, עַיֵּן שָׁם עוֹד בְּבֵאוּר יוֹתֵר. וְעִקַּר חַיּוּת וְקִיּוּם כָּל הָעוֹלָמוֹת הוּא אֱמוּנָה, כְּמוֹ שֶׁכָּתוּב: "וְכָל מַעֲשֵׂהוּ בֶּאֱמוּנָה", וְעַל־כֵּן הַחַיּוּת הַנִּמְשָׁךְ תָּמִיד מִלְמַעְלָה, מִבְּחִינַת הַיִּחוּד הַחִיצוֹן הַנַּ"ל, שֶׁהוּא לְצֹרֶךְ חַיּוּת וְקִיּוּם הָעוֹלָמוֹת, זֶה בְּחִינַת הֶאָרַת הָאֱמוּנָה שֶׁנִּמְשָׁךְ מִשָּׁם, שֶׁעַל־יְדֵי הֶאָרָה זֹאת נִמְשָׁךְ בְּלֵב הָאָדָם לְהַאֲמִין בְּהַשֵּׁם יִתְבָּרַךְ, כִּי אֱמוּנָה הוּא בְּחִינַת מַלְכוּת שֶׁשָּׁרְשָׁהּ בְּחָכְמָה עִלָּאָה, כְּמוֹ שֶׁכָּתוּב: "ה' בְּחָכְמָה יָסַד אָרֶץ" כַּיָּדוּעַ. וְזֶה בְּחִינַת "לְךָ אָמַר לִבִּי בַּקְּשׁוּ פָנָי", שֶׁהַלֵּב שֶׁל הָאָדָם אוֹמֵר לוֹ לְבַקֵּשׁ פָּנָיו יִתְבָּרַךְ תָּמִיד, וְזֶה נִמְשָׁךְ מִבְּחִינַת הַחַיּוּת הָעֶלְיוֹן הַנִּמְשָׁךְ תָּמִיד מִלְמַעְלָה מֵהַיִּחוּד הַחִיצוֹן הַנַּ"ל. וּבָזֶה תָּלוּי עִקַּר הַבְּחִירָה שֶׁל הָאָדָם, שֶׁעַל־יְדֵי־זֶה הָאָדָם גָּבֹהַּ מִמַּדְרֵגַת הַמַּלְאָכִים וְכוּ', כִּי הַהֶאָרָה וְהַחַיּוּת הַנַּ"ל כְּשֶׁנִּמְשָׁךְ בָּעוֹלָמוֹת הָעֶלְיוֹנִים שֶׁהֵם עוֹלַם הַמַּלְאָכִים וְהַשְּׂרָפִים וְכוּ' שֶׁאֵין שָׁם גַּשְׁמִיּוּת וּבְחִירָה, אָז יֵשׁ לָהֶם כֹּחַ לְקַבֵּל הֶאָרָה הַזֹּאת בִּשְׁלֵמוּת גָּדוֹל, וְתֵכֶף מִתְעוֹרְרִין בְּרַעַשׁ גָּדוֹל לְהַקְדִּישׁ שְׁמוֹ יִתְבָּרַךְ וְנִתְלַהֲבִים בְּהִתְלַהֲבוּת גָּדוֹל לַעֲשׂוֹת בְּאֵימָה וּבְיִרְאָה רְצוֹן קוֹנָם; אֲבָל כְּשֶׁזֹּאת הַהֶאָרָה מַגִּיעַ לְזֶה הָעוֹלָם הֶעָכוּר הַגַּשְׁמִי שֶׁהוּא עוֹלַם הָעֲשִׂיָּה, אֲזַי אִי אֶפְשָׁר לְקַבֵּל הֶאָרָה הַזֹּאת הַגְּדוֹלָה, כִּי־אִם הִתְנוֹצְצוּת מְעַט מִמֶּנָּה, שֶׁעַל־יְדֵי־זֶה נִתְעוֹרֵר לֵב הָאָדָם לְהִשְׁתּוֹקֵק לֶאֱמוּנָתוֹ יִתְבָּרַךְ וּלְבַקֵּשׁ פָּנָיו תָּמִיד בִּבְחִינַת "לְךָ אָמַר לִבִּי בַּקְּשׁוּ פָנָי" הַנַּ"ל, כִּי מֵחֲמַת שֶׁזֹּאת הַהֶאָרָה אֵינָהּ יְכוֹלָה לְהִתְלַבֵּשׁ בְּזֶה הָעוֹלָם כִּי־אִם עַל־יְדֵי צִמְצוּמִים רַבִּים, עַל־כֵּן בַּתְּחִלָּה אֵינוֹ נִמְשָׁךְ מִמֶּנָּה לְלֵב הָאָדָם כִּי־אִם הִתְנוֹצְצוּת בְּעָלְמָא לְרַמֵּז לְהָאָדָם שֶׁיַּמְשִׁיךְ אַחֲרָיו יִתְבָּרַךְ כְּמוֹ שֶׁמְּרַמְּזִין לְהָאָדָם מֵרָחוֹק, וַאֲזַי יֵשׁ לְהָאָדָם בְּחִירָה, כִּי הַמַּשְׂכִּיל הֶחָפֵץ בֶּאֱמֶת לַאֲמִתּוֹ הוּא מִתְעוֹרֵר תֵּכֶף עַל־יְדֵי הִתְנוֹצְצוּת הַזֹּאת וּמַתְחִיל לָרוּץ וְלִרְדֹּף לְהַשִּׂיג בִּשְׁלֵמוּת הָאֱמוּנָה הַזֹּאת, וּמִשְׁתַּדֵּל לַעֲשׂוֹת בְּלִבּוֹ צִמְצוּמִים וְכֵלִים לְקַבֵּל הֶאָרָה הַזֹּאת בְּיוֹתֵר, וְזֶה בְּחִינַת הַמְשָׁכַת רוּחָנִיּוּת אֱלָקוּת לְתוֹךְ צִמְצוּמִים; וְעַל־יְדֵי הֶאָרָה הַזֹּאת שֶׁנִּתּוֹסֵף בְּהַמֹּחִין שֶׁלּוֹ [שֶׁהוּא בְּחִינַת מַה שֶּׁמְּקַבְּלִין הַמֹּחִין הֶאָרָה מֵהַיִּחוּד הַחִיצוֹן הַנַּ"ל בִּשְׁעַת קְרִיאַת־שְׁמַע כַּנַּ"ל], עַל־יְדֵי־זֶה הוּא נִתְעוֹרֵר בְּשַׁלְהוֹבִין דִּרְחִימוּתָא לִמְסֹר נַפְשׁוֹ בְּכָל לֵב עַל קְדֻשַּׁת הַשֵּׁם, וְאָז עוֹלֶה עַל־יְדֵי־ זֶה בְּסוֹד מַיִּין נֻקְּבִּין כַּנַּ"ל וְגוֹרֵם יִחוּד הָעֶלְיוֹן הַפְּנִימִי, וְאָז נִמְשָׁךְ לוֹ מִשָּׁם חַיּוּת יוֹתֵר עֶלְיוֹן, שֶׁהוּא בְּחִינַת חַיּוּת נִשְׁמוֹת יִשְׂרָאֵל, שֶׁעַל־יְדֵי־זֶה נִתְגַּלֶּה הָאֱמוּנָה בִּשְׁלֵמוּת בְּהִתְגַּלּוּת גָּדוֹל לְכָל בָּאֵי עוֹלָם, כִּי דַּיְקָא בְּזֶה הָעוֹלָם שֶׁהוּא תַּחְתּוֹן וּמְגֻשָּׁם מְאֹד צְרִיכִין לְהַמְשִׁיךְ הָאֱמוּנָה שֶׁהוּא עִקַּר הַחַיּוּת מֵהַיִּחוּד הַפְּנִימִי שֶׁהוּא יוֹתֵר עֶלְיוֹן וְגָבֹהַּ. וְעַל־יְדֵי־זֶה בֶּאֱמֶת נִשְׁמוֹת יִשְׂרָאֵל גְּבוֹהִים מִמַּלְאָכִים, כִּי הַמַּלְאָכִים אֵינָם עה מְקַבְּלִים חַיּוּת רַק מֵהַיִּחוּד הַחִיצוֹן, אֲבָל נִשְׁמוֹת יִשְׂרָאֵל הֵם נִמְשָׁכִין מֵהַיִּחוּד הַפְּנִימִי הַנַּ"ל כַּמְבֹאָר בְּכִתְבֵי הָאֲרִ"י זַ"ל, כִּי זֶה הַחַיּוּת וְהֶאָרָה הַנִּמְשֶׁכֶת מֵהַיִּחוּד הַחִיצוֹן, אַף־עַל־פִּי שֶׁהוּא גַּם־כֵּן גָּבֹהַּ וְקָדוֹשׁ מְאֹד, אַף־עַל־פִּי־כֵן אֵין לוֹ כֹּחַ עֲדַיִן לִקְבֹּעַ עַל־ יָדוֹ הָאֱמוּנָה בִּשְׁלֵמוּת בְּלֵב הָאָדָם, רַק שֶׁעַל־יָדוֹ אָנוּ מִתְעוֹרְרִין לֶאֱמוּנָתוֹ יִתְבָּרַךְ כַּנַּ"ל. וְעִקַּר הָאֱמוּנָה בִּשְׁלֵמוּת נִמְשָׁךְ עַל־ יְדֵי הַצַּדִּיקִים אֲמִתִּיִּים, שֶׁתֵּכֶף שֶׁמַּגִּיעַ עֲלֵיהֶם הֶאָרָה וְהִתְנוֹצְצוּת מֵהַיִּחוּד הַחִיצוֹן הָעֶלְיוֹן הַנַּ"ל, אֲזַי מַמְשִׁיכִין זֹאת הַהֶאָרָה לְתוֹךְ צִמְצוּמִים וּמְקַשְּׁרִין אוֹתָהּ בְּלִבָּם, וְעַל־יְדֵי־זֶה נִמְשָׁךְ הֶאָרָה לְהַמֹּחִין שֶׁלָּהֶם, וְעַל־יְדֵי־זֶה הֵם עוֹלִים בְּסוֹד מַיִּין נֻקְבִּין בִּמְסִירַת־נֶפֶשׁ עַל קִדּוּשׁ הַשֵּׁם, וְעַל־יְדֵי־זֶה נַעֲשֶׂה יִחוּד הַפְּנִימִי שֶׁמִּשָּׁם הַחַיּוּת שֶׁל נִשְׁמוֹת הַצַּדִּיקִים, שֶׁעַל־יְדֵי זֶה הַחַיּוּת יְכוֹלִין הַצַּדִּיקִים לְגַלּוֹת הָאֱמוּנָה בָּעוֹלָם בִּשְׁלֵמוּת גָּדוֹל, וּבָזֶה אָנוּ גְּבוֹהִים הַרְבֵּה מִן הַמַּלְאָכִים, כִּי אַף־עַל־פִּי שֶׁהֵם מְקַבְּלִין הֶאָרָה מֵהַיִּחוּד הַחִיצוֹן בְּאוֹר גָּדוֹל וְנִפְלָא יוֹתֵר מִמַּה שֶּׁמְּקַבְּלִין מִמֶּנּוּ הַתַּחְתּוֹנִים, אַף־ עַל־פִּי־כֵן אֵין לָהֶם כֹּחַ לִגְרֹם הַיִּחוּד הַפְּנִימִי וּלְחַדֵּשׁ הָאֱמוּנָה בְּהֶאָרָה יְתֵרָה וְנִפְלָאָה; אֲבָל אֲנַחְנוּ עַם קָדוֹשׁ, אַדְּרַבָּא מֵחֲמַת זֶה בְּעַצְמוֹ שֶׁתְּחִלַּת הֶאָרַת הָאֱמוּנָה בָּאָה עָלֵינוּ בְּזֶה הָעוֹלָם בְּצִמְצוּם גָּדוֹל, רַק בִּבְחִינַת הִתְנוֹצְצוּת וּרְמָזִים כַּנַּ"ל, וְעַל־יְדֵי־זֶה יֵשׁ לָנוּ בְּחִירָה, אֲזַי כְּשֶׁאָנוּ זוֹכִין לִבְחֹר בְּהָאֱמֶת, לִרְדֹּף וְלָרוּץ אַחֲרָיו יִתְבָּרַךְ בִּמְסִירַת־נֶפֶשׁ, אֲזַי אָנוּ זוֹכִים לִגְרֹם עַל־יְדֵי־ זֶה יִחוּד הַפְּנִימִי שֶׁמִּשָּׁם נִמְשָׁךְ עָלֵינוּ הֶאָרָה נִפְלָאָה בִּידִיעַת תְּשׁוּקַת אֱמוּנָתוֹ יִתְבָּרַךְ מַה שֶּׁאֵין הַמַּלְאָכִים יוֹדְעִים מִזֶּה כְּלָל, וְיֵשׁ לָנוּ כֹּחַ לְחַדֵּשׁ אֶת הָאֱמוּנָה בְּהִתְחַדְּשׁוּת נִפְלָא, בִּבְחִינַת "חֲדָשִׁים לַבְּקָרִים רַבָּה אֱמוּנָתֶךָ". וְהִנֵּה זֹאת הֶאָרָה הַנִּמְשֶׁכֶת מֵהַיִּחוּד הַחִיצוֹן, נִמְשָׁךְ עַל כָּל הָעוֹלָם, אֲפִלּוּ עַל אֻמּוֹת הָעוֹלָם, כִּי מִמֶּנּוּ עִקַּר חַיּוּת וְקִיּוּם כָּל הַנִּבְרָאִים. וּבֶאֱמֶת רוֹצֶה הַשֵּׁם יִתְבָּרַךְ לְהַמְשִׁיךְ גַּם אוֹתָנוּ לֶאֱמוּנָתוֹ הַקְּדוֹשָׁה, אֲבָל הֵם, כְּשֶׁבָּא עֲלֵיהֶם הֶאָרָה וְהִתְנוֹצְצוּת וּרְמָזִים הַנַּ"ל, הֵם פּוֹנִים עֹרֶף מִלִּשְׁמֹעַ, כִּי אֵינָם רוֹצִים לְהַשְׁלִיךְ תַּאֲוָתָם הָרָעוֹת וְלִמְסֹר נַפְשָׁם בִּשְׁבִילוֹ יִתְבָּרַךְ. וְזֶה בְּחִינַת מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, שֶׁהֶחֱזִיר הַקָּדוֹשׁ־ בָּרוּךְ־הוּא הַתּוֹרָה עַל כָּל הָאֻמּוֹת וְלֹא רָצוּ לְקַבְּלָהּ, וְעַל־יְדֵי־זֶה, לֹא דַי שֶׁאֵינָם זוֹכִים לִגְרֹם יִחוּד הַפְּנִימִי, שֶׁמִּשָּׁם עִקַּר הִתְגַּלּוּת הָאֱמוּנָה בְּאוֹר נִפְלָא, שֶׁזֶּה עִקַּר קַבָּלַת הַתּוֹרָה, אַף גַּם אֲפִלּוּ אוֹר הַנִּמְשָׁךְ בִּקְבִיעוּת מִבְּחִינַת יִחוּד הַחִיצוֹן, גַּם זֶה נִתְקַלְקֵל אֶצְלָם עַל־יְדֵי מַעֲשֵׂיהֶם הָרָעִים, וְנִמְשָׁךְ לָהֶם עַל־יְדֵי־זֶה כְּפִירוֹת וֶאֱמוּנוֹת כָּזְבִּיּוֹת. וּמִזֶּה נִמְשָׁךְ מַה שֶּׁכָּל הָעוֹלָם, אֲפִלּוּ אֻמּוֹת הָעוֹלָם וְהַפִילוֹסוֹפִים וְהָאֶפִּיקוֹרְסִים, רֻבָּם כְּכֻלָּם מוֹדִים בִּמְצִיאַת הַשֵּׁם יִתְבָּרַךְ, וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל: דְּקָרוּ לֵהּ אֱלָקָא דֶּאֱלָקַיָּא, כָּל זֶה נִמְשָׁךְ מֵהַחַיּוּת שֶׁנִּמְשָׁךְ בְּצִמְצוּם גַם בְּזֶה הָעוֹלָם מֵהַיִּחוּד הַחִיצוֹן, שֶׁעִקַּר הַחַיּוּת הוּא אֱמוּנָה; אַךְ מֵחֲמַת גַּשְׁמִיּוּת הָעוֹלָם, אֵין הַהֶאָרָה הַזֹּאת מִתְגַּלָּה בְּזֶה הָעוֹלָם רַק בִּבְחִינַת הִתְנוֹצְצוּת וּרְמָזִים, וְעַל־יְדֵי־זֶה עִקַּר הַבְּחִירָה, שֶׁמִּי שֶׁרוֹצֶה עַל־יְדֵי־זֶה לִמְסֹר נַפְשׁוֹ בִּשְׁבִיל הַשֵּׁם יִתְבָּרַךְ וְלִצְעֹק אֵלָיו מֵעֹמֶק הַלֵּב, עַל־יְדֵי־זֶה גּוֹרֵם יִחוּד הַפְּנִימִי, וְאָז מַמְשִׁיךְ מִשָּׁם חַיּוּת הָאֱמוּנָה הַקְּדוֹשָׁה בִּשְׁלֵמוּת, כִּי דַּיְקָא מֵחֲמַת שֶׁהָעוֹלָם הַזֶּה נָמוּךְ וּמְגֻשָּׁם בְּיוֹתֵר, צָרִיךְ שֶׁיִּמְשֹׁךְ אֵלָיו חַיּוּת וְהֶאָרָה מִמָּקוֹם גָּבֹהַּ בְּיוֹתֵר, בִּכְדֵי שֶׁלֹּא יוּכַל גַּשְׁמִיּוּת זֶה הָעוֹלָם לְהַסְתִּירוֹ. וְהַכְּסִילִים הַבּוֹחֲרִים בָּרַע וְאֵינָם רוֹצִים לְהַשְׁלִיךְ תַּאֲוָתָם וְלִרְדֹּף אַחַר הַשֵּׁם יִתְבָּרַךְ בִּמְסִירַת־נֶפֶשׁ, אֲזַי אֵינָם זוֹכִים לְקַבֵּל חַיּוּת הָאֱמוּנָה מֵהַיִּחוּד הַפְּנִימִי, וְגַם מְעַט הַחַיּוּת שֶׁנִּמְשָׁךְ מֵהַיִּחוּד הַחִיצוֹן אֵינָם יְכוֹלִים לְקַבֵּל בִּשְׁלֵמוּת, עַד שֶׁנִּתְקַלְקֵל גַּם זֶה אֶצְלָם וְנַעֲשֶׂה מִזֶּה אֱמוּנוֹת כָּזְבִּיּוֹת וּכְפִירוֹת, רַחֲמָנָא לִצְּלַן, כַּנַּ"ל (שם הל' תחומין, ה"ה, אותיות ג ד ה ו). 
מו. אַף־עַל־פִּי שֶׁגַּם בָּעוֹלָמוֹת הָעֶלְיוֹנִים יֵשׁ בְּחִינַת אֱמוּנָה, אַף־עַל־פִּי־כֵן עִקַּר הַמְשָׁכַת הָאֱמ

). 
סא. גֹדֶל הַהַעְלָמָה שֶׁיֵּשׁ בָּעוֹלָם, אִי אֶפְשָׁר לְהָבִין וּלְשַׁעֵר כְּלָל. כִּי הַכֹּל יוֹדְעִין וְרוֹאִין הָאֱמֶת שֶׁהָעוֹלָם הַזֶּה הוּא צֵל עוֹבֵר, וְאַף־עַל־פִּי־כֵן הַכֹּל רָצִין אַחֲרָיו מְאֹד, מֵחֲמַת גֹּדֶל הַהַעְלָמָה שֶׁמִּתְפַּשֶּׁטֶת בָּעוֹלָם לְכַסּוֹת עַל אוֹר הַדַּעַת הָאֲמִתִּי. וְכָל זֶה בִּשְׁבִיל הַבְּחִירָה, כִּי אִם לֹא הָיָה כֹּחַ הַהַעְלָמָה גָּדוֹל כָּל־כָּךְ, אֲזַי לֹא הָיָה שׁוּם בְּחִירָה כְּלָל. וְהִנֵּה הָעוֹלָם כָּלוּל מֵאַרְבָּעָה יְסוֹדוֹת: אֵשׁ, רוּחַ, מַיִם, עָפָר; אַךְ עִקַּר הִתְפַּשְּׁטוּת וְהִתְגַּבְּרוּת הַהַעְלָמָה הוּא עַל הֶעָפָר הַזֶּה שֶׁאָנוּ הַבַּעֲלֵי־בְחִירָה יוֹשְׁבִין עָלֶיהָ. וְהִנֵּה הָאַרְבָּעָה יְסוֹדוֹת הַנַּ"ל הֵם כְּנֶגֶד הָאַרְבָּעָה עוֹלָמוֹת וְאַרְבַּע אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ. וְשָׁלשׁ אוֹתִיּוֹת רִאשׁוֹנוֹת הֵם בְּחִינַת שְׁלשָׁה מֹחִין, וְהֵא הָאַחֲרוֹנָה הִיא בְּחִינַת מַלְכוּת, בְּחִינַת אֱמוּנָה, וּכְנֶגְדָּהּ - יְסוֹד הֶעָפָר. וְעַל־כֵּן עִקַּר הִתְגַּלּוּת הַהַעְלָמָה שֶׁמִּתְגַּבֵּר כָּל־כָּךְ בִּיסוֹד הֶעָפָר הוּא עַל־יְדֵי אֱמוּנָה דַּיְקָא, וְהָעִקָּר הוּא עַל־יְדֵי אֱמוּנַת חֲכָמִים, שֶׁהֵם עוֹסְקִים בָּזֶה לְגַלּוֹת הַהַעְלָמָה וּלְהַמְשִׁיךְ אוֹר הָאֱמֶת וְהִתְגַּלּוּת אֱלָקוּתוֹ יִתְבָּרַךְ בָּעוֹלָם (שם הל' שחיטה, הל' ה, אותיות ו, יב). 
סב. תִּקּוּן הַדַּעַת וְהָאֱמוּנָה הַכֹּל אֶחָד, וּשְׁנֵיהֶם תְּלוּיִים זֶה בָּזֶה. וְהָעִקָּר הוּא הָאֱמוּנָה, שֶׁהוּא יְסוֹד הַכֹּל, כְּמוֹ שֶׁכָּתוּב: "כָּל מִצְו?ֹתֶיךָ אֱמוּנָה". אַךְ זֶה יָדוּעַ, שֶׁחַיּוּת הָאֱמוּנָה שֶׁהוּא בְּחִינַת מַלְכוּת, הוּא מֵהַדָּעַת, כִּי בֶּאֱמֶת אַף־עַל־פִּי שֶׁאֱמוּנָה הוּא דַּיְקָא לְהַאֲמִין בֶּאֱמוּנָה לְבַד בְּלִי שׁוּם שֵׂכֶל וָדַעַת, כִּי בְּמַה שֶּׁהַשֵּׂכֶל מֵבִין, אֵין זֶה אֱמוּנָה כַּמּוּבָן, אַף־עַל־פִּי־כֵן שֹׁרֶשׁ הָאֱמוּנָה וְחַיּוּתָהּ הוּא מֵהַדַּעַת, כִּי עִקַּר הָאֱמוּנָה הוּא רַק אֵצֶל מִן הָאָדָם שֶׁיֵּשׁ לוֹ דַּעַת וָשֵׂכֶל, רַק שֶׁהַשֵּׁם יִתְבָּרַךְ חוֹנֵן עָלֵינוּ וּמַמְשִׁיךְ עַל נַפְשֵׁנוּ וְדַעְתֵּנוּ הֶאָרָה מִשֵּׂכֶל עֶלְיוֹן כָּזֶה, שֶׁעַל־יְדֵי־זֶה נִמְשָׁךְ בָּנוּ כֹּחַ הָאֱמוּנָה, כִּי הָאֱמוּנָה נִמְשֶׁכֶת בְּשָׁרְשָׁהּ מִשֵּׂכֶל עֶלְיוֹן וְגָבֹהַּ מְאֹד מְאֹד, שֶׁמִּשָּׁם נִמְשָׁךְ בָּנוּ הַכֹּחַ לְהִתְחַזֵּק לְהִתְחַזֵּק בֶּאֱמוּנָה שְׁלֵמָה. וְאַף־ עַל־פִּי שֶׁהָאָדָם יָכוֹל לִזְכּוֹת לֶאֱמוּנָה שְׁלֵמָה אַף־עַל־פִּי שֶׁאֵין לוֹ דַּעַת גָּדוֹל, כְּמוֹ שֶׁאָנוּ רוֹאִין אֵצֶל הֶהָמוֹן וְכֵן הַנָּשִׁים, שֶׁיֵּשׁ לָהֶם אֱמוּנָה שְׁלֵמָה בִּפְשִׁיטוּת, שֶׁזֶּה עִקַּר הָאֱמוּנָה לְהַאֲמִין בִּפְשִׁיטוּת כְּמוֹתָם כַּמְבֹאָר בְּמָקוֹם אַחֵר - אַף־עַל־פִּי־כֵן מִי שֶׁזּוֹכֶה עַל־יְדֵי תּוֹרָה וַעֲבוֹדַת־הַשֵּׁם לִשְׁלֵמוּת הַדַּעַת דִּקְדֻשָּׁה, בְּוַדַּאי אָז אֱמוּנָתוֹ חֲזָקָה יוֹתֵר וְיוֹתֵר. וְכָל מַה שֶּׁהָאָדָם זוֹכֶה יוֹתֵר לְהַגְדִּיל דַּעְתּוֹ בִּקְדֻשָּׁה, הוּא זוֹכֶה לְהַמְשִׁיךְ הֶאָרָה נִפְלָאָה עַל הָאֱמוּנָה יוֹתֵר וְיוֹתֵר, כִּי הוּא מֵבִין בְּכָל פַּעַם בְּיוֹתֵר שֶׁאֵינוֹ יוֹדֵעַ כְּלָל וְשֶׁצָּרִיךְ לְהִתְחַזֵּק רַק בֶּאֱמוּנָה שְׁלֵמָה; וְגַם מֵחֲמַת שֶׁרוֹאֶה שֶׁעַל־יְדֵי שֶׁנִפְתַּח דַּעְתּוֹ וְנִתְיַשְּׁבוּ אֶצְלוֹ כַּמָּה קֻשְׁיוֹת וּפְלִיאוֹת שֶׁהָיָה בְּדַעְתּוֹ מִתְּחִלָּה עַל הַשֵּׁם יִתְבָּרַךְ וְהַצַּדִּיקִים, עַל־יְדֵי־זֶה הוּא מֵבִין וְיוֹדֵעַ שֶׁגַּם הַקֻּשְׁיוֹת שֶׁעֲדַיִן סְתוּמִים אֶצְלוֹ, בְּוַדַּאי יֵשׁ גַּם עֲלֵיהֶם תֵּרוּצִים נְכוֹנִים, רַק שֶׁעֲדַיִן לֹא זָכָה לְהַשִּׂיג זֹאת, אוֹ שֶׁהֵם מֵהַקֻּשְׁיוֹת שֶׁאִי אֶפְשָׁר לְיַשְּׁבָן בְּזֶה הָעוֹלָם בְּשׁוּם אֹפֶן, וְעַל־כֵּן הוּא מִתְחַזֵּק בֶּאֱמוּנָה יְתֵרָה בְּכָל פַּעַם; נִמְצָא, שֶׁעַל־יְדֵי הַדַּעַת נִתְחַזֵּק הָאֱמוּנָה. וּמִכָּל־שֶׁכֵּן לְהֵפֶךְ, שֶׁכָּל מַה שֶּׁהָאָדָם מִתְחַזֵּק אֶת עַצְמוֹ בֶּאֱמוּנָה יְתֵרָה, נִתּוֹסֵף לוֹ עַל־יְדֵי־זֶה הֶאָרָה גְדוֹלָה בְּדַעְתּוֹ, כִּי הָעִקָּר הוּא הָאֱמוּנָה, כִּי עַל־יְדֵי אֱמוּנָה זוֹכִין לְדַעַת, וְעַל־כֵּן דַּעַת וֶאֱמוּנָה שְׁנֵיהֶם אֶחָד, כִּי שְׁנֵיהֶם בִּכְלָל נִקְרָאִים אֱמוּנָה, כִּי עִקַּר תַּכְלִית הַדַּעַת הוּא הָאֱמוּנָה, בִּבְחִינַת: תַּכְלִית הַיְדִיעָה - אֲשֶׁר לֹא נֵדַע; רַק עַל־יְדֵי כָּל דַּעַת שֶׁמַּשִּׂיג בְּיוֹתֵר, עַל־יְדֵי־זֶה הוּא מֵבִין בְּהִתְבּוֹנְנוּת נִפְלָא כַּמָּה צְרִיכִין לְהִתְחַזֵּק בֶּאֱמוּנָה וְלִסְמֹךְ רַק עַל הָאֱמוּנָה שֶׁהוּא יְסוֹד הַכֹּל. וְעַל־יְדֵי שֶׁזּוֹכִין לִשְׁלֵמוּת הַדַּעַת וְהָאֱמוּנָה, עַל־יְדֵי־ זֶה נִתְיַחֵד קֻדְשָׁא־בְּרִיךְ־הוּא וּשְׁכִינְתֵּהּ אַפִּין בְּאַפִּין, כִּי קֻדְשָׁא־בְּרִיךְ־הוּא וּשְׁכִינְתֵּהּ הֵם שֹׁרֶשׁ הַדַּעַת וְהָאֱמוּנָה, שֶׁשְּׁנֵיהֶם אֶחָ

). 
ע. כָּל הַמִּצְו?ֹת שֶׁבַּתּוֹרָה הֵם בִּשְׁבִיל צִיּוּר אוֹר הָעֶלְיוֹן לְטוֹבָה וְלִבְרָכָה, וְלֹא לְהֵפֶךְ, חַס וְשָׁלוֹם. כִּי עִקַּר שֹׁרֶשׁ כָּל הַתּוֹרָה כֻּלָּהּ הוּא הָאֱמוּנָה הַקְּדוֹשָׁה, שֶׁעַל־יְדֵי־זֶה יוֹדְעִין מִמֶּנּוּ יִתְבָּרַךְ, כִּי עִקַּר הַבְּרִיאָה הָיְתָה בְּגִין דְּיִשְׁתְּמוֹדְעִין לֵהּ. אֲבָל זֶה יָדוּעַ שֶׁהַשֵּׁם יִתְבָּרַךְ מְרוֹמָם וְנִשָּׂא מְאֹד מִדַּעְתֵּנוּ, וְלֵית מַחֲשָׁבָה תְּפִיסָא בֵּהּ כְּלָל, אַךְ אַף־עַל־פִּי־כֵן מְרַחֵם עָלֵינוּ הַשֵּׁם יִתְבָּרַךְ לְמַעֲנוֹ, וּמֵאִיר לְכָל אֶחָד בְּדַעְתּוֹ בְּכֹחַ הַצַּדִּיקֵי־אֱמֶת, שֶׁיָּאִיר בּוֹ אֲמִתַּת הָאֱמוּנָה הַקְּדוֹשָׁה, שֶׁיֹּאחַז אֶת עַצְמוֹ בְּהַשֵּׁם יִתְבָּרַךְ וּבְתוֹרָתוֹ הַקְּדוֹשָׁה, אֲשֶׁר הוּא חַיֵּינוּ לָנֶצַח. אֲבָל הָאוֹר הַיּוֹרֵד מִלְמַעְלָה הוּא גָבֹהַּ מְאֹד וְהוּא אוֹר פָּשׁוּט, וְצָרִיךְ כָּל אֶחָד לְצַיְּרוֹ כְּפִי תְּפִיסַת הַמֹּחִין שֶׁלּוֹ, אֲבָל לָאו כָּל אָדָם זוֹכֶה לָזֶה, לְצַיֵּר הָאוֹר לְטוֹבָה; כִּי רֻבָּם, אֵין כְּלֵי הַמֹּחִין שֶׁלָּהֶם מְתֻקָּנִים כָּרָאוּי. עַל־כֵּן חָמַל עָלֵינוּ הַשֵּׁם יִתְבָּרַךְ וְנָתַן לָנוּ אֶת הַתּוֹרָה הַקְּדוֹשָׁה, רְמַ"ח מִצְו?ֹת עֲשֵׂה וּשְׁסָ"ה מִצְו?ֹת לֹא־תַעֲשֶׂה וּמִצְו?ֹת דְּרַבָּנָן, שֶׁכֻּלָּם הֵם בְּחִינַת צִיּוּרִים קְדוֹשִׁים לְצַיֵּר הָאוֹר לִבְרָכָה, וְהִזְהִיר אוֹתָנוּ לְהִשָּׁמֵר מִכָּל הָעֲבֵרוֹת, שֶׁכֻּלָּם הֵם קִלְקוּלִים וּפְגָמִים, שֶׁעַל־יָדָם מְצַיְּרִים הָאוֹר לְהֵפֶךְ, חַס וְשָׁלוֹם. וְזֶהוּ כְּלַל כָּל הַתּוֹרָה וְהַמִּצְו?ֹת, וְכָל הַכַּוָּנוֹת וְהַסּוֹדוֹת שֶׁיֵּשׁ בָּהֶם, כֻּלָּם כְּלוּלִים בְּעִנְיָן זֶה, וּבָזֶה תָּלוּי עִקַּר הַחַיּוּת שֶׁל הָאָדָם וְשֶׁל כָּל הָעוֹלָמוֹת, כִּי הֵם חַיֵּינוּ, כִּי עִקַּר הַחַיּוּת הוּא עַל־יְדֵי אוֹר הָעֶלְיוֹן הַבָּא מִלְמַעְלָה כְּשֶׁזּוֹכִים לְצַיְּרוֹ לִבְרָכָה, וְאָז מְיֻחָד וּמְקֻשָּׁר הָאוֹר בְּהַכֵּלִים, שֶׁזֶּה עִקַּר הַחַיּוּת כַּיָּדוּעַ, וְכֵן לְהֵפֶךְ, חַס וְשָׁלוֹם. וְעַל־ כֵּן כְּפִי שִׁקּוּל הַדַּעַת בְּהַשְׁקָפָה רִאשׁוֹנָה, הָיָה רָאוּי לֵהָרֵג וְאַל יַעֲבֹר עַל שׁוּם מִצְוָה מֵהַתּוֹרָה הַקְּדוֹשָׁה, כִּי אֵיךְ אֶפְשָׁר לַעֲבֹר, חַס וְשָׁלוֹם, עַל שׁוּם מִצְוָה, כִּי הֲלוֹא תֵּכֶף נִתְקַלְקֵל צִיּוּר הָאוֹר כְּפִי פְּגַם הַמִּצְוָה, וּמֵהֵיכָן יְקַבֵּל חַיּוּת? וְהַתּוֹרָה אָמְרָה שֶׁכָּל הַמִּצְו?ֹת שֶׁבַּתּוֹרָה נִדְחִין מִפְּנֵי פִּקּוּחַ־נֶפֶשׁ, וְעַל כָּל הַמִּצְו?ֹת יַעֲבֹר וְאַל יֵהָרֵג, חוּץ מֵעֲבוֹדָה זָרָה וְגִלּוּי־עֲרָיוֹת וּשְׁפִיכוּת־דָּמִים, כִּי חַיּוּתוֹ שֶׁל נֶפֶשׁ אֶחָד מִיִּשְׂרָאֵל יָקָר מְאֹד בְּעֵינָיו יִתְבָּרַךְ, כִּי כָּל אֶחָד מִיִּשְׂרָאֵל עוֹסֵק כָּל יְמֵי חַיָּיו רַק בְּעִנְיָן זֶה לְצַיֵּר הָאוֹר לִבְרָכָה וּלְהַשְׁלִים בְּחִינַת שִׁבְעִים פָּנִים בַּתּוֹרָה, כְּפִי הַחֵלֶק שֶׁיֵּשׁ לְכָל אֶחָד מִיִּשְׂרָאֵל שָׁם, שֶׁעַל־יָדָם עִקַּר צִיּוּר הָאוֹר לְטוֹבָה; וְעַל־כֵּן יוֹתֵר כְּדַאי לַעֲבֹר פַּעַם אֶחָד עַל אֵיזֶה דָבָר מֵהַתּוֹרָה בִּשְׁבִיל פִּקּוּחַ־נֶפֶשׁ, כִּי בִּימֵי חַיָּיו יְתַקֵּן יוֹתֵר צִיּוּר הָאוֹר לְטוֹבָה, וּכְעֵין שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל: חַלֵּל עָלָיו שַׁבָּת אֶחָד בִּשְׁבִיל שֶׁיִּשְׁמֹר שַׁבָּתוֹת הַרְבֵּה. חוּץ מֵעֲבוֹדָה זָרָה וְגִלּוּי־עֲרָיוֹת וּשְׁפִיכוּת־דָּמִים, שֶׁעַל־יָדָם נִתְקַלְקֵל צִיּוּר הָאוֹר כָּל־כָּךְ, עַד שֶׁמְּהַפֵּךְ הָאֱמֶת לְגַמְרֵי מֵהֵפֶךְ אֶל הֵפֶךְ, שֶׁעַל־יְדֵי־זֶה אִי אֶפְשָׁר לוֹ עוֹד לְצַיֵּר הָאוֹר לְטוֹבָה, מֵאַחַר שֶׁכְּבָר הָפַךְ הָאֱמֶת לְגַמְרֵי כַּמְבֹאָר בִּפְנִים, עַל־כֵּן עֲלֵיהֶם יֵהָרֵג וְאַל יַעֲבֹר. וְכֵן בִּשְׁעַת הַשְּׁמַד אוֹ כְּשֶׁהָעוֹבֵד־ כּוֹכָבִים מִתְכַּוֵּן לְהַעֲבִירוֹ עַל דָּת וּבְפַרְהֶסְיָא, אָז עַל כָּל הַמִּצְו?ֹת שֶׁבַּתּוֹרָה יֵהָרֵג וְאַל יַעֲבֹר, כִּי מֵאַחַר שֶׁמְּכַוֵּן לְהַעֲבִירוֹ עַל דָּת וְלַהֲפֹךְ הַקְּעָרָה עַל פִּיהָ, חַס וְשָׁלוֹם, לַהֲפֹךְ הָאֱמֶת וּלְצַיֵּר הָאוֹר לְהֵפֶךְ, חַס וְשָׁלוֹם, וְהוּא בְּפַרְהֶסְיָא בִּפְנֵי עֲשָׂרָה מִיִּשְׂרָאֵל, וְהַחִלּוּל־הַשֵּׁם בָּזֶה גָּדוֹל מְאֹד, וְגַם יְכוֹלִים רַבִּים לְהִכָּשֵׁל וְלִטְעוֹת מִן הָאֱמֶת עַל־יְדֵי־זֶה, חַס וְשָׁלוֹם, עַל־כֵּן אָז צָרִיךְ שֶׁיֵּהָרֵג וְאַל יַעֲבֹר אֲפִלּוּ עַל מִצְוָה קַלָּה שֶׁבַּתּוֹרָה, כְּדֵי שֶׁלֹּא יְקַלְקֵל צִיּוּר הָאוֹר לְגַמְרֵי, חַס וְשָׁלוֹם, עַל־יְדֵי־זֶה, וְלָמָּה לּוֹ חַיִּים, כִּי הֲלוֹא עִקַּר הַחַיִּים הוּא בְּחִינַת צִיּוּר הָאוֹר לְטוֹבָה וְלִבְרָכָה כַּנַּ"ל (הלכות יין נסך, הלכה ד, אותיות יד, כו). 
עא. מִי שֶׁלִּבּוֹ שָׁלֵם עִם הַשֵּׁם, וֶאֱמוּנָתוֹ חֲזָקָה, וּמַאֲמִין שֶׁהַכֹּל מִתְנַהֵג רַק בִּרְצוֹנוֹ יִתְבָּרַךְ, אֲזַי הוּא בְּשִׂמְחָה תָּמִיד וְאֵין לוֹ שׁוּם דְּאָגָה וָפַחַד כְּלָל מִשּׁוּם דָּב

). 
עב. הַשֵּׁם יִתְבָּרַךְ בָּרָא אֶת הָעוֹלָם בְּגוּף וָנֶפֶשׁ, חֹמֶר וְצוּרָה, וְכַוָּנָתוֹ הָיָה כְּדֵי לְהַכְנִיעַ הַגּוּף לְגַבֵּי הַנֶּפֶשׁ, וְזֶה עִקַּר עֲבוֹדָתֵנוּ. וּכְמוֹ שֶׁבִּפְרָטִיּוּת צָרִיךְ כָּל אָדָם לְהִתְגַּבֵּר לְבַטֵּל הַגּוּף לְגַבֵּי הַנֶּפֶשׁ, שֶׁכָּל פְּעֻלּוֹת הַגּוּף יִהְיֶה רַק בִּשְׁבִיל הַנֶּפֶשׁ, הַיְנוּ לַעֲשׂוֹת רְצוֹנוֹ יִתְבָּרַךְ, שֶׁזֶּה תְּשׁוּקַת הַנֶּפֶשׁ; כְּמוֹ־כֵן בִּכְלָלִיּוּת הָעוֹלָם, יִשְׂרָאֵל עַם קָדוֹשׁ הֵם בְּחִינַת הַנֶּפֶשׁ וְהַנְּשָׁמָה שֶׁל כָּל הָעוֹלָם, וְכָל אֻמִּין דְּעָלְמָא וְכָל הַבְּרוּאִים כֻּלָּם הֵם בְּחִינַת גּוּף כְּנֶגֶד יִשְׂרָאֵל, וְכֻלָּם צְרִיכִים לִהְיוֹת נִכְנָעִים וּבְטֵלִים לְגַבֵּי הַנֶּפֶשׁ שֶׁהֵם יִשְׂרָאֵל וְלַעֲשׂוֹת רְצוֹנָם, כִּי אֵין לָהֶם שׁוּם קִיּוּם וְחַיּוּת בְּלֹא יִשְׂרָאֵל, כְּמוֹ שֶׁאֵין חַיּוּת לַגּוּף בְּלֹא הַנְּשָׁמָה. וְעִקַּר הַתַּכְלִית שֶׁל כָּל הַבְּרִיאָה כֻּלָּהּ בִּכְלָל וּבִפְרָט הוּא, שֶׁיִּתְבַּטֵּל הַחֹמֶר וְהַגּוּף לְגַבֵּי הַנְּשָׁמָה, לְהַפְשִׁיט כָּל דָּבָר מִגַּשְׁמִיּוּתוֹ וּמֵחָמְרִיּוּתוֹ, לַהֲפֹךְ מֵחֹמֶר לְצוּרָה, מִגּוּף לְנֶפֶשׁ, כְּדֵי שֶׁיַּעֲלֶה וְיִכָּלֵל וְיִתְדַּבֵּק בְּשָׁרְשׁוֹ וְיָשׁוּב לִמְקוֹר חוֹצְבוֹ שֶׁבַּקְּדֻשָּׁה, מְקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה קֹדֶם שֶׁנִּבְרָא, וְזֶה עִקַּר עֲבוֹדַת הָאָדָם בָּעוֹלָם הַזֶּה, וְזֶה כְּלַל כָּל הַתּוֹרָה וְהַמִּצְוָה, כִּי הַשֵּׁם יִתְבָּרַךְ שִׁעֵר בְּדַעְתּוֹ שֶׁעַל־יְדֵי מִצְו?ֹת אֵלּוּ נוּכַל לְהַכִּיר אוֹתוֹ יִתְבָּרַךְ. וּצְרִיכִין דַּיְקָא לַעֲשׂוֹת הַמִּצְוָה בְּפֹעַל בְּעֻבְדָּא דַיְקָא, כִּי כָּךְ שִׁעֵר הַשֵּׁם יִתְבָּרַךְ, שֶׁעַל־יְדֵי עֲשִׂיַּת הַמִּצְו?ֹת הָאֵלּוּ בְּמַעֲשֶׂה דַיְקָא, עַל־יְדֵי־זֶה אָנוּ יְכוֹלִין לְזַכֵּךְ גַּשְׁמִיּוּת גּוּפֵנוּ וְגַשְׁמִיּוּת כָּל הָעוֹלָם, עַד שֶׁיִּתְהַפֵּךְ מֵחֹמֶר לְצוּרָה בִּכְלָל וּבִפְרָט, כְּדֵי שֶׁיַּעֲלוּ וְיִכָּלְלוּ כָּל הַדְּבָרִים בְּשָׁרְשָׁן כַּנַּ"ל, דְּהַיְנוּ לָדַעַת וּלְהַכִּיר אוֹתוֹ יִתְבָּרַךְ, שֶׁזֶּהוּ תַּכְלִית שֶׁל כָּל הַבְּרִיאָה כֻּלָּהּ, שֶׁהוּא בְּגִין דְּיִשְׁתְּמוֹדְעִין לֵהּ. וְעַל־כֵּן אֱמוּנָה הוּא יְסוֹד כָּל הַתּוֹרָה, כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל: בָּא חֲבַקּוּק וְהֶעֱמִידוֹ עַל אֱמוּנָה, כִּי זֶה עִקַּר הַתַּכְלִית שֶׁל כָּל הַבְּרִיאָה, לִזְכּוֹת לֶאֱמוּנָה, לְהַאֲמִין שֶׁהַשֵּׁם יִתְבָּרַךְ בָּרָא הַכֹּל בַּעֲשָׂרָה מַאֲמָרוֹת, וְהוּא יִתְבָּרַךְ מְחַיֶּה אֶת כֻּלָּם, שֶׁעַל־יְדֵי־זֶה שֶׁמַּאֲמִינִים שֶׁכָּל הַחַיּוּת הוּא רַק מֵהַשֵּׁם יִתְבָּרַךְ לְבַד, עַל־יְדֵי־זֶה מַעֲלִין וּמְרִימִין כָּל הַדְּבָרִים לְהַשֵּׁם יִתְבָּרַךְ. וְעַל־כֵּן אֵין שׁוּם דָּבָר עוֹמֵד בִּפְנֵי פִּקּוּחַ־נֶפֶשׁ מִיִּשְׂרָאֵל, חוּץ מֵעֲבוֹדָה זָרָה וְגִלּוּי־עֲרָיוֹת וּשְׁפִיכוּת־דָּמִים, כִּי כָּל נֶפֶשׁ מִיִּשְׂרָאֵל כְּלוּלָה מֵרְמַ"ח אֵיבָרִים וּשְׁסָ"ה גִּידִים, שֶׁהֵם בְּחִינַת כְּלַל כָּל הַתּוֹרָה כֻּלָּהּ, רְמַ"ח מִצְו?ֹת עֲשֵׂה וּשְׁסָ"ה מִצְו?ֹת לֹאשׂ תַעֲשֶׂה; וְכָל זְמַן שֶׁמִּתְקַיֵּם בָּעוֹלָם הַזֶּה עוֹד נֶפֶשׁ אֶחָד מִיִּשְׂרָאֵל בְּיוֹתֵר, עַל־יְדֵי־זֶה מִתְגַּבֵּר בְּיוֹתֵר הַנְּשָׁמָה עַל הַגּוּף, כִּי יִשְׂרָאֵל הֵם בְּחִינַת נֶפֶשׁ וְצוּרָה נֶגֶד כְּלַל הָעוֹלָם כַּנַּ"ל, וְכָל מִצְוָה הוּא רַק בְּחִינַת פְּרָט אֶחָד, שֶׁעַל־יְדֵי־ זֶה נִכְלָל אֵיזֶה חֵלֶק וּבְחִינָה מֵהָעוֹלָם בְּשָׁרְשׁוֹ, אֲבָל נֶפֶשׁ מִיִּשְׂרָאֵל הִיא כְּלָלִיּוּת כָּל הַתּוֹרָה כֻּלָּהּ, וְהוּא בְּעַצְמוֹ בְּחִינַת נֶפֶשׁ שֶׁל כָּל הָעוֹלָם כֻּלּוֹ, וְעַל־כֵּן כָּל מִצְו?ֹת הַתּוֹרָה נִדְחִין מִפְּנֵי פִּקּוּחַ־נֶפֶשׁ. אַךְ כָּל זֶה כְּשֶׁנִּשְׁאָר הָאֱמוּנָה בִּשְׁלֵמוּת, שֶׁאָז אַף־עַל־ פִּי שֶׁמֻּכְרָח לַעֲבֹר עַל אֵיזֶה מִצְוָה, חַס וְשָׁלוֹם, מִפְּנֵי פִּקּוּחַ־נֶפֶשׁ, עֲדַיִן הוּא מְקֻשָּׁר בְּהַשֵּׁם יִתְבָּרַךְ עַל־יְדֵי אֱמוּנָה לְבַד, וְיָכוֹל לִחְיוֹת בְּעַצְמוֹ וּלְהָרִים וּלְהַגְבִּיהַּ אֶת כָּל הָעוֹלָם כֻּלּוֹ לְהַשֵּׁם יִתְבָּרַךְ עַל־יְדֵי אֱמוּנָתוֹ לְבַד, שֶׁמַּאֲמִין שֶׁהַשֵּׁם יִתְבָּרַךְ בָּרָא אֶת כָּל הָעוֹלָם בַּעֲשָׂרָה מַאֲמָרוֹת שֶׁבָּהֶן נֶעְלָמִין הָעֲשֶׂרֶת הַדִּבְּרוֹת שֶׁהֵם כְּלַל כָּל הַתּוֹרָה, שֶׁזֶּה הָיָה הַחַיּוּת וְהַקִּיּוּם שֶׁל הָעוֹלָם קֹדֶם מַתַּן־תּוֹרָה. וְעַל־כֵּן גַּם עַכְשָׁו, כְּשֶׁצְּרִיכִין, חַס וְשָׁלוֹם, לַעֲבֹר עַל מִצְו?ֹת הַתּוֹרָה בִּשְׁבִיל פִּקּוּחַ־נֶפֶשׁ, הוּא בְּחִינַת 'בִּטּוּלָהּ שֶׁל תּוֹרָה זֶהוּ קִיּוּמָהּ', וּכְמַאֲמַר רַבּוֹתֵינוּ זַ"ל: חַלֵּל עָלָיו שַׁבָּת אֶחָד בִּשְׁבִיל שֶׁיִּשְׁמֹר שַׁבָּתוֹת הַרְבֵּה, שֶׁאָז בִּשְׁעַת בִּטּוּלָהּ שֶׁל תּוֹרָה, מְקַבְּלִין חַיּוּת מֵהַתּוֹרָה הַנֶּעְלֶמֶת הַנַּ"ל, שֶׁזֶּה הָיָה קִיּוּם הָעוֹלָם קֹדֶם מַתַּן־תּוֹרָה. אֲבָל כְּשֶׁרוֹצִין שֶׁיַּעֲבֹד עֲבוֹדָה זָרָה, חָלִילָה, אֲזַי בְּוַדַּאי צָרִיךְ שֶׁיֵּהָרֵג וְאַל יַעֲבֹר, כִּי תֵּכֶף כְּשֶׁפּוֹגֵם, חַס וְשָׁלוֹם, בֶּאֱמוּנָה, שׁוּב אֵין לוֹ שׁוּם חַיּוּת כְּלָל וְנֶעֱקָר מִשָּׁרְשׁוֹ לְגַמְרֵי וּמַחֲרִיב כָּל הָעוֹלָם כֻּלּוֹ וְכֹל אֲשֶׁר בּוֹ, אֲשֶׁר כֻּלָּם תְּלוּיִים בּוֹ, שֶׁיֶּשׁ לוֹ כֹחַ לְהַגְבִּיהַּ כֻּלָּם וּלְהַעֲלוֹתָם לְשָׁרְשָׁם הָאֲמִתִּי עַל־יְדֵי הָאֱמוּנָה שֶׁמַּאֲמִין בּוֹ יִתְבָּרַךְ שֶׁבָּרָא אֶת כֻּלָּם כַּנַּ"ל. וּכְשֶׁפּוֹגֵם בֶּאֱמוּנָה, חַס וְשָׁלוֹם, אֲזַי נֶעֱקָר לְגַמְרֵי מִשֹּׁרֶשׁ חַיּוּתוֹ, וּבְוַדַּאי אֵין צְרִיכִין אוֹתוֹ עוֹד בָּעוֹלָם כְּלָל, כִּי לֹא דַי שֶׁאֵינוֹ יָכוֹל לְקַיֵּם אֶת הָעוֹלָם, אַדְּרַבָּה הוּא מַחֲרִיב לְגַמְרֵי אֶת הָעוֹלָם, שֶׁחַיּוּת וְקִיּוּם כָּל הָעוֹלָם הוּא רַק עַל־יְדֵי אֱמוּנָה, כְּמוֹ שֶׁנֶּאֱמַר: "וְכָל מַעֲשֵׂהוּ בֶּאֱמוּנָה". וְכֵן עַל שְׁפִיכוּת־דָּמִים גַּם־כֵּן יֵהָרֵג וְאַל יַעֲבֹר, כִּי אֵין דּוֹחִין נֶפֶשׁ מִפְּנֵי נֶפֶשׁ, כִּי כָּל אֶחָד מִיִּשְׂרָאֵל עַל־יְדֵי חֹזֶק אֱמוּנָתוֹ לְבַד, הוּא בְּחִינַת הַנֶּפֶשׁ וְהַחַיּוּת שֶׁל כָּל הָעוֹלָם, וְעַל־כֵּן כָּל זְמַן שֶׁשֵּׁם יִשְׂרָאֵל נִקְרָא עָלָיו, דְּהַיְנוּ שֶׁיֶּשׁ לוֹ אֱמוּנָה בְּהַשֵּׁם יִתְבָּרַךְ, אָנוּ צְרִיכִין אוֹתוֹ שֶׁיִּתְקַיֵּם בָּעוֹלָם, וְאֵין דּוֹחִין אוֹתוֹ לְהָרְגוֹ מִפְּנֵי חֲבֵרוֹ, אֲפִלּוּ אִם הוּא גָּדוֹל מִמֶּנּוּ הַרְבֵּה, כִּי מִי יוֹדֵעַ גֹּדֶל כֹּחוֹ שֶׁל זֶה בְּעִנְיַן חִזּוּק הָאֱמוּנָה; כְּמוֹ שֶׁאָנוּ רוֹאִים בְּחוּשׁ, שֶׁלִּפְעָמִים הַקַּל שֶׁבַּקַּלִּים מוֹסֵר נַפְשׁוֹ עַל קְדֻשַּׁת הַשֵּׁם יוֹתֵר מִגָּדוֹל שֶׁבְּיִשְׂרָאֵל, וְעַל־ כֵּן אֵין דּוֹחִין נֶפֶשׁ מִפְּנֵי נֶפֶשׁ לְעוֹלָם, כִּי כָּל אֶחָד מִיִּשְׂרָאֵל, כָּל זְמַן שֶׁיֶּשׁ לוֹ אֱמוּנָה, צְרִיכִין אוֹתוֹ שֶׁיִּתְקַיֵּם בָּעוֹלָם, כִּי כָּל אֶחָד מִיִּשְׂרָאֵל מַכְרִיעַ כָּל הָעוֹלָם כֻּלּוֹ לְהַשֵּׁם יִתְבָּרַךְ לְפִי בְּחִינָתוֹ עַל־יְדֵי אֱמוּנָתוֹ לְבַד, וְאִי אֶפְשָׁר לָנוּ לְהַעֲרִיךְ בֵּין נֶפֶשׁ לְנֶפֶשׁ, כִּי מִי יוֹדֵעַ הַכֹּחַ שֶׁל כָּל אֶחָד בְּשֹׁרֶשׁ אֱמוּנָתוֹ. וְעַל־כֵּן מִי שֶׁהוּא אֶפִּיקוֹרוֹס וְאֵין לוֹ אֱמוּנָה, הוּא מֵאֵלּוּ שֶׁמּוֹרִידִין וְלֹא מַעֲלִין, כִּי עִקַּר יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ וְחַיּוּת כָּל הָעוֹלָמוֹת כֻּלָּם הוּא רַק עַל־יְדֵי אֱמוּנָה כַּנַּ"ל. וְעַל־כֵּן בִּשְׁבִיל גִּלּוּי־עֲרָיוֹת גַּם־כֵּן יֵהָרֵג וְאַל יַעֲבֹר, כִּי שְׁמִירַת הַבְּרִית הוּא גַּם־כֵּן יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ, וְעִקַּר קִיּוּם הָאֱמוּנָה תָּלוּי בִּשְׁמִירַת הַבְּרִית. וְהַפּוֹגֵם בָּזֶה, הוּא גַּם־כֵּן כְּאִלּוּ עוֹקֵר חַיּוּת כָּל הַנְּפָשׁוֹת וְחַיּוּת כָּל הָעוֹלָם מִשָּׁרְשׁוֹ, וּמַגְבִּיר הַגּוּף עַל הַנֶּפֶשׁ, הַחֹמֶר עַל הַצּוּרָה, שֶׁזֶּה בְּעַצְמוֹ בְּחִינַת פְּגַם עֲבוֹדָה זָרָה. וְעַל־כֵּן אָמְרוּ רַבּוֹתֵינוּ זַ"ל שֶׁפְּגַם הַבְּרִית הוּא בְּחִינַת "אַל תִּפְנוּ אֶל הָאֱלִילִים", וְעַל־כֵּן מְחֻיָּב לִמְסֹר נַפְשׁוֹ וְחַיּוּתוֹ שֶׁלֹּא לַעֲבֹר עַל זֶה, חַס וְשָׁלוֹם (הלכות עבודה זרה הלכה ב, עיין פנים; ועיין יראה ועבודה, אותיות סב סג). 
עג. עַל־יְדֵי אֱמוּנָה שֶׁאָנוּ מַאֲמִינִים בּוֹ יִתְבָּרַךְ שֶׁבָּרָא הַכֹּל, וְכָל הַזְּמַן וְהַמָּקוֹם נִמְשָׁךְ מִמֶּנּוּ יִתְבָּרַךְ, מִבְּחִינַת לְמַעְלָה מֵהַזְּמַן וְהַמָּקוֹם, עַל־יְדֵי־זֶה אָנוּ מְקַשְּׁרִין וּמַעֲלִין הַמָּקוֹם וְהַזְּמַן לִבְחִינַת לְמַעְלָה מֵהַזְּמַן וְהַמָּקוֹם, וְאָז כָּל הַבְּרִיאָה כֻּלָּהּ בִּבְחִינַת לְמַעְלָה מֵהַזְּמַן וְהַמָּקוֹם, שֶׁהוּא בְּחִינַת הַשְׁגָּחָה, שֶׁזֶּה כְּלַל עֲבוֹדַת יִשְׂרָאֵל לְהַעֲלוֹת וּלְקַשֵּׁר וְלִכְלֹל כָּל הַבְּרִיאָה בִּבְחִינַת קֹדֶם הַ

). 
עט. בְּהַתּוֹרָה יֵשׁ חֻקִּים וּמִשְׁפָּטִים, וְעַל יְדֵי שֶׁמְּקַיְּמִין הַמִּשְׁפָּטִים שֶׁבַּתּוֹרָה, שֶׁהֵם אֵלּוּ הַמִּצְו?ֹת שֶׁיֵּשׁ בָּהֶם טַעַם וָשֵׂכֶל, עַל־יְדֵי־ זֶה מְבַטְּלִין כָּל הַקֻּשְׁיוֹת וְהַכְּפִירוֹת הַבָּאִים מֵהַקְּלִפּוֹת שֶׁנִּתְהַוּוּ מִבְּחִינַת שְׁבִירַת כֵּלִים, שֶׁשָּׁם יֵשׁ מְעַט שֵׂכֶל וְאוֹתִיּוֹת, אֲבָל יֵשׁ קֻשְׁיוֹת וּכְפִירוֹת כָּאֵלּוּ שֶׁאִי אֶפְשָׁר לִמְצֹא עֲלֵיהֶם שׁוּם תְּשׁוּבָה עַל־פִּי שֵׂכֶל לְיַשְּׁבוֹ, וְהֵם נִמְשָׁכִין מִבְּחִינַת חָלָל הַפָּנוּי, כַּמְבֹאָר בִּפְנִים. וְאֵלּוּ הַקֻּשְׁיוֹת מִתְבַּטְּלִין עַל־יְדֵי הַחֻקִּים שֶׁבַּתּוֹרָה, שֶׁהֵם הַמִּצְו?ֹת שֶׁאִי אֶפְשָׁר לָנוּ לְהָבִין וּלְהַשִּׂיג בָּהֶם שׁוּם טַעַם וָשֵׂכֶל כְּלָל, וְאָנוּ מְקַיְּמִין אוֹתָם רַק בֶּאֱמוּנָה לְבָד. וְעַל־יְדֵי כֹּחַ אֵלּוּ הַמִּצְו?ֹת נִתְחַזֵּק הָאֱמוּנָה אֶצְלֵנוּ לְגָרֵשׁ וּלְבַטֵּל וּלְבַעֵר מֵאִתָּנוּ כָּל הַקֻּשְׁיוֹת וְאֶפִּיקוֹרְסוּת הַנִּמְשָׁךְ מֵחָלָל הַפָּנוּי, שֶׁשָּׁם אִי אֶפְשָׁר לְהַשִּׂיג שׁוּם שֵׂכֶל וְחָכְמָה כְּלָל, רַק צְרִיכִין לְהִתְחַזֵּק בֶּאֱמוּנָה לְבָד. וְזֶה בְּחִינַת אִסּוּר מְעוֹנֵן וּמְנַחֵשׁ וּמְכַשֵּׁף, זֶה בְּחִינַת הַרְחָקַת הַכְּפִירוֹת הַבָּאִים מִשְּׁבִירַת כֵּלִים, שֶׁמִּשָּׁם נִמְשָׁכִין כָּל הַחָכְמוֹת שֶׁל הַמְנַחֲשִׁים וּמְעוֹנְנִים וּמְכַשְּׁפִים. וְאִסּוּר חֻקּוֹת הָעַכּוּ"ם שֶׁלֹּא לָלֶכֶת בְּחֻקּוֹתֵיהֶם הוּא לְרַחֵק כָּל הַכְּפִירוֹת וְהָאֶפִּיקוֹרְסוּת הַבָּאִים מִבְּחִינַת חָלָל הַפָּנוּי; כִּי הַשֵּׁם יִתְבָּרַךְ בְּרַחֲמָיו הִבְדִּילָנוּ מִכָּל הַתּוֹעִים הָאֵלֶּה, וְנָתַן לָנוּ אֶת הַתּוֹרָה שֶׁיְּסוֹדָהּ אֱמוּנָה, וְקִדְּשָׁנוּ בְּמִצְו?ֹתָיו הַקְּדוֹשִׁים שֶׁיֵּשׁ בָּהֶם חֻקִּים וּמִשְׁפָּטִים, שֶׁעַל־יְדֵי־זֶה אָנוּ מְבַטְּלִין וּמְגָרְשִׁין שְׁנֵי מִינֵי אֶפִּיקוֹרְסוּת וְקֻשְׁיוֹת הַנַּ"ל וְזוֹכִין לֶאֱמוּנָה שְׁלֵמָה (הלכות חוקות העמים, הל' ג). 
פ. כָּל הַהַשָּׂגוֹת וְכָל הַצִּמְצוּמִים דִּקְדֻשָּׁה שֶׁזּוֹכִין עַל־יָדָם לְהַשִּׂיג אֱלָקוּת, כֻּלָּם הֵם בְּחִינַת אֱמוּנָה שֶׁהוּא יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ, כְּמוֹ שֶׁנֶּאֱמַר: "כָּל מִצְו?ֹתֶיךָ אֱמוּנָה", וּכְתִיב: "צַדִּיק בֶּאֱמוּנָתוֹ יִחְיֶה". כִּי אֲנָשִׁים פְּשׁוּטִים וּקְטַנֵּי הָעֵרֶךְ, בְּוַדַּאי עִקַּר חַיּוּתָם וְתִקְוָתָם לִזְכּוֹת לְתַכְלִית הַנִּצְחִי הָאֲמִתִּי הוּא רַק עַל־יְדֵי אֱמוּנָה. אַךְ אֲפִלּוּ מִי שֶׁיֶּשׁ לוֹ שֵׂכֶל גָּדוֹל וְהוּא לַמְדָן וְחָרִיף גָּדוֹל בְּשַׁ"ס וּפוֹסְקִים, וַאֲפִלּוּ אִם יֶשׁ לוֹ יָד גַּם בְּחָכְמַת הַקַּבָּלָה, בַּזֹּהַר הַקָּדוֹשׁ וּבְכִתְבֵי הָאֲרִ"י זַ"ל - כָּל זְמַן שֶׁלֹּא זִכֵּךְ עַצְמוֹ מִזֻּהֲמַת הַנָּחָשׁ וְלֹא שִׁבֵּר עֲדַיִן לְגַמְרֵי תַּאֲוַת גּוּפוֹ וְחָמְרוֹ, וְיֶשׁ לוֹ עֲדַיִן אֵיזֶה אֲחִיזָה וְשֶׁמֶץ דָּבָר מִתַּאֲוַת הַגּוּף וְהַבְלֵי עוֹלָם הַזֶּה, בְּוַדַּאי עֲדַיִן אֵין שִׂכְלוֹ שָׁלֵם, וְאָסוּר לוֹ לִכְנֹס בְּשִׂכְלוֹ בְּחָכְמַת הַשָּׂגַת אֱלָקוּתוֹ יִתְבָּרַךְ, כִּי יוּכַל לְהִכָּשֵׁל וְלִפֹּל, חַס וְשָׁלוֹם, רַחֲמָנָא לִצְּלַן. וְעַל־כֵּן צָרִיךְ לְהִתְחַזֵּק רַק בֶּאֱמוּנָה וּלְהַשְׁלִיךְ שִׂכְלוֹ לְגַמְרֵי, וְלִסְמֹךְ עַל אֲבוֹתֵינוּ הַקְּדוֹשִׁים וְעַל הַצַּדִּיקִים אֲמִתִּיִּים אֲשֶׁר כָּפוּ אֶת יִצְרָם וְשָׁבְרוּ אֶת הַחֹמֶר לְגַמְרֵי, כִּי רַק הֵם זָכוּ לְהַשָּׂגַת אֱלָקוּתוֹ יִתְבָּרַךְ בְּתַכְלִית הַשְּׁלֵמוּת. וְאַף־עַל־פִּי־כֵן, אֲפִלּוּ צַדִּיקִים כָּאֵלּוּ, שֶׁטִּהֲרוּ וְקִדְּשׁוּ עַצְמָן מִזֻּהֲמַת הַנָּחָשׁ לְגַמְרֵי וְשָׁבְרוּ כָּל הַתַּאֲווֹת וּבִטְּלוּ אֶת הַגּוּף וְהַחֹמֶר לְגַמְרֵי, גַּם הֵם הָיָה עִקַּר הִתְחַזְּקוּת שֶׁלָּהֶם רַק עַל־יְדֵי הָאֱמוּנָה הַקְּדוֹשָׁה. כִּי אִי אֶפְשָׁר לְהַשִּׂיג שׁוּם הַשָּׂגָה וְלָדַעַת שׁוּם יְדִיעָה אֲמִתִּית בְּהִתְנוֹצְצוּת אֱלָקוּתוֹ יִתְבָּרַךְ, כִּי־אִם עַל־יְדֵי הָאֱמוּנָה הַקְּדוֹשָׁה, אֲשֶׁר הִיא הַשַּׁעַר שֶׁדֶּרֶךְ שָׁם נִכְנָסִין לְכָל הַקְּדֻשּׁוֹת וּלְכָל הַהַשָּׂגוֹת וּלְכָל הַיְדִיעוֹת הַקְּדוֹשִׁים, בִּבְחִינַת "בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ" - "זֹאת" הוּא בְּחִינַת מַלְכוּת, בְּחִינַת אֱמוּנָה, שֶׁהוּא יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ, בְּחִינַת "זֹאת הַתּוֹרָה וְכוּ'", "זֹאת" דַּיְקָא. וְזֶה שֶׁהֶאֱרִיךְ בַּתִּקּוּנִים: דְּלֵית רְשׁוּ לְנָבִיא וְחוֹזֶה לְאַעֲלָא לְקֻדְשָׁא בַּר מִנָּהּ וְכוּ'. כִּי אִי אֶפְשָׁר לְהִתְקָרֵב וְלִכְנֹס לְשׁוּם קְדֻשָּׁה וּלְשׁוּם הַשָּׂגָה וּלְשׁוּם יְדִיעָה מֵהַשֵּׁם יִתְבָּרַךְ כִּי־אִם עַל־יְדֵי הָאֱמוּנָה הַקְּדוֹשָׁה, וְכָל הַמִּלְחָמוֹת וְכָל הַנִּסְיוֹנוֹת שֶׁיֵּשׁ לְהָאָדָם בַּעֲבוֹדַת הַשֵּׁם, אִי אֶפְשָׁר לְנַצֵּחַ שׁוּם מִלְחָמָה וְלַעֲמֹד בְּנִסָּיוֹן כִּי־אִם עַל־יְדֵי הָאֱמוּנָה הַקְּדוֹשָׁה, כְּמוֹ שֶׁכָּתַב שָׁם בַּתִּקּוּנִים: וְדָוִד כַּד הָוֵי עָאל בִּקְרָבָא, לֹא אִתְרְחִיץ אֶלָּא בָּהּ, כְּמוֹ שֶׁכָּתוּב: "אִם תַּחֲנֶה עָלַי מַחֲנֶה וְכוּ' בְּזֹאת אֲנִי בוֹטֵחַ", הַיְנוּ שֶׁעִקַּר בִּטְחוֹנוֹ וְתִקְוָתוֹ הָיָה בֶּאֱמוּנָה שֶׁנִּקְרָא "זֹאת", דְּהַיְנוּ שֶׁהָיָה יוֹדֵעַ שֶׁהוּא חָזָק בֶּאֱמוּנָה בְּהַשֵּׁם יִתְבָּרַךְ, וְעַל־כֵּן הוּא חָזָק, שֶׁבְּוַדַּאי יַעֲמֹד נֶגֶד כָּל הַמַּחֲנוֹת וְהַמִּלְחָמוֹת שֶׁל הַיֵּצֶר הָרָע וְהַסִּטְרָא־אָחֳרָא, וּבְוַדַּאי יוּכַל לְנַצְּחָם וּלְשַׁבְּרָם, מֵאַחַר שֶׁיֶּשׁ לוֹ אֱמוּנָה חֲזָקָה בְּהַשֵּׁם יִתְבָּרַךְ שֶׁנִּקְרֵאת "זֹאת". וְהַנָּבִיא כְּשֶׁרָאָה אֹרֶךְ הַגָּלוּת, לֹא הָיָה לוֹ תִקְוָה לָצֵאת מִשָּׁם כִּי־אִם עַל־יְדֵי הָאֱמוּנָה שֶׁנִּקְרֵאת "זֹאת", כְּמוֹ שֶׁנֶּאֱמַר: "זֹאת אָשִׁיב אֶל לִבִּי עַל־כֵּן אוֹחִיל וְכוּ'", כִּי מִי שֶׁיִּהְיֶה חָזָק בֶּאֱמוּנָה, בְּוַדַּאי יִזְכֶּה לְנַצֵּחַ הַמִּלְחָמָה וְלָצֵאת מִן הַגָּלוּת בְּוַדַּאי. וְעַיֵּן בַּתִּקּוּנִים, שֶׁהֶאֱרִיךְ בְּעִנְיַן בְּחִינָה שֶׁל "זֹאת", שֶׁיַּעֲקֹב מָסַר "זֹאת" לְבָנָיו, וּמשֶׁה בֵּרַךְ אֶת יִשְׂרָאֵל בְּ"זֹאת", וְהַכֹּל הוֹלֵךְ וְסוֹבֵב עַל הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁנִּקְרֵאת "זֹאת"

). 
פא. הָאֱמוּנָה הוּא הַפֶּתַח וְהַשַּׁעַר לִכְנֹס עַל־יָדָהּ בְּהַשָּׂגַת אֱלָקוּתוֹ כַּנַּ"ל, וְהוּא גַּם־כֵּן הַסּוֹף וְהַתַּכְלִית שֶׁל כָּל הַיְדִיעוֹת וְהַהַשָּׂגוֹת, בִּבְחִינַת: "תַּכְלִית הַיְדִיעָה - אֲשֶׁר לֹא נֵדַע", שֶׁזֶּהוּ בְּחִינַת אֱמוּנָה, כִּי זֶהוּ תַּכְלִית שֶׁל כָּל הַיְדִיעוֹת וְהַהַשָּׂגוֹת, שֶׁיּוֹדְעִין וּמַשִּׂיגִין שֶׁאִי אֶפְשָׁר לֵידַע כְּלָל רַק לְהַאֲמִין בּוֹ יִתְבָּרַךְ. וְזֶה בְּחִינַת: "אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אֱלֹקִים"; "אֲנִי" הוּא בְּחִינַת מַלְכוּת, בְּחִינַת אֱמוּנָה, כַּיָּדוּעַ. וְזֶה: "אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן", כִּי הַהַתְחָלָה הוּא מֵהָאֱמוּנָה, וְהַסּוֹף הוּא אֱמוּנָה, וְכָל מַה שֶּׁיּוֹדְעִין וּמַשִּׂיגִין יוֹתֵר בְּהַשָּׂגַת אֱלָקוּתוֹ יִתְבָּרַךְ, נִתְחַזֵּק הָאֱמוּנָה יוֹתֵר וְיוֹתֵר, וְזֶהוּ עִקַּר תַּכְלִית כָּל הַהַשָּׂגוֹת וִידִיעוֹת. וְעַל־כֵּן צְרִיכִין רַבִּי גָּדוֹל בְּיוֹתֵר שֶׁיּוּכַל לְהַכְנִיס הַשָּׂגַת אֱלָקוּתוֹ אֲפִלּוּ בְּהַפְּחוּתִים וְהַקְּטַנִּים מְאֹד, כִּי כָל הַשָּׂגוֹת וִידִיעוֹת הֵם רַק בִּבְחִינַת מָטֵי וְלָא מָטֵי, בְּגִין דְּלֵית מַחֲשָׁבָה תְּפִיסָא בֵּהּ כְּלָל. כִּי בֶּאֱמֶת עַל־פִּי חָכְמוֹת, בְּוַדַּאי אִי אֶפְשָׁר לְהַשִּׂיגוֹ וְלֵידַע מִמֶּנּוּ יִתְבָּרַךְ כְּלָל, כִּי יוּכַל לִתְעוֹת בְּחָכְמָתוֹ מְאֹד כְּדֶרֶךְ שֶׁתָּעוּ וְנָבוֹכוּ הַמְחַקְּרִים, רַחֲמָנָא לִצְּלַן, עַד שֶׁבָּאוּ לְאֶפִּיקוֹרְסוּת גָּמוּר עַל־יְדֵי טָעוּת חָכְמָתָם הַנְּבוֹכָה, וְעַל־כֵּן הָעִקָּר הִיא הָאֱמוּנָה. אֲבָל צְרִיכִין לְהַחֲיוֹת אֶת הָאֱמוּנָה וּלְחַזְּקָהּ עַל־יְדֵי הַמְשָׁכַת הַחַיּוּת מֵאוֹר הַפָּנִים שֶׁהוּא הַשֵּׂכֶל, וְזֶה נַעֲשֶׂה דַּיְקָא עַל־יְדֵי הַצַּדִּיקֵי הַדּוֹר הַגְּדוֹלִים בְּמַעֲלָה יְתֵרָה דַּיְקָא, שֶׁהֵם עוֹסְקִים לְהַכְנִיס בָּנוּ הָאֱמוּנָה הַקְּדוֹשָׁה, וּבְכָל הַתּוֹרוֹת וְהַהַשָּׂגוֹת שֶׁהֵם מְגַלִּין לָנוּ, עַל־יְדֵי־זֶה הֵם מְחַיִּין וּמְחַזְּקִין אֱמוּנָתֵנוּ הַקְּדוֹשָׁה; כִּי אַף־עַל־פִּי שֶׁאָנוּ רוֹאִין וּמְבִינִים שֶׁאֵין אָנוּ מְבִינִים דִּבְרֵיהֶם כְּלָל, וְחָכְמָתָם הַגְּדוֹלָה נֶעְלָם וְרָחוֹק מֵאִתָּנוּ מְאֹד, אַף־עַל־פִּי־כֵן כָּל חַד כְּפֻם מָה דִּמְשַׁעֵר בְּלִבֵּהּ, יָכוֹל לְהִתְנוֹצֵץ לוֹ מְעַט רְמָזִים גְּדוֹלִים וַחֲזָקִים כַּמָּה צְרִיכִין לְהִתְחַזֵּק בֶּאֱמוּנָה; כֻּלֵּי הַאי וְאוּלַי יִזְכֶּה גַּם־כֵּן לֵידַע וּלְהַשִּׂיג קְצָת לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ, אֲשֶׁר נֹעַם עֲרֵבוּת מְתִיקוּת הִתְנוֹצְצוּת אֶחָד אִי אֶפְשָׁר לְשַׁעֵר, וּכְדַאי לִסְבֹּל כָּל הַיִּסּוּרִים שֶׁבָּעוֹלָם וּלְשַׁבֵּר כָּל הַתַּאֲווֹת וּלְהִתְיַגֵּעַ וְלִטְרֹחַ בַּעֲבוֹדַת הַשֵּׁם בְּכָל הַטְרָחוֹת וִיגִיעוֹת בִּמְסִירַת־נֶפֶשׁ בֶּאֱמֶת בִּשְׁבִיל עֲרֵבוּת נְעִימוּת הִתְנוֹצְצוּת אֶחָד. אַשְׁרֵי הַזּוֹכֶה לִרְדֹּף אַחַר זֶה בֶּאֱמֶת. וְעַל־כֵּן רַק הַצַּדִּיקִים הָאֲמִתִּיִּים הַגְּדוֹלִים בְּיוֹתֵר מַכְנִיסִין בָּנוּ הָאֱמוּנָה הַשְּׁלֵמָה דִּקְדֻשָּׁה (שם אותיות י יא). 
פב. עִקַּר כָּל הַנִּסִּים וְהַנִּפְלָאוֹת וְהִתְגַּלּוּת אֱלָהוּת שֶׁהָיָה עַל יְדֵי משֶׁה רַבֵּנוּ, עָלָיו הַשָּׁלוֹם, וְכֵן כָּל הַהַשָּׂגוֹת הַגְּדוֹלוֹת וְהַנִּפְלָאוֹת שֶׁגִּלּוּ לָנוּ שְׁאָר הַצַּדִּיקֵי אֱמֶת, הַכֹּל הוּא רַק כְּדֵי לְחַזֵּק אוֹתָנוּ בֶּאֱמוּנָה שְׁלֵמָה, שֶׁזֶּה תַּכְלִית כָּל הַהַשָּׂגוֹת וְהַיְדִיעוֹת, בְּחִינַת: 'תַּכְלִית הַיְדִיעָה - אֲשֶׁר לֹא נֵדַע' כַּנַּ"ל. וְזֶה שֶׁכָּתוּב אַחַר כָּל הַנִּסִּים וְהַנִּפְלָאוֹת שֶׁעָשָׂה משֶׁה בִּיצִיאַת מִצְרַיִם, שֶׁהָיָה אָז הִתְגַּלּוּת אֱלָקוּת בְּאוֹר נִפְלָא וְגָדוֹל מְאֹד כַּיָּדוּעַ, וְאַחַר־כָּךְ: וַעֲנַן ה' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם וְכוּ', וְעַמּוּד אֵשׁ לָיְלָה, וְאַחַר־ כָּךְ הָיָה קְרִיעַת יַם סוּף בְּנִפְלָאוֹת גְּדוֹלוֹת וּבְהִתְגַּלּוּת אֱלָקוּת גָּדוֹל מְאֹד, עַד שֶׁרָאֲתָה שִׁפְחָה עַל הַיָּם וְכוּ' כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל. אַחַר כָּל זֶה כְּתִיב: "וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה וְכוּ', וַיַּאֲמִינוּ בַּה'" - רְאֵה וְהָבֵן וְהַבֵּט, כִּי אַחַר כָּל הַהַשָּׂגוֹת וְהַיְדִיעוֹת וְהַמּוֹפְתִים, עֲדַיִן צְרִיכִין לֶאֱמוּנָה, כִּי כָל הַנַּ"ל לֹא הָיָה אֶלָּא בִּשְׁבִיל חִזּוּק הָאֱמוּנָה, כָּל חַד כְּפֻם מָה דִּמְשַׁעֵר בְּלִבֵּהּ, כִּי לְעוֹלָם צְרִיכִין לְהִתְחַזֵּק בֶּאֱמוּנָה וּלְהַאֲמִין בְּהַשֵּׁם יִתְבָּרַךְ וּבְהַצַּדִּיקֵי אֱמֶת בִּפְשִׁיטוּת בְּלִי שׁוּם חָכְמוֹת, כִּי ה

). 
פו. הָאֱמוּנָה אַף עַל פִּי שֶׁהִיא לְמַטָּה מֵהַשֵּׂכֶל כַּיָּדוּעַ, כִּי אֵין אֱמוּנָה כִּי־אִם בְּמַה שֶּׁאֵין הַשֵּׂכֶל מֵבִין, אַף־עַל־פִּי־כֵן שָׁרְשָׁהּ נִמְשָׁךְ מִמָּקוֹם גָּבֹהַּ וְעֶלְיוֹן מְאֹד, שֶׁהוּא גָּבֹהַּ מִכָּל הַשִּׂכְלִיִּים. כִּי בְּחִינַת הָאֱמוּנָה הוּא בְּחִינַת "אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן", בְּחִינַת "מַגִּיד מֵרֵאשִׁית אַחֲרִית", בְּחִינַת "סוֹף מַעֲשֶׂה בְּמַחֲשָׁבָה תְּחִלָּה", וְכַמְבֹאָר כָּל זֶה בְּמָקוֹם אַחֵר (שם). 
פז. אֱמֶת וֶאֱמוּנָה הֵם שְׁנֵיהֶם אֶחָד. כִּי מִי שֶׁמַּאֲמִין בְּהָאֱמֶת, הוּא מְקֻשָּׁר אֶל הָאֱמֶת כְּאִלּוּ הוּא יוֹדֵעַ וּמַשִּׂיג אוֹתוֹ בְּשִׂכְלוֹ הֵיטֵב, וְאֵין חִלּוּק בֵּינֵיהֶם כְּלָל; אַדְּרַבָּה, עִקַּר הָאֱמֶת אִי אֶפְשָׁר לֵידַע וּלְהַשִּׂיג מֵחֲמַת רִבּוּי אוֹר, כִּי־אִם עַל־יְדֵי אֱמוּנָה, כִּי אֱמֶת וֶאֱמוּנָה הֵם בְּחִינַת אִישׁ וְאִשָּׁה, שֶׁעַל זֶה נֶאֱמַר: "לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ", הַיְנוּ כִּי אִי אֶפְשָׁר לֵהָנוֹת מֵהָאֱמֶת וּלְהוֹלִיד מִמֶּנּוּ לְבַדּוֹ, מֵחֲמַת שֶׁאִי אֶפְשָׁר לְקַבֵּל עֶצֶם אוֹר הָאֱמֶת, עַל־כֵּן אָמַר הַקָּדוֹשׁ־בָּרוּךְ־הוּא: "אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ", הַיְנוּ הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁהִיא בְּחִינַת "אֵשֶׁת חַיִל", בְּחִינַת "אִשָּׁה יִרְאַת ה'", בְּחִינַת הַכַּלָּה הַקְּדוֹשָׁה הַמְשֻׁבַּחַת בְּכָל סֵפֶר שִׁיר־הַשִּׁירִים, כִּי הָאֱמוּנָה הַקְּדוֹשָׁה נִקְרֵאת "כַּלָּה", כִּי הִיא כְּלוּלָה מֵהַכֹּל, כִּי כָּל הַשָּׂגוֹת אֱלָקוּת וְכָל הַיְדִיעוֹת הַגְּבוֹהוֹת, הַכֹּל אֵין יְכוֹלִין לְקַבֵּל כִּי־אִם עַל־יְדֵי אֱמוּנָה, כִּי הָאֱמוּנָה הִיא עֶצֶם מֵעֲצָמָיו וּבָשָׂר מִבְּשָׂרוֹ שֶׁל הָאֱמֶת, כִּי שְׁנֵיהֶם אֶחָד וְאִי אֶפְשָׁר לָזֶה בְּלֹא זֶה, וְכָל קִיּוּם הָעוֹלָם עַל־יְדֵי שְׁנֵיהֶם דַּיְקָא, בִּבְחִינַת "עַל־כֵּן יַעֲזָב־אִישׁ אֶת־אָבִיו וְאֶת אִמּוֹ", הַיְנוּ שֶׁצְּרִיכִין לַעֲזֹב אֶת כָּל הַחָכְמוֹת שֶׁהֵם בְּחִינַת אָב לַחָכְמָה וְאֵם לַבִּינָה, רַק לְדַבֵּק עַצְמוֹ בְּהָאִשָּׁה יִרְאַת־הַשֵּׁם, שֶׁהִיא בְּחִינַת הָאֱמוּנָה הַקְּדוֹשָׁה, שֶׁעִקַּר הִתְגַּלּוּת אֲמִתַּת הָאֱמֶת הוּא עַל־יָדָהּ, בִּבְחִינַת "וְהָיוּ לְבָשָׂר אֶחָד", שֶׁהָאֱמֶת וְהָאֱמוּנָה הֵם אֶחָד בְּתַכְלִית הָאַחְדוּת, כִּי מֵאַחַר שֶׁמַּאֲמִין בְּהָאֱמֶת לַאֲמִתּוֹ, אֲזַי נִכְלָל הָאֱמוּנָה בְּהָאֱמֶת בְּתַכְלִית הָאַחְדוּת, וְעַל־יְדֵי־זֶה נוֹלָדִים כָּל הַהַשָּׂגוֹת לָדַעַת מֵאֲמִתַּת אֱלָקוּתוֹ יִתְבָּרַךְ, כִּי אִי אֶפְשָׁר לָדַעַת מִמֶּנּוּ יִתְבָּרַךְ כִּי־אִם עַל־יְדֵי הִתְחַבְּרוּת אֱמֶת וֶאֱמוּנָה, כִּי אֱמֶת בְּלֹא אֱמוּנָה אִי אֶפְשָׁר לְקַבֵּל מֵחֲמַת רִבּוּי אוֹר כַּנַּ"ל, וֶאֱמוּנָה בְּלֹא אֱמֶת, בְּוַדַּאי אֵינוֹ כְּלוּם, כִּי כְּשֶׁאֵינוֹ מִסְתַּכֵּל עַל הָאֱמֶת, אֲזַי יוּכַל לָבוֹא לֶאֱמוּנוֹת כָּזְבִּיּוֹת, חַס וְשָׁלוֹם, כִּי עִקַּר קִיּוּם שֶׁל הָאֱמוּנָה הַקְּדוֹשָׁה הוּא עַל־יְדֵי אֱמֶת, בְּחִינַת "צֶדֶק כַּד אִתְחַבָּרַת בֶּאֱמֶת, אִתְעֲבִידַת אֱמוּנָה", הַיְנוּ כְּשֶׁמִּסְתַּכֵּל עַל הָאֱמֶת לַאֲמִתּוֹ, אָז בְּוַדַּאי רוֹאֶה בְּעֵינָיו שֶׁרָאוּי לְהַאֲמִין בַּאֲבוֹתֵינוּ הַקְּדוֹשִׁים וּבְהַצַּדִּיקֵי־אֱמֶת שֶׁמַּזְהִירִים אוֹתָנוּ לְקַיֵּם תּוֹרָתֵנוּ הַקְּדוֹשָׁה, וְאָז אִתְעֲבִידַת אֱמוּנָה, שֶׁזּוֹכִין לֶאֱמוּנָה הַקְּדוֹשָׁה בִּשְׁלֵמוּת, וְאָז נִכְלָל אֱמֶת וֶאֱמוּנָה יַחַד, כִּי בֶּאֱמֶת שְׁנֵיהֶם אֶחָד כַּנַּ"ל, וְעַל־יְדֵי־זֶה נוֹלָדִין כָּל הַהַשָּׂגוֹת וְהַיְדִיעוֹת, כִּי עַל־יְדֵי אֱמוּנָה זוֹכִין אַחַר־כָּךְ לְהַשָּׂגוֹת וִידִיעוֹת גְּבוֹהוֹת מְאֹד, כַּמְבֹאָר בְּמָקוֹם אַחֵר, וְעַל־יְדֵי אֵלּוּ הַיְדִיעוֹת מוֹלִידִין נְפָשׁוֹת מַמָּשׁ, כִּי כָּל מַה שֶּׁהַצַּדִּיקִים זוֹכִין לְהַשִּׂיג הַשָּׂגוֹת גְּבוֹהוֹת בְּיוֹתֵר עַל־יְדֵי הִתְחַבְּרוּת אֱמֶת וֶאֱמוּנָה כַּנַּ"ל, עַל־יְדֵי־זֶה יְכוֹלִין לְהַכְנִיס הָאֱמוּנָה הַקְּדוֹשָׁה בְּלֵב כָּל הַנְּפָשׁוֹת הַיְרוּדוֹת וְהָרְחוֹקוֹת מִמֶּנּוּ יִתְבָּרַךְ מְאֹד מְאֹד, עַד שֶׁנֶּחְשָׁב כְּאִלּוּ עֲשָׂאָן כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל, וּכְאִלּוּ נוֹלְדוּ אֵל

). 
פח. קֹדֶם אֲכִילַת עֵץ הַדַּעַת כְּתִיב: "וַיִּהְיוּ שְׁנֵיהֶם עֲרוּמִּים הָאָדָם וְאִשְׁתּוֹ", כִּי אָז הָיוּ הָאֱמֶת וְהָאֱמוּנָה, שֶׁהֵם בְּחִינַת אִישׁ וְאִשְׁתּוֹ, עֲרֻמִּים בְּלִי שׁוּם לְבוּשׁ, כִּי הָיוּ יְכוֹלִין אָז לְקַבֵּל אוֹר הָאֱמֶת וְהָאֱמוּנָה בְּלִי לְבוּשִׁין, כִּי הָיוּ הַכֹּל רוֹאִין הָאֱמֶת וְהָאֱמוּנָה, שֶׁהָיוּ רוֹאִין עַיִן בְּעַיִן שֶׁאֲמִתַּת יְדִיעָתוֹ יִתְבָּרַךְ הוּא עַל־יְדֵי אֱמוּנָה, שֶׁזֶּה בְּחִינַת 'תַּכְלִית הַיְדִיעָה, אֲשֶׁר לֹא נֵדַע', שֶׁהִשִּׂיגוּ אֶת הָאֱמֶת בְּתַכְלִית הַיְדִיעָה עַד שֶׁרָאוּ וְיָדְעוּ בִּידִיעָה בְּרוּרָה אֲמִתַּת אֱלָקוּתוֹ יִתְבָּרַךְ, שֶׁאִי אֶפְשָׁר לֵידַע מִּמֶּנּוּ כִּי־אִם עַל־יְדֵי אֱמוּנָה, כְּמוֹ שֶׁיֵּשׁ גַּם עַתָּה כַּמָּה דְּבָרִים שֶׁאִם לֹא הָיוּ רוֹאִין אוֹתָם בָּעֵינַיִם בְּכָל יוֹם, הָיָה קָשֶׁה לְהַאֲמִין בָּהֶם, כְּגוֹן שֶׁיִּהְיֶה מִטִּפָּה סְרוּחָה נוֹצָר בֶּן־אָדָם, וְיִהְיֶה בְּבֶטֶן אִמּוֹ תִּשְׁעָה חֳדָשִׁים, וְאַחַר־כָּךְ יִתְגַּדֵּל מִזֶּה בֶּן־אָדָם הַשָּׁלֵם בְּדַעַת וּבְצוּרָה וְכוּ', וְכֵן מִגַּרְעִין אֶחָד הַנִּזְרָע בָּאָרֶץ וְנִתְבַּלֶּה, יִתְגַּדֵּל מִמֶּנּוּ אִילָן יָפֶה וְגָדוֹל עִם הַרְבֵּה עֲנָפִים וּפֵרוֹת - בְּוַדַּאי לֹא הָיָה הַשֵּׂכֶל הַפָּשׁוּט מַסְכִּים לָזֶה בְּשׁוּם אֹפֶן, וְכֵן בְּכָל פְּרָטֵי הַבְּרִיאָה. וּבֶאֱמֶת נֶאֱמַר עַל זֶה: "מַה גָּדְלוּ מַעֲשֶׂיךָ ה'", וְנֶאֱמַר: "מָה רַבּוּ מַעֲשֶׂיךָ ה'". נִמְצָא שֶׁהָאָדָם רוֹאֶה בְּעֵינָיו דְּבָרִים שֶׁאֵינוֹ מְבִינָם בְּשֵׂכֶל, שֶׁעַל־ יְדֵי־זֶה מֻכְרָח לְהִתְחַזֵּק בֶּאֱמוּנָה. וְקֹדֶם הַחֵטְא הָיְתָה יְדִיעַת הָאֱמֶת לַאֲמִתּוֹ, הַיְנוּ הַיְדִיעָה מִמֶּנּוּ יִתְבָּרַךְ, הָיְתָה פְּשׁוּטָה וּבְרוּרָה בְּתַכְלִית הַבֵּרוּר, עַד שֶׁהָיוּ יוֹדְעִין כִּי אִי אֶפְשָׁר לֵידַע מִמֶּנּוּ כִּי־אִם עַל־יְדֵי אֱמוּנָה, וּבֶאֱמֶת אֱמֶת וֶאֱמוּנָה שְׁנֵיהֶם אֶחָד בְּתַכְלִית הָאַחְדוּת כַּנַּ"ל; אֲבָל אַחַר הַחֵטְא, שֶׁנֶּאֱחַז בָּהֶם זֻהֲמַת הַנָּחָשׁ, עַל־יְדֵי־זֶה אִי אֶפְשָׁר לְקַבֵּל עַתָּה אוֹר הָאֱמֶת וְהָאֱמוּנָה כִּי־אִם עַל־יְדֵי לְבוּשִׁין, שֶׁהֵם בְּחִינַת כְּלַל הַתּוֹרָה הַקְּדוֹשָׁה, שֶׁנִּתְלַבְּשָׁה בְּכַמָּה לְבוּשִׁין בְּסוֹד 'חֲלוּקָא דְּרַבָּנָן'. וְכֵן כָּל הַחִדּוּשֵׁי־תוֹרָה שֶׁמְּחַדְּשִׁין לָנוּ הַצַּדִּיקִים שֶׁבְּכָל דּוֹר וּמְבָאֲרִין לָנוּ דַּרְכֵי הַתּוֹרָה הַקְּדוֹשָׁה שֶׁיְּסוֹדָהּ אֱמֶת וֶאֱמוּנָה, הַיְנוּ שֶׁעַכְשָׁו אִי אֶפְשָׁר לְקַבֵּל הָאֱמֶת וְהָאֱמוּנָה בִּשְׁלֵמוּת כִּי־אִם עַל־יְדֵי כַּמָּה לְבוּשִׁין וְהַקְדָּמוֹת שֶׁהַצַּדִּיקִים מְבָאֲרִים לָנוּ עַל־יְדֵי נִפְלְאוֹת חִדּוּשֵׁי תּוֹרָתָם, שֶׁהַכֹּל הוּא רַק בִּשְׁבִיל לְהַמְשִׁיךְ בָּנוּ אֱמוּנָה שְׁלֵמָה בְּאֹפֶן שֶׁנִּזְכֶּה עַל־יְדֵי־זֶה לְקַבֵּל אוֹר הָאֱמֶת, וְהֵם בְּחִינַת לְבוּשִׁים שֶׁמַּלְבִּישִׁים בָּהֶם אֶת הָאֱמֶת וְהָאֱמוּנָה, וּמִשָּׁם נִמְשָׁכִין כָּל הַמַּלְבּוּשִׁים שֶׁבָּעוֹלָם שֶׁנִּתְהַוּוּ אַחַר הַחֵטְא, שֶׁהֵם תִּקּוּן גָּדוֹל כְּדֵי שֶׁלֹּא יִהְיֶה כֹּחַ לְזֻהֲמַת הַנָּחָשׁ, חַס וְשָׁלוֹם, לְהִתְאַחֵז בְּהָאֱמֶת וְהָאֱמוּנָה וְלִפְגֹּם אוֹתָם, חַס וְשָׁלוֹם. אַךְ הַמַּלְבּוּשִׁים צְרִיכִין גַּם־כֵּן תִּקּוּן וּשְׁמִירָה, וְתִקּוּנָם הוּא עַל־יְדֵי מִצְוַת צִיצִת, שֶׁעַל־יְדֵי מִצְוַת צִיצִת עִקַּר הַמְשָׁכַת הָאֱמֶת וְהָאֱמוּנָה, כַּמְבֹאָר בִּפְנִים. וְזֶה בְּחִינַת הָאִסּוּר שֶׁ"לֹּא יִלְבַּשׁ גֶּבֶר שִׂמְלַת אִשָּׁה וְכוּ'", כִּי יֵשׁ לְבוּשֵׁי אֱמֶת וּלְבוּשֵׁי אֱמוּנָה, שֶׁזֶּה בְּחִינַת לְבוּשֵׁי אִישׁ וּלְבוּשֵׁי אִשָּׁה, אַךְ דֶּרֶךְ הַסִּטְרָא־אָחֳרָא, שֶׁהֵם הֵיכְלֵי הַתְּמוּרוֹת, שֶׁהֵם מְמִירִין וּמַחֲלִיפִין וְרוֹצִים לִסְתֹּר וּלְהַעְלִים אֶת הָאֱמֶת דִּקְדֻשָּׁה, הַיְנוּ מַה שֶּׁהַשֵּׂכֶל דִּקְדֻשָּׁה מַשִּׂיג וּמֵבִין שֶׁכָּךְ הוּא הָאֱמֶת, וְהֵם רוֹצִים לְסָתְרוֹ בְּהָאֱמוּנוֹת כָּזְבִּיּוֹת שֶׁלָּהֶם, שֶׁזֶּה בְּחִינָה שֶׁמַּלְבִּישִׁים וּמַעֲלִימִין הָאֱמֶת עַל־יְדֵי לְבוּשֵׁי אִשָּׁה. וְכֵן בְּמָקוֹם שֶׁמְּבִינִים עַל־פִּי הָאֱמֶת שֶׁצְּרִיכִין לְהַאֲמִין, הֵם רוֹצִים לִסְתֹּר הָאֱמוּנָה דִּקְדֻשָּׁה עַל־יְדֵי הָאֱמֶת הַמְדֻמֶּה וְהַמֻּטְעֶה שֶׁלָּהֶם, כִּי מַה שֶּׁהַשֵּׂכֶל וְהַיְדִיעָה מַסְכִּים לָזֶה, זֶה בְּחִינַת אֱמֶת, וּמֵחֲמַת שֶׁאֵין הַשֵּׂכֶל הַמְשֻׁבָּשׁ שֶׁלָּהֶם מַסְכִּים לְהָאֱמוּנָה הַקְּדוֹשָׁה, עַל־כֵּן רוֹצִים לְסָתְרָהּ וּלְהַעְלִימָהּ, חַס וְשָׁלוֹם, שֶׁזֶּה בְּחִינָה שֶׁמַּלְבִּישִׁין הָאִשָּׁה, שֶׁהִיא בְּחִינַת אֱמוּנָה, שִׂמְלַת גֶּבֶר, כִּי בְּמָקוֹם שֶׁהַשֵּׂכֶל הָאֱמֶת מֵבִין שֶׁאִי אֶפְשָׁר לְהַשִּׂיג, רַק שֶׁצְּרִיכִין לִסְמֹךְ עַל אֱמוּנָה, שָׁם הֵם רוֹצִים דַּיְקָא לְהָבִין בְּשִׂכְלָם, שֶׁזֶּה שֹׁרֶשׁ כָּל הַכְּפִירוֹת וְהָאֱמוּנוֹת כָּזְבִּיּוֹת. וְזֶה שֶׁפֵּרֵשׁ רַשִׁ"י שֶׁדָּבָר זֶה גּוֹרֵם לְנִאוּף, כִּי עִקַּר הַנִּאוּף נִמְשָׁךְ מִכְּפִירוֹת, כַּמְבֹאָר בִּפְנִים. אֲבָל הַשֵּׁם יִתְבָּרַךְ הִבְדִּילָנוּ מֵהֶם וְהֵאִיר בָּנוּ נְקֻדַּת הָאֱמֶת עַל־יְדֵי הַצַּדִּיקִים אֲמִתִּיִּים שֶׁמַּלְבִּישִׁין אֶת הָאֱמֶת וְהָאֱמוּנָה בִּבְחִינַת 'חֲלוּקָא דְּרַבָּנָן', לְבוּשֵׁי קֹדֶשׁ, שֶׁהֵם חִדּוּשֵׁי תּוֹרָתָם הַנּוֹרָאִים, שֶׁעַל־יְדֵי־זֶה הֵם מַכְנִיסִין בָּנוּ אֱמֶת וֶאֱמוּנָה, שֶׁעַל־יְדֵי־זֶה אָנוּ זוֹכִין לְהִסְתַּכֵּל עַל הָאֱמֶת, הַיְנוּ עַל הַסְכָּמַת הַשֵּׂכֶל הָאֲמִתִּי, בִּכְדֵי לָסוּר עַל־יְדֵי־זֶה מֵאֱמוּנוֹת כָּזְבִּיּוֹת, שֶׁבִּשְׁבִיל זֶה עִקַּר שְׁלֵמוּת הָאֱמוּנָה הוּא עַל־יְדֵי אֱמֶת כַּנַּ"ל. וְכֵן עַל־יְדֵי הָאֱמֶת הַזֶּה אָנוּ זוֹכִין לְהִתְחַזֵּק בֶּאֱמוּנָה הַקְּדוֹשָׁה בְּמָקוֹם שֶׁאִי אֶפְשָׁר לְהַשִּׂיג וּלְהָבִין בְּשׁוּם שֵׂכֶל, אַף־עַל־פִּי־כֵן הֵם מְבִינִים מֵרָחוֹק שֶׁכָּךְ הוּא הָאֱמֶת, רַק שֶׁאִי אֶפְשָׁר לְהָבִין וּלְהַשִּׂיג, וּצְרִיכִין לְהִתְחַזֵּק רַק בֶּאֱמוּנָה הַקְּדוֹשָׁה, כִּי בֶּאֱמֶת אִי אֶפְשָׁר לָדַעַת וּלְהַשִּׂיג בִּשְׁלֵמוּת אוֹתוֹ יִתְבָּרַךְ וְטַעֲמֵי הַמִּצְו?ֹת שֶׁל הַתּוֹרָה הַקְּדוֹשָׁה, וְכֵן קְדֻשַּׁת הַצַּדִּיקִים אֲמִתִּיִּים, רַק עַל־יְדֵי אֱמוּנָה כַּנַּ"ל (שם אותיות יא יב יג). 
