). 
צ. אִי אֶפְשָׁר לְהִתְדַּבֵּק וּלְהִתְקָרֵב לְהַשֵּׁם יִתְבָּרַךְ בֶּאֱמֶת כִּי־אִם עַל־יְדֵי אֱמוּנָה, שֶׁהוּא יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ. כָּל הָעוֹלָמוֹת, כָּל הַנֶּאֱצָלִים וְהַנִּבְרָאִים, הַנּוֹצָרִים וְהַנַּעֲשִׂים, כֻּלָּם עוֹמְדִים רַק עַל אֱמוּנָה, כְּמוֹ שֶׁנֶּאֱמַר: "וְכָל מַעֲשֵׂהוּ בֶּאֱמוּנָה". וְכָל תִּקּוּן הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי שֶׁעַל־יְדֵי־זֶה הָיְתָה כָּל הַבְּרִיאָה, הַכֹּל הָיָה בִּבְחִינַת אֱמוּנָה. כִּי זֶה יָדוּעַ בִּכְתָבִים, שֶׁתְּחִלַּת הַצִּמְצוּם הָיָה בִּבְחִינַת מַלְכוּת שֶׁבְּאֵין־סוֹף, וּמַלְכוּת הוּא בְּחִינַת אֱמוּנָה כַּיָּדוּעַ. כִּי הַשֵּׁם יִתְבָּרַךְ הִסְתַּכֵּל בְּחָכְמָתוֹ הַקְּדוֹשָׁה, שֶׁאִי אֶפְשָׁר לְהַכִּירוֹ וְלֵידַע מִמֶּנּוּ יִתְבָּרַךְ (שֶׁבִּשְׁבִיל זֶה הָיְתָה כָּל הַבְּרִיאָה, 'בְּגִין דְּיִשְׁתְּמוֹדְעִין לֵהּ') עַל־יְדֵי שׁוּם מִדָּה וְשׁוּם שֵׂכֶל וּסְפִירָה, כִּי־אִם עַל־יְדֵי אֱמוּנָה שֶׁהִיא בְּחִינַת מַלְכוּת שֶׁהוּא תְּחִלַּת הַצִּמְצוּם, שֶׁעַל־יָדָהּ עִקַּר הִתְגַּלּוּת כָּל הַמִּדּוֹת וְכָל הָעוֹלָמוֹת. וְזֶהוּ עִקַּר תְּחִלַּת הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי, דְּהַיְנוּ שֶׁצִּמְצֵם אֱלָקוּתוֹ כִּבְיָכוֹל, שֶׁהוּא הַשֵּׂכֶל, כִּי הַשֵּׁם יִתְבָּרַךְ הוּא עֶצֶם הַחָכְמָה כִּבְיָכוֹל, כַּיָּדוּעַ, וּכְשֶׁפִּנָּה הַשֵּׂכֶל מִשָּׁם, נִשְׁאַר הַמָּקוֹם פָּנוּי כִּבְיָכוֹל בְּלִי שֵׂכֶל, וְלֹא נִשְׁאַר שָׁם כִּי־אִם בְּחִינַת אֱמוּנָה, דְּהַיְנוּ שֶׁמַּאֲמִינִים בְּהָאֱמֶת בֶּאֱמוּנָה לְבַד בְּלִי שׁוּם שֵׂכֶל וְחָכְמָה. וְתֵכֶף כְּשֶׁנַּעֲשָׂה הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי, דְּהַיְנוּ בְּחִינַת אֱמוּנָה, אָז תֵּכֶף הִמְשִׁיךְ אֱלָקוּתוֹ לְתוֹךְ אוֹתוֹ הֶחָלָל הַפָּנוּי, שֶׁזֶּה בְּחִינַת כְּלַל הַמִּדּוֹת וְכָל הָעוֹלָמוֹת, מֵרֵאשִׁית נְקֻדַּת הַבְּרִיאָה שֶׁהוּא תְּחִלַּת הָאֲצִילוּת, עַד סוֹף נְקֻדַּת הַמֶּרְכָּז שֶׁל עוֹלָם הַגַּשְׁמִי הַזֶּה, וְכָל מַעֲשֵׂהוּ בֶּאֱמוּנָה כַּנַּ"ל. כִּי אַחַר־כָּךְ כְּשֶׁנִּתְהַוָּה מִדַּת הָאֱמוּנָה שֶׁהוּא תְּחִלַּת הַצִּמְצוּם, אָז יֵשׁ בְּכֹחַ לְגַלּוֹת אֱלָקוּתוֹ יִתְבָּרַךְ עַל־יְדֵי צִמְצוּמִים שֶׁל הַשֵּׂכֶל, שֶׁהֵם כְּלַל כָּל הַמִּדּוֹת וְהַסְּפִירוֹת, כִּי עַל־יְדֵי אֱמוּנָה זוֹכִין אַחַר־כָּךְ לְהָבִין בְּשֵׂכֶל, כְּמוֹ שֶׁנֶּאֱמַר: "וְאֵרַשְׂתִּיךְ לִי בֶּאֱמוּנָה", (וְהָדַר) "וְיָדַעַתְּ אֶת ה'", כִּי בַּתְּחִלָּה, קֹדֶם תִּקּוּן הַצִּמְצוּם שֶׁל הָאֱמוּנָה, אִי אֶפְשָׁר לְהָבִין בְּשֵׂכֶל, כִּי עֲדַיִן הַכֹּל אֶצְלוֹ בִּבְחִינַת אֵין־ סוֹף, כִּי כָּל מַה שֶּׁאֵין הָאָדָם מֵבִין, הוּא אֶצְלוֹ בִּבְחִינַת אֵין־סוֹף כַּיָּדוּעַ, כִּי אַף־עַל־ פִּי שֶׁבָּעוֹלָם הָעֶלְיוֹן וּבַמַּדְרֵגָה הָעֶלְיוֹנָה מִזֶּה, הַשָּׂגָה זוֹ הִיא בְּחִינַת צִמְצוּם, אֲבָל בָּעוֹלָם הַנָּמוּךְ מִמֶּנּוּ, הוּא עֲדַיִן בְּחִינַת אֵין־סוֹף, כִּי מַלְכוּת דִּיצִירָה הוּא בְּחִינַת אֵין־סוֹף נֶגֶד כֶּתֶר דַּעֲשִׂיָּה, כַּיָּדוּעַ וּמוּבָן. וְעַל־כֵּן בַּתְּחִלָּה אִי אֶפְשָׁר לְהָאָדָם שֶׁיָּבִין שׁוּם דָּבָר וְשׁוּם הַשָּׂגָה, כִּי הַכֹּל אֶצְלוֹ בְּחִינַת אֵין־סוֹף, וְצָרִיךְ שֶׁיִּהְיֶה לוֹ בַּתְּחִלָּה אֱמוּנָה שְׁלֵמָה לְבַד בְּלִי שׁוּם שֵׂכֶל, וְזֶהוּ בְּחִינַת הַצִּמְצוּם כַּנַּ"ל; וְאָז כְּשֶׁהוּא חָזָק בֶּאֱמוּנָתוֹ, אָז הַשֵּׁם יִתְבָּרַךְ מֵאִיר עֵינָיו וְזוֹכֶה לְהָבִין אַחַר־כָּךְ הַדָּבָר בְּשִׂכְלוֹ, שֶׁזֶּה בְּחִינַת הַמְשָׁכַת הָאוֹרוֹת וְהַמִּדּוֹת לְתוֹךְ הֶחָלָל הַפָּנוּי, לְתוֹךְ הַצִּמְצוּם, שֶׁהוּא בְּחִינַת אֱמוּנָה כַּנַּ"ל, כִּי הָאֱמוּנָה הוּא הַצִּמְצוּם וְהַכְּלִי שֶׁל כָּל הַמִּדּוֹת, שֶׁהֵם כֻּלָּם בְּחִינַת צִמְצוּמֵי הַשֵּׂכֶל מֵעִלָּה לְעָלוּל, מִשֵּׂכֶל עֶלְיוֹן לְשֵׂכֶל הַתַּחְתּוֹן, לְהַשִּׂיג עַל־יָדָם הַשָּׂגַת אֱלָקוּתוֹ יִתְבָּרַךְ, וְכֻלָּם אֵין לָהֶם כֹּחַ לְגַלּוֹת וּלְהוֹלִיד שׁוּם דַּעַת וְשׁוּם הַשָּׂגָה בּוֹ יִתְבָּרַךְ, כִּי־אִם עַל־יְדֵי הָאֱמוּנָה לְבַד, כִּי הָאֱמוּנָה הוּא הַכְּלִי וְהַצִּמְצוּם שֶׁל כֻּלָּם. וְזֶה בְּחִינַת מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, דְּלֵית רְשׁוּ לְשׁוּם סְפִירָה וְכוּ' לַאֲרָקָא בִּרְכָאן בַּר מִנָּהּ, כִּי עַל־יְדֵי אֱמוּנָה בְּחִינַת מַלְכוּת, עַל־יָדָהּ דַּיְקָא עִקַּר הִתְגַּלּוּת הַדַּעַת שֶׁל הַשָּׂגַת אֱלָקוּתוֹ יִתְבָּרַךְ (הל' נדה, הלכה ב). 
צא. זֶה הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי, הַיְנוּ מַה שֶּׁבְּחָכְמָתוֹ הַנִּפְלָאָה צִמְצֵם חָכְמָתוֹ כָּל־כָּךְ, עַד אֲשֶׁר סִלֵּק הַחָכְמָה וְהַשֵּׂכֶל לְגַמְרֵי, עַד שֶׁנִּשְׁאַר הַמָּקוֹם כִּבְיָכוֹל פָּנוּי מִכָּל הַשִּׂכְלִיּוּת וְהַחָכְמוֹת שֶׁהֵם עַצְמוּת אֱלָקוּתוֹ יִתְבָּרַךְ, וְלֹא נִשְׁאַר מִן הַשֵּׂכֶל כִּי־ אִם כֹּחַ הָאֱמוּנָה, שֶׁבָּרָא כֹּחַ בְּהָעוֹלָמוֹת וְהַנִּבְרָאִים שֶׁיִּהְיֶה לָהֶם שֵׂכֶל וָדַעַת לְהַאֲמִין בּוֹ יִתְבָּרַךְ בְּלִי שׁוּם שֵׂכֶל. וּבֶאֱמֶת זֶה הַצִּמְצוּם הוּא פֶּלֶא גָּדוֹל, כַּמּוּבָא בְּמָקוֹם אַחֵר, כִּי אֱמוּנָה הוּא פֶּלֶא גָּדוֹל, כְּמוֹ שֶׁנֶּאֱמַר: "אוֹדֶה שִׁמְךָ כִּי עָשִׂיתָ פֶּלֶא, עֵצוֹת מֵרָחֹק אֱמוּנָה אֹמֶן", כִּי אֱמוּנָה הוּא נִפְלְאוֹת תְּמִים דֵּעִים, כִּי בְּדָבָר שֶׁהַשֵּׂכֶל מֵבִין, אֵין צְרִיכִין לְהַאֲמִין וְאֵינוֹ נִקְרָא אֱמוּנָה, מֵאַחַר שֶׁגַּם הַשֵּׂכֶל מֵבִין זֶה, וְעִקַּר הָאֱמוּנָה הוּא בְּמַה שֶּׁאֵין מְבִינִים בַּשֵּׂכֶל. וְאִם־כֵּן, מֵאַחַר שֶׁאֵין הַשֵּׂכֶל מֵבִין וּמַשִּׂיג שָׁם, מֵהֵיכָן יָבוֹא לְדַעְתּוֹ שֶׁיַּאֲמִין בָּזֶה? אַךְ בֶּאֱמֶת הוּא נִפְלְאוֹת תְּמִים דֵּעִים, שֶׁבָּרָא בְּחָכְמָתוֹ הַגְּדוֹלָה כֹּחַ בְּשֵׂכֶל הָאָדָם, שֶׁיִּהְיֶה לוֹ כֹּחַ לְצַמְצֵם וּלְסַלֵּק דַּעְתּוֹ וּלְהַאֲמִין בֶּאֱמוּנָה לְבַד עַל־יְדֵי כֹּחַ הָרְשִׁימוּ שֶׁנִּשְׁאַר בְּהַדַּעַת גַּם לְאַחַר הִסְתַּלְּקוּת הַדַּעַת, כִּי אַף־עַל־גַב דְּאִיהוּ לָא חָזֵי, מַזְּלֵהּ חָזֵי, כִּי אַף־עַל־פִּי שֶׁאֵינוֹ מֵבִין הַדָּבָר בְּשִׂכְלוֹ, אַף־עַל־פִּי־כֵן מֵבִין מֵרָחוֹק שֶׁרָאוּי לוֹ לְהַאֲמִין, כִּי כְּשֶׁרוֹצֶה לְהִסְתַּכֵּל עַל הָאֱמֶת, הוּא מֵבִין בְּבֵרוּר שֶׁצְּרִיכִין לְהַאֲמִין, כִּי הוּא מֵבִין זֶה בְּעַצְמוֹ שֶׁאִי אֶפְשָׁר לְהָבִין הַדָּבָר בְּשׁוּם שֵׂכֶ

). 
צב. כְּשֶׁרוֹדֵף שִׂכְלוֹ לָדַעַת וּלְהִסְתַּכֵּל בְּמַה שֶּׁאֵין לוֹ רְשׁוּת וְאֵינוֹ רוֹצֶה לִסְמֹךְ עַל הָאֱמוּנָה לְבַד, עַל־יְדֵי־זֶה גּוֹרְמִין שְׁבִירַת כֵּלִים, חַס וְשָׁלוֹם, דְּהַיְנוּ שֶׁנִּשְׁבָּר כְּלִי הָאֱמוּנָה, מֵאַחַר שֶׁאֵינוֹ רוֹצֶה לִסְמֹךְ עַל הָאֱמוּנָה לְבַד, וְרוֹצֶה לָדַעַת וּלְהָבִין דַּיְקָא בְּלִי אֱמוּנָה; נִמְצָא שֶׁמַּפְשִׁיט אֶת הַדַּעַת מִן הָאֱמוּנָה, שֶׁזֶּה בְּחִינַת שְׁבִירַת כֵּלִים וּמִיתַת הַמְּלָכִים, כִּי נִשְׁאֲרוּ הַכֵּלִים בְּלִי אוֹרוֹת, וְהָאוֹרוֹת בְּלִי כֵלִים, כִּי הָאֱמוּנָה הוּא בְּחִינַת כֵּלִים, וְהַדַּעַת הוּא בְּחִינַת אוֹרוֹת, וּמֵחֲמַת זֶה נִתְבַּטֵּל הָאוֹר לְגַמְרֵי, כִּי חוֹזֵר הַכֹּל אֶל אֵין־סוֹף מֵחֲמַת שֶׁהוּא בְּלֹא כְלִי וְהַכֵּלִים נָפְלוּ לְמַטָּה וְכוּ', כְּיָדוּעַ בִּכְתָבִים. הַיְנוּ שֶׁמֵּחֲמַת שֶׁרוֹדֵף שִׂכְלוֹ לְהִסְתַּכֵּל בְּמַה שֶּׁאֵין לוֹ רְשׁוּת, וְאֵינוֹ רוֹצֶה לִסְמֹךְ שָׁם עַל הָאֱמוּנָה לְבַד, נִמְצָא שֶׁפּוֹגֵם בְּהָאֱמוּנָה, וְאָז מֵחֲמַת רִבּוּי אוֹר הַשֵּׂכֶל נִשְׁבָּר כְּלִי הָאֱמוּנָה, וְאָז נִפְגָּם וְנוֹפֵל הָאֱמוּנָה, וְאָז נִתְבַּטֵּל הַדַּעַת לְגַמְרֵי, שֶׁאֵינוֹ יָכוֹל עַל־יְדֵי־זֶה לְהָבִין וּלְהַשִּׂיג אֲפִלּוּ מַה שֶּׁהָיָה אֶפְשָׁר לוֹ לְהָבִין בַּתְּחִלָּה, כִּי חָזַר הַכֹּל אֶל בְּחִינַת הָאֵין־סוֹף מֵאַחַר שֶׁנִּשְׁבַּר הַכְּלִי וְהַצִּמְצוּמִים שֶׁהוּא הָאֱמוּנָה הַקְּדוֹשָׁה. וְזֶה בְּחִינַת חֵטְא עֵץ־ הַדַּעַת, שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, דְּאִסְתַּכַּל בְּמָה דְּלָא הֲוָה לֵהּ רְשׁוּת, שֶׁעַל יְדֵי־זֶה חָזַר וְגָרַם שְׁבִירַת כֵּלִים כַּמּוּבָא (שם אותיות ג ד). 
צג. כְּלַל הַדָּבָר, שֶׁהָעִקָּר הוּא הָאֱמוּנָה בִּפְשִׁיטוּת, לְהַאֲמִין בְּהַשֵּׁם יִתְבָּרַךְ בִּתְמִימוּת וּבִפְשִׁיטוּת בְּלִי שׁוּם חֲקִירוֹת וְחָכְמוֹת כְּלָל, וּכְשֶׁזּוֹכֶה לִהְיוֹת חָזָק בָּזֶה יָמִים וְשָׁנִים הַרְבֵּה, אֲזַי אִם יִזְכֶּה, יַחְמֹל עָלָיו הַשֵּׁם יִתְבָּרַךְ וְיִפְתַּח לוֹ שְׁבִילֵי הַשֵּׂכֶל וְיוּכַל לְהַשִּׂיג וּלְהָבִין מְעַט בִּידִיעָתוֹ יִתְבָּרַךְ. וַאֲפִלּוּ אַחַר־כָּךְ, כְּשֶׁיִּזְכֶּה לְאֵיזֶה יְדִיעָה וְהַשָּׂגָה, הוּא צָרִיךְ לִתֵּן גְּבוּל לְדַעְתּוֹ שֶׁלֹּא יִסְתַּכֵּל בְּמַה שֶּׁאֵין לוֹ רְשׁוּת, כִּי בַּמֻּפְלָא מִמְּךָ אַל תִּדְרשׁ, רַק לִסְמֹךְ עַל אֱמוּנָה לְבַד, כִּי לְעוֹלָם צְרִיכִין לְהִתְחַזֵּק רַק בֶּאֱמוּנָה, שֶׁהִיא הַיְסוֹד וְהַקִּיּוּם שֶׁל כָּל הָעוֹלָמוֹת, וְהָאֱמוּנָה הוּא בְּרֹאשׁ וּבְסוֹף וּבְאֶמְצַע, בִּבְחִינַת "אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אֱלֹקִים" - "אֲנִי" הוּא בְּחִינַת מַלְכוּת אֱמוּנָה כַּיָּדוּעַ, וּמִבַּלְעֲדֵי הָאֱמוּנָה אִי אֶפְשָׁר לָדַעַת מֵהַשֵּׁם יִתְבָּר

). 
צה. אַף־עַל־פִּי שֶׁזֶּה הַדְּבֵקוּת הַנַּ"ל יָקָר מְאֹד, אַף־עַל־פִּי־כֵן אִי אֶפְשָׁר לִהְיוֹת דָּבוּק תָּמִיד, כִּי אִי אֶפְשָׁר שֶׁהָאֱמוּנָה הַקְּדוֹשָׁה תְּקַבֵּל תָּמִיד מִן הַדַּעַת הַקְּדוֹשָׁה, כְּדֵי שֶׁלֹּא יִתְגַּבְּרוּ, חַס וְשָׁלוֹם, הָעֲנָנִין דִּמְכַסָּיִין עַל עַיְנִין, שֶׁהֵם בְּחִינַת קְלִפַּת עֵשָׂו וְיִשְׁמָעֵאל, שֶׁהֵם הַקְּלִפּוֹת וְהַכְּפִירוֹת הַבָּאִים מִבְּחִינַת שְׁבִירַת כֵּלִים הַנַּ"ל. כִּי בְּכָל עֵת שֶׁצְּרִיכִין לַעֲשׂוֹת אֵיזֶה יִחוּד דִּקְדֻשָּׁה שֶׁהוּא בְּחִינַת דְּבֵקוּת כַּנַּ"ל, אָז צְרִיכִין לְעוֹרֵר תְּחִלַּת הַצִּמְצוּם הַנַּ"ל וּלְבָרֵר בֵּרוּרִים מִבְּחִינַת שִׁבְרֵי־כֵלִים (עַיֵּן פְּנִים); וּמֵחֲמַת שֶׁבְּאֵלּוּ הַשִּׁבְרֵי־כֵלִים נֶאֱחָז הַסִּטְרָא־אָחֳרָא וְהַקְּלִפּוֹת מְאֹד מְאֹד, עַל־כֵּן צְרִיכִין לִהְיוֹת אִישׁ־חַיִל וְגִבּוֹר גָּדוֹל מִי שֶׁרוֹצֶה לַעֲסֹק בָּזֶה לְיַחֵד יִחוּדִים וּלְזַוֵּג הַמִּדּוֹת הַקְּדוֹשִׁים, כְּדֵי שֶׁלֹּא יִתְגָּרוּ בּוֹ הַכְּפִירוֹת שֶׁהֵם הַקְּלִפּוֹת שֶׁנֶּאֱחָזִין בְּשִׁבְרֵי־כֵלִים, וְהֵם הֵם בְּחִינַת הָעֲנָנִין דִּמְכַסָּיִין עַל עַיְנִין, וּצְרִיכִין לְהִשָּׁמֵר מֵהֶם מְאֹד. וַאֲפִלּוּ מִי שֶׁהוּא אִישׁ־חַיִל וְיוֹדֵעַ לְהִשָּׁמֵר מֵהֶם, אַף־עַל־פִּי־כֵן אִי אֶפְשָׁר לוֹ לִהְיוֹת דָּבוּק תָּמִיד, שֶׁלֹּא יִתְגַּבְּרוּ, חַס וְשָׁלוֹם, הַכְּפִירוֹת וְהַקְּלִפּוֹת הַנֶּאֱחָזִין בְּשִׁבְרֵי־כֵלִים שֶׁעוֹסְקִין לְבָרֵר אוֹתָם עַל־יְדֵי הַדְּבֵקוּת וְהַיִּחוּד. וְעַל־כֵּן גַּם הַצַּדִּיק צָרִיךְ לְבַטֵּל עַצְמוֹ לִפְעָמִים מִדְבֵקוּתוֹ, בִּבְחִינַת 'בִּטּוּלָהּ שֶׁל תּוֹרָה זֶהוּ קִיּוּמָהּ', עַד שֶׁיָּבוֹא מָשִׁיחַ וִיתַקֵּן הָעוֹלָם בִּשְׁלֵמוּת וְיִתְבַּטְּלוּ כָּל הַקְּלִפּוֹת וְהָעֲנָנִין דִּמְכַסָּיִין עַל עַיְנִין הַנַּ"ל, וְאָז יִהְיוּ יְכוֹלִים לִהְיוֹת דְּבוּקִים בְּהַשֵּׁם יִתְבָּרַךְ בִּתְמִידוּת (שם אותיות ו, ט). 
צו. אִי אֶפְשָׁר לְהַמְשִׁיךְ הַדַּעַת לְתוֹךְ הָאֱמוּנָה, כִּי־אִם כְּשֶׁהָאֱמוּנָה טְהוֹרָה וּקְדוֹשָׁה, שֶׁאָז יֶשׁ לָהּ כֹּחַ לְקַבֵּל אוֹר הַדַּעַת וּלְהוֹלִיד וּלְגַלּוֹת עַל־יְדֵי־זֶה הוֹלָדוֹת וְהִתְגַּלּוּת קְדוֹשׁוֹת; אֲבָל תֵּכֶף כְּשֶׁמִּתְעוֹרֵר דַּם־נִדּוּת בְּהָאִשָּׁה יִרְאַת־הַשֵּׁם, כִּבְיָכוֹל, דְּהַיְנוּ כְּשֶׁמַּתְחִילִין לְבַלְבֵּל אֶת אֱמוּנָתוֹ בְּקֻשְׁיוֹת וּכְפִירוֹת הַנִּמְשָׁכִין מִשְּׁבִירַת כֵּלִים, שֶׁזֶּה בְּחִינַת דַּם־נִדּוּת, כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל: עֲבוֹדָה זָרָה מְטַמְּאָה כְּנִדָּה, אֲזַי אָסוּר לוֹ לְהִשְׁתַּדֵּל לְהַמְשִׁיךְ הַדַּעַת לְתוֹךְ הָאֱמוּנָה, כִּי אָז צָרִיךְ לֵישֵׁב בָּדָד וְלִבְרֹחַ מִן הַדַּעַת לְגַמְרֵי, דְּהַיְנוּ שֶׁלֹּא יִשְׁתַּמֵּשׁ עִם הַדַּעַת כְּלָל וְלֹא יְחַבֵּר אָז אֶת הַדַּעַת עִם הָאֱמוּנָה כְּלָל, דְּהַיְנוּ שֶׁלֹּא יִרְצֶה לְהַמְשִׁיךְ הַדַּעַת לְהָבִין וּלְתָרֵץ הַקֻּשְׁיוֹת וְהַחֲקִירוֹת וְהַכְּפִירוֹת הָעוֹלִים עַל מֹחוֹ, כִּי תֵּכֶף כְּשֶׁעוֹלִים עַל דַּעְתּוֹ קֻשְׁיוֹת וּכְפִירוֹת, חַס וְשָׁלוֹם, אֲזַי הוּא צָרִיךְ לִסְמֹךְ רַק עַל הָאֱמוּנָה לְבַד בְּלִי שׁוּם הֲבָנַת הַדַּעַת, כִּי כְּשֶׁיִּרְצֶה אָז לְהָבִין בְּשֵׂכֶל, אֲזַי יִתְגַּבְּרוּ הַקֻּשְׁיוֹת וְהַכְּפִירוֹת, שֶׁהֵם בְּחִינַת דַּם־נִדּוּת, עַל הַשֵּׂכֶל, וְלֹא דַי שֶׁלֹּא יְתַקֵּן אֶת הָאֱמוּנָה עַל־יְדֵי הַשֵּׂכֶל, אַדְּרַבָּה, הָאֱמוּנָה וְהַשֵּׂכֶל יִהְיוּ נִפְגָּמִין וְנִתְקַלְקְלִין יוֹתֵר עַל־יְדֵי־זֶה, בִּבְחִינַת "וּתְהִי נִדָּתָהּ עָלָיו", וְיִתְבַּטֵּל הַשֵּׂכֶל וְהָאֱמוּנָה לְגַמְרֵי וְיָכוֹל לָבוֹא עַל־יְדֵי־זֶה לִכְפִירוֹת גְּמוּרוֹת, רַחֲמָנָא לִצְּלַן. וְזֶה בְּחִינַת חֹמֶר אִסּוּר נִדָּה, כִּי אִישׁ וְאִשָּׁה בְּשָׁרְשָׁן הֵם בְּחִינַת דַּעַת וֶאֱמוּנָה, וּכְשֶׁמִּתְעוֹרֵר הַדַּם־נִדּוּת, חַס וְשָׁלוֹם, שֶׁהֵם בְּחִינַת הַכְּפִירוֹת, אָז נֶאֱמָר: "וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ, לֹא תִקְרַב", שֶׁלֹּא יִתְגַבֵּר הַדַּם־נִדּוּת, חַס וְשָׁלוֹם, עַל הַדַּעַת הַקְּדוֹשָׁה וְיִתְבַּטֵּל הַדַּעַת וְהָאֱמוּנָה לְגַמְרֵי וְיִתְגַּבְּרוּ הַכְּפִירוֹת, חַס וְשָׁלוֹם. וְאָז עִקַּר הַתִּקּוּן, שֶׁיִּהְיֶה פֵּרוּד בֵּין הַדַּעַת וְהָאֱמוּנָה, וְאָז צְרִיכִין לְסַלֵּק הַדַּעַת לְגַמְרֵי וְלִסְמֹךְ רַק עַל אֱמוּנָה לְבָד. וְזֶה: "וְהִזַּרְתֶּם אֶת בְּנֵי־יִשְׂרָאֵל", וְאָמְרוּ רַבּוֹתֵינוּ זַ"ל, שֶׁצְּרִיכִין לִפְרשׁ סָמוּךְ לְוִסְתָּהּ, כִּי לָא מִבַּעְיָא בְּעֵת נִדּוּתָהּ צְרִיכִין לִפְרשׁ, אֶלָּא אֲפִלּוּ סָמוּךְ לְוִסְתָּהּ, הַיְנוּ תֵּכֶף כְּשֶׁיּוֹדְעִין שֶׁיַּתְחִילוּ לַעֲלוֹת עַל הַדַּעַת אֵיזֶה קֻשְׁיוֹת וּכְפִירוֹת שֶׁהֵם בְּחִינַת דַּם־נִדּוּת, אֲזַי תֵּכֶף צְרִיכִין לְהַפְרִישׁ אֶת הַדַּעַת לִבְלִי לְהִשְׁתַּמֵּשׁ עִמּוֹ כְּלָל, רַק לִסְמֹךְ עַל אֱמוּנָה לְבָד. וְהַכְּלָל, שֶׁאָסוּר לְהִשְׁתַּמֵּשׁ עִם דַּעְתּוֹ כִּי־אִם בְּעֵת שֶׁהָאֱמוּנָה עַל מְכוֹנָהּ, שֶׁהָאֱמוּנָה חֲזָקָה וּנְכוֹנָה אֶצְלוֹ בְּתֹקֶף גָּדוֹל וְאֵין לוֹ שׁוּם סָפֵק וְקֻשְׁיָא כְּלָל. וְאָז כְּשֶׁהָאֱמוּנָה חֲזָקָה וּנְכוֹנָה אֶצְלוֹ בֶּאֱמֶת בִּתְמִימוּת וּבִפְשִׁיטוּת בְּתֹקֶף גָּדוֹל, אָז יֶשׁ לוֹ רְשׁוּת לִרְדֹּף וּלְהִשְׁתּוֹקֵק לְהַשִּׂיג וְלֵידַע מְעַט מִמֶּנּוּ יִתְבָּרַךְ כְּפִי מַדְרֵגָתוֹ, כִּי לְכָךְ נוֹצַר, בְּגִין דְּיִשְׁתְּמוֹדְעִין לֵהּ; אֲבָל תֵּכֶף כְּשֶׁמַּתְחִילִין לִכְנֹס בּוֹ אֵיזֶה קֻשְׁיוֹת וַחֲקִירוֹת, שֶׁזֶּהוּ בְּחִינַת דַּםשׂנִדּוֹת, אָז צָרִיךְ לִבְרֹחַ מִן הַשֵּׂכֶל לְגַמְרֵי וְלִבְלִי לְהִשְׁתַּמֵּשׁ עִם הַשֵּׂכֶל כְּלָל, רַק לִס

). 
צח. עִקַּר הַבְּרִיאָה הָיְתָה בִּשְׁבִיל הָאָדָם, דְּהַיְנוּ בִּשְׁבִיל הַצַּדִּיק שֶׁנִּקְרָא אָדָם. וְעִקַּר מַעֲלַת הָאָדָם הוּא, שֶׁיֶּשׁ לוֹ כֹּחַ לְקַשֵּׁר וּלְחַבֵּר כָּל הָעוֹלָמוֹת יַחַד, דְּהַיְנוּ לְחַבֵּר עָלְמָא תַתָּאָה בְּעָלְמָא עִלָּאָה, שֶׁבָּהֶם כְּלוּלִים תִּקּוּן כָּל הָעוֹלָמוֹת, כִּי הָאָדָם כָּלוּל מִשְּׁנֵיהֶם, מֵעֶלְיוֹנִים וְתַחְתּוֹנִים, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, כִּי זֶה עִקַּר הַשְּׁלֵמוּת וְזֶה עִקַּר הַשַּׁעֲשׁוּעִים שֶׁל הַשֵּׁם יִתְבָּרַךְ כְּשֶׁמִּתְחַבֵּר וּמִתְקַשֵּׁר עוֹלָם הַתַּחְתּוֹן, שֶׁהוּא עוֹלָם הָעֲשִׂיָּה הַגַּשְׁמִי הַזֶּה, בָּעוֹלָמוֹת הָעֶלְיוֹנִים הָרוּחָנִיִּים וְהַזַּכִּים מְאֹד, בִּבְחִינַת "וְאָבִיתָ תְהִלָּה מִגּוּשֵׁי עָפָר, מִקְּרוּצֵי חֹמֶר", כִּי זֶהוּ רְצוֹנוֹ יִתְבָּרַךְ שֶׁבִּשְׁבִיל זֶה בָּרָא כָּל הַבְּרִיאָה מֵרֹאשׁ וְעַד סוֹף, וְהַכֹּל בִּשְׁבִיל הָאָדָם הַבַּעַל־בְּחִירָה שֶׁהוּא בָּעוֹלָם הַזֶּה הַגַּשְׁמִי, שֶׁעִקַּר עֲבוֹדָתוֹ הוּא לְקַשֵּׁר תַּחְתּוֹנִים בְּעֶלְיוֹנִים, שֶׁזֶּה עִקַּר תַּעֲנוּגָיו וְשַׁעֲשׁוּעָיו יִתְבָּרַךְ, כִּי מִיּוֹם שֶׁבָּרָא הַקָּדוֹשׁ־בָּרוּךְ־הוּא אֶת הָעוֹלָם נִתְאַוָּה לִהְיוֹת דִּירָתוֹ בַּתַּחְתּוֹנִים כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל, וְעִקַּר הִתְקַשְּׁרוּת וְהִכָּלְלוּת שֶׁל תַּחְתּוֹנִים בְּעֶלְיוֹנִים, עָלְמָא תַתָּאָה בְּעָלְמָא עִלָּאָה, הוּא רַק עַל־יְדֵי אֱמוּנָה שֶׁהוּא כְּלַל הַתּוֹרָה, בִּבְחִינַת "כָּל מִצְו?ֹתֶיךָ אֱמוּנָה", כִּי כָּל מִצְו?ֹת הַתּוֹרָה הֵם בָּעוֹלָם הַזֶּה בְּעוֹלַם הַמַּעֲשֶׂה דַּיְקָא, וְרֻבָּם כְּכֻלָּם מְלֻבָּשִׁין בִּדְבָרִים גַּשְׁמִיִּים, שֶׁצְּרִיכִין לַעֲשׂוֹת צִיצִת מִצֶּמֶר וּפִשְׁתָּן דַּיְקָא, וּתְפִלִּין מֵעוֹר בְּהֵמָה וְכֵן סֻכָּה וְלוּלָב וְכוּ', וְעַל־יְדֵי שֶׁאָנוּ מְקַיְּמִין מִצְו?ֹתָיו יִתְבָּרַךְ בְּמַעֲשֶׂה דַּיְקָא, בִּדְבָרִים גַּשְׁמִיִּים, עַל־יְדֵי־זֶה נַעֲשֶׂה עִקַּר הַיִּחוּד וְהַהִתְקַשְּׁרוּת שֶׁל עָלְמָא תַתָּאָה בְּעָלְמָא עִלָּאָה, שֶׁנִּכְלָל שְׁכִינַת עֻזּוֹ הַשּׁוֹכֵן בַּתַּחְתּוֹנִים בְּמִי שֶׁהוּא מְרוֹמָם עַל כָּל בְּרָכָה וּתְהִלָּה, כִּי הוּא יִתְבָּרַךְ לְמַעְלָה מִכָּל הָרוּחָנִיּוּת וּמִכָּל הַשֵּׁמוֹת וּמִכָּל הַמַּחֲשָׁבוֹת, וְלֵית מַחֲשָׁבָה תְּפִיסָא בֵּהּ כְּלָל. וְעַל־כֵּן בֶּאֱמֶת, זֹאת הַבְּחִינָה אִי אֶפְשָׁר לְהַשִּׂיג עַל־יְדֵי שׁוּם שֵׂכֶל וְחָכְמָה אֵיךְ אֶפְשָׁר לְקַשֵּׁר עוֹלָם הַגַּשְׁמִי הַזֶּה בְּבוֹרֵא הַכֹּל יִתְבָּרַךְ שֶׁהוּא מְרוֹמָם מִכָּל הָרוּחָנִיּוּת, וְאֵיךְ שַׁיָּךְ שֶׁהוּא יִתְבָּרַךְ יְקַבֵּל תַּעֲנוּג וְשַׁעֲשׁוּעַ מִמַּעֲשֵׂה הַתַּחְתּוֹנִים, אֲשֶׁר עַל־יְדֵי מְבוּכָה זֹאת רַבִּים נִתְפַּקְּרוּ לְגַמְרֵי, רַחֲמָנָא לִצְּלַן, וְרַבִּים אוֹמְרִים עַל הַמִּצְו?ֹת טְעָמִים שֶׁל שְׁטוּת וָהֶבֶל; אֲבָל בֶּאֱמֶת אִי אֶפְשָׁר לְהַשִּׂיג וּלְהָבִין זֹאת בְּשׁוּם שֵׂכֶל, כִּי־אִם בֶּאֱמוּנָה לְבַד, כְּמוֹ שֶׁנֶּאֱמַר: "כָּל מִצְו?ֹתֶיךָ אֱמוּנָה", וְהָאֱמוּנָה הַזֹּאת מַשְׁפִּיעִים בָּנוּ הַצַּדִּיקִים הָאֲמִתִּיִּים שֶׁזָּכוּ לְ'תַכְלִית הַיְדִיעָה - אֲשֶׁר לֹא נֵדַע', וּמֵאַחַר שֶׁהֵם בִּבְחִינַת 'לֹא נֵדַע', שֶׁזֶּהוּ תַּכְלִית הַיְדִיעָה, עַל־כֵּן הֵם בְּתַכְלִית שְׁלֵמוּת הָאֱמוּנָה, כִּי הָאֱמוּנָה הוּא בְּמַה שֶּׁאֵין מְבִינִים. וְעַל־יְדֵי אֱמוּנָה הַזֹּאת, שֶׁהוּא יְסוֹד כָּל הַתּוֹרָה וְהַמִּצְו?ֹת, עַל־יְדֵי־זֶה מִתְקַשְּׁרִין וְנִכְלָלִין כָּל הָעוֹלָמוֹת קט הַתַּחְתּוֹנִים בָּעֶלְיוֹנִים, שֶׁזֶּהוּ עִקַּר הַתַּכְלִית שֶׁבִּשְׁבִיל זֶה נִבְרָא הַכֹּל כַּנַּ"ל (הל' נדרים הל' ד, אותיות יב יג יד). 
צט. הַצַּדִּיק הַגָּדוֹל בְּמַעֲלָה, כָּל מַה שֶּׁבָּא לְאֵיזֶה הַשָּׂגָה וּמַדְרֵגָה, אֲפִלּוּ כְּשֶׁזּוֹכֶה לַעֲלִיָּה גְדוֹלָה, הוּא מֵשִׂים עַצְמוֹ תֵּכֶף כְּאֵינוֹ יוֹדֵעַ, וְחוֹזֵר בְּכָל פַּעַם אֶל הָאֱמוּנָה; כִּי הוּא יוֹדֵעַ וּמַאֲמִין, שֶׁכְּפִי גְּדֻלַּת הַשֵּׁם יִתְבָּרַךְ, עֲדַיִן אֵינוֹ יוֹדֵעַ כְּלָל, כִּי גָּבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וְכוּ', כִּי לִגְדֻלָּתוֹ אֵין חֵקֶר, וְעַל־כֵּן אַף־עַל־פִּי שֶׁזּוֹכֶה לְהַשָּׂגָה גְּבוֹהָה וַעֲצוּמָה מְאֹד, אַף־עַל־פִּי־כֵן אֵינוֹ סוֹמֵךְ אֶת עַצְמוֹ עַל זֶה לַעֲבֹד אֶת הַשֵּׁם יִתְבָּרַךְ בְּחָכְמוֹת לְבַד, רַק הוּא חוֹזֵר בְּכָל פַּעַם לַעֲבֹד אֶת הַשֵּׁם יִתְבָּרַךְ בִּתְמִימוּת בַּעֲבוֹדוֹת פְּשׁוּטוֹת, וּמוֹרִיד אֶת עַצְמוֹ לְכָל הַמַּדְרֵגוֹת הַתַּחְתּוֹנוֹת, לְהַעֲלוֹת נַחַת־רוּחַ לְפָנָיו יִתְבָּרַךְ מִכֻּלָּם, כִּי זֶה עִקַּר שַׁעֲשׁוּעָיו יִתְבָּרַךְ, וְעַל־ יְדֵי־זֶה בְּעַצְמוֹ זוֹכֶה הַצַּדִּיק לַעֲלִיּוֹת גְּבוֹהוֹת יוֹתֵר וְיוֹתֵר, כִּי עַל־יְדֵי אֱמוּנָה וּתְמִימוּת כַּנַּ"ל, זוֹכִין לַעֲלוֹת עַל כָּל הַמַּדְרֵגוֹת וּלְהַגִּיעַ

). 
קא. עִקַּר שְׁלֵמוּת הִתְגַּלּוּת הָאֱמֶת הוּא בַּסּוֹף, בִּבְחִינַת "טוֹב אַחֲרִית דָּבָר מֵרֵאשִׁיתוֹ", בִּבְחִינַת "שְׂפַת אֱמֶת תִּכּוֹן לָעַד" - "כּוֹנַנְתָּ" לֹא כְתִיב אֶלָּא "תִּכּוֹן", שֶׁבַּסּוֹף לֶעָתִיד יִתְגַּלֶּה הָאֱמֶת, כִּי בְּרֵאשִׁית הַדָּבָר אִי אֶפְשָׁר לְגַלּוֹת הָאֱמֶת בְּשׁוּם אֹפֶן, כִּי אָז תִּתְבַּטֵּל הַבְּחִירָה. כִּי אִם הָיָה הָאָדָם רוֹאֶה בְּעֵינָיו תַּעֲנוּגֵי הָעוֹלָם הַבָּא מַה שֶּׁיִּזְכֶּה עַל־יְדֵי עֲזִיבַת הָעֲבֵרָה וְהַתַּאֲוָה וְכֵן עַל־יְדֵי עֲשִׂיַּת הַמִּצְוָה, בְּוַדַּאי הָיָה הַכֹּל בּוֹרְחִים מִן הָעֲבֵרָה וְרוֹדְפִים אַחֲרֵי הַמִּצְו?ֹת בְּלִי שׁוּם בְּחִירָה כְּלָל; אַךְ עִקַּר הַבְּחִירָה הוּא מֵחֲמַת שֶׁאֵין רוֹאִים הָאֱמֶת בִּתְחִלָּתוֹ, אַדְּרַבָּא, כְּפִי פַּשְׁטוּת קַטְנוּת דַּעַת הָאָדָם, נִדְמֶה לוֹ בֶּאֱמֶת שֶׁאֲכִילָה וּשְׁתִיָּה וּשְׁאָר תַּאֲווֹת הַגּוּף הֵם תַּעֲנוּג, וַעֲבוֹדַת־הַשֵּׁם הוּא יְגִיעָה, וְזֶה עִקַּר נִסְיוֹנוֹ, שֶׁצָּרִיךְ לִסְבֹּל יְגִיעוֹת גְּדוֹלוֹת בִּשְׁבִיל עֲבוֹדַת־הַשֵּׁם, וְכָל זֶה מֵחֲמַת שֶׁאֵין רוֹאֶה הָאֱמֶת תֵּכֶף, וְעַל־ יְדֵי־זֶה דַּיְקָא יִזְכֶּה לְבַסּוֹף לְקַבֵּל שָׂכָר טוֹב שֶׁהוּא הִתְגַּלּוּת הָאֱמֶת לַאֲמִתּוֹ שֶׁיִּתְגַּלֶּה לֶעָתִיד, שֶׁזֶּה עִקַּר קִבּוּל הַשָּׂכָר, וּלְפֻם צַעֲרָא אַגְרָא. וְכֵן כָּל הַקֻּשְׁיוֹת שֶׁקָּשֶׁה לְהָאָדָם עַל הַנְהָגַת הַשֵּׁם יִתְבָּרַךְ, וְכֵן מַה שֶּׁקָּשֶׁה עַל הַצַּדִּיקֵי־אֱמֶת, בִּפְרָט הַקֻּשְׁיוֹת שֶׁל הַחֲכָמִים בְּעֵינֵיהֶם וְשֶׁל הַמְחַקְּרִים, וְכָל זֶה מֵחֲמַת שֶׁלְּפִי הָאֱמֶת שֶׁבְּדַעְתָּם נִדְמֶה לָהֶם שֶׁרָאוּי שֶׁלֹּא לְהִתְנַהֵג כָּךְ, כִּי רוֹצֶה לְהָבִין וּלְהַשִּׂיג אֲמִתַּת הָאֱמֶת תֵּכֶף, אֲבָל אִישׁ־בַּעַר לֹא יֵדָע שֶׁאִי אֶפְשָׁר לְהַשִּׂיג וּלְהָבִין בַּשֵּׂכֶל אֲמִתָּתוֹ וְהַנְהָגָתוֹ יִתְבָּרַךְ בִּשְׁלֵמוּת, כִּי־אִם עַל־יְדֵי אֱמוּנָה כְּשֶׁמִּתְחַבֶּרֶת עִם הָאֱמֶת, וְלֶאֱמוּנָה זוֹכִין עַל־יְדֵי אֱמֶת, הַיְנוּ אִם יִרְצֶה לְהִסְתַּכֵּל עַל הָאֱמֶת לַאֲמִתּוֹ יָבִין שֶׁאִי אֶפְשָׁר עֲדַיִן לְהַשִּׂיג בִּשְׁלֵמוּת עֶצֶם אֲמִתַּת הָאֱמֶת, אַךְ אַף־עַל־פִּי־כֵן הָאֱמֶת הוּא כָּךְ, עַל־כֵּן צְרִיכִין לְהִתְחַזֵּק בֶּאֱמוּנָה לְהַאֲמִין בֶּהָאֱמֶת, כִּי כָּל הַקֻּשְׁיוֹת שֶׁקָּשִׁין לְהָאָדָם עַל הַנְהָגַת הַשֵּׁם יִתְבָּרַךְ, וְכֵן הָעַקְמִימִיּוּת שֶׁיֵּשׁ בְּלִבּוֹ עַל הַצַּדִּיקֵי־אֱמֶת, כָּל זֶה הוּא מֵחֲמַת שֶׁהוּא מְשֻׁקָּע בְּתַאֲוַת עוֹלָם הַזֶּה וַהֲבָלָיו וּבְכָבוֹד וְנִצָּחוֹן. וְעַל־כֵּן מִי שֶׁחָס עַל חַיָּיו בֶּאֱמֶת וְרוֹצֶה לִזְכּוֹת לְחַיִּים נִצְחִיִּים וּמַחֲזִיר פָּנָיו קְצָת מִתַּאֲוַת עוֹלָם הַזֶּה וַהֲבָלָיו וְחוֹשֵׁב עַל תַּכְלִיתוֹ הַנִּצְחִי, אֲזַי הַשֵּׁם יִתְבָּרַךְ מְרַחֵם עָלָיו וּמֵאִיר לוֹ דַּרְכֵי הָאֱמוּנָה בְּאֹפֶן שֶׁיִּהְיֶה לוֹ כֹּחַ לִבְחֹר בְּהָאֱמֶת וֶאֱמוּנָה אִם יִרְצֶה. וְאָז הוּא מֵבִין שֶׁכָּל הַנִּסְיוֹנוֹת וְהָעַקְמִימִיּוּת וְהַקֻּשְׁיוֹת שֶׁרוֹצִים לְהַסְתִּיר וּלְהַעְלִים מִמֶּנּוּ אוֹר הָאֱמֶת, כָּל זֶה הוּא רַק מֵחֲמַת שֶׁהַשֵּׁם יִתְבָּרַךְ אֵינוֹ מְגַלֶּה הָאֱמֶת בַּתְּחִלָּה בִּשְׁלֵמוּת כְּדֵי שֶׁיִּהְיֶה בְּחִירָה, רַק מֵאִיר הָאֱמֶת קְצָת בְּאֹפֶן שֶׁיִּהְיֶה כֹּחַ לְהַאֲמִין לְמִי שֶׁיִּרְצֶה לְהִסְתַּכֵּל עַל הָאֱמֶת לַאֲמִתּוֹ. וּמִבְּחִינָה זוֹ הָיָה כָּל הַנִּסְיוֹנוֹת שֶׁעָבְרוּ עַל אֲבוֹתֵינוּ בַּמִּדְבָּר, וְכֵן הוּא בְּכָל דּוֹר וּבְכָל זְמַן, וְעִקַּר הַגְּאֻלָּה תָּלוּי בָּזֶה; כִּי כָּךְ דֶּרֶךְ הַשֵּׁם יִתְבָּרַךְ, שֶׁהוּא עוֹסֵק בְּרַחֲמָיו לְקָרֵב אֶת הָאָדָם בְּכַמָּה דְּרָכִים, אַךְ אַף־עַל־פִּי־כֵן הוּא מַנִּיחַ לוֹ מָקוֹם לְהִסְתַּפֵּק קְצָת בִּשְׁבִיל נִסָּיוֹן וּבְחִירָה, וּכְשֶׁמִּתְחַזֵּק בֶּאֱמוּנָה שְׁלֵמָה עַל־ יְדֵי שֶׁמִּסְתַּכֵּל עַל הָאֱמֶת, עַל כָּל הַחֲסָדִים שֶׁעָשָׂה עִמּוֹ הַשֵּׁם יִתְבָּרַךְ, וְכֵן לְעִנְיַן אֱמוּנַת חֲכָמִים, אִם יִסְתַּכֵּל בֶּאֱמֶת עַל כָּל הַהִתְגַּלּוּת וְהַנִּפְלָאוֹת שֶׁזָּכִינוּ עַל־יְדֵי הַצַּדִּיקֵי־אֱמֶת, עַל־יְדֵי־זֶה יִתְחַזֵּק בֶּאֱמוּנָה שְׁלֵמָה וְיָבִין שֶׁכָּל הָעַקְמִימִיּוּת וְהַמַּחֲלֹקֶת, הַכֹּל הוּא רַק בִּשְׁבִיל נִסָּיוֹן וּבְחִירָה, וְאִם יִתְחַזֵּק בֶּאֱמוּנָתוֹ אַחַר כָּל הָעַקְמִימִיּוּת וְהַמַּחֲלֹקֶת וְהַנִּסְיוֹנוֹת, אֲזַי עַל־יְדֵי־זֶה דַּיְקָא יִזְכֶּה לְכָל־טוּב (שם אותיות יב יג יד טו טז). 
קב. אֲפִלּוּ כְּשֶׁזּוֹכֶה הָאָדָם לְהִתְקָרֵב אֶל הָאֱמֶת עַל־יְדֵי תֹּקֶף אֱמוּנָתוֹ כַּנַּ"ל, צָרִיךְ גַּם־כֵּן שֶׁיִּהְיֶה לוֹ אֱמוּנָה בְּעַצְמוֹ, קיא שֶׁזֶּהוּ גַּם־כֵּן בִּכְלַל אֱמוּנַת חֲכָמִים, כַּמְבֹאָר בְּמָקוֹם אַחֵר. כִּי הַרְבֵּה מִתְרַחֲקִים עַל־יְדֵי רִבּוּי הַקֻּשְׁיוֹת שֶׁקָּשֶׁה לָהֶם עַל עַצְמָן, שֶׁרוֹאִים שֶׁזֶּה כַּמָּה שֶׁחוֹתְרִים וּמִתְיַגְּעִים בִּשְׁבִיל לְהַשִּׂיג הָאֱמֶת, וְאַף־עַל־פִּי־כֵן עֲדַיִן הֵם רְחוֹקִים כָּל־כָּךְ; וְכָל זֶה מַעֲשֵׂה הַבַּעַל־ דָּבָר שֶׁחוֹתֵר עֲלֵיהֶם לְרַחֲקָם יוֹתֵר, כִּי בֶּאֱמֶת אִי אֶפְשָׁר לְהָאָדָם בְּשׁוּם אֹפֶן שֶׁיֵּדַע בְּזֶה הָעוֹלָם הֵיכָן הוּא אוֹחֵז (וַאֲפִלּוּ דָּוִד הַמֶּלֶךְ, עָלָיו הַשָּׁלוֹם, אָמַר: יוֹדֵעַ אֲנִי שֶׁיֵּשׁ קִבּוּל שָׂכָר לַצַּדִּיקִים וְכוּ', אֲבָל אֵינִי יוֹדֵעַ אִם יֶשׁ לִי חֵלֶק עִמָּהֶם, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל), וְזֶה מֵעִקְּרֵי הַנִּסְיוֹנוֹת שֶׁל הָאָדָם, שֶׁאֵינוֹ יוֹדֵעַ הֵיכָן הוּא עוֹמֵד וְאוֹחֵז, כִּי אִם הָיָה רוֹאֶה וְיוֹדֵעַ מַה שֶּׁזּוֹכֶה גַּם עַתָּה עַל־יְדֵי כָּל תְּנוּעָה וְהַעְתָּקָה שֶׁמְּנַתֵּק אֶת עַצְמוֹ מֵרַע לְטוֹב, אֲפִלּוּ תְּנוּעָה בְּעָלְמָא, אֲזַי בְּוַדַּאי הָיָה רָץ בְּכָל כֹּחוֹ לַעֲבוֹדַת־הַשֵּׁם וּלְתוֹרָתוֹ וְהָיָה מִתְבַּטֵּל הַבְּחִירָה לְגַמְרֵי, כִּי עִקַּר הַבְּחִירָה הוּא מַה שֶּׁאֵינוֹ רוֹאֶה וְיוֹדֵעַ מַה שֶּׁעוֹשֶׂה וּמְתַקֵּן כָּל אֶחָד לְפִי מְקוֹמוֹ וּשְׁעָתוֹ. עַל־כֵּן צְרִיכִין גַּם בָּזֶה לְהִתְחַזֵּק בֶּאֱמוּנָה, לֵידַע וּלְהַאֲמִין בְּדִבְרֵי רַבּוֹתֵינוּ זַ"ל, שֶׁאֵין שׁוּם תְּנוּעָה טוֹבָה נֶאֱבֶדֶת כְּלָל, כִּי לֵית רְעוּתָא טָבָא דְּאִתְאֲבִיד, וְסוֹף כָּל סוֹף לֹא יִשָּׁאֵר מִמֶּנּוּ רַק אֵיזֶה טוֹב שֶׁחָטַף בָּעוֹלָם הַזֶּה, וּבְוַדַּאי כָּל הַמַּרְבֶּה הֲרֵי זֶה מְשֻׁבָּח, אֲבָל אַף־עַל־פִּי־כֵן אַטּוּ מָאן דְּלָא יָכִיל לְמֶעְבַּד כֹּלָּא מִצְוָה - פַּלְגָּא מִצְוָה נָמֵי לָא לִעֲבַד?! וְכָל הַהִתְרַחֲקוּת שֶׁל בְּנֵי־אָדָם עַל־יְדֵי רַעְיוֹנִים וּמַחֲשָׁבוֹת כָּאֵלּוּ, הַכֹּל מֵחֲמַת בְּחִינָה הַנַּ"ל, הַיְנוּ מֵחֲמַת מַה שֶּׁרוֹצֶה לְהָבִין הָאֱמֶת תֵּכֶף וּמִיָּד. אֲבָל הַמַּאֲמִין לֹא יָחוּשׁ, וּצְרִיכִין לְהַמְתִּין הַרְבֵּה הַרְבֵּה עַד שֶׁיִּזְכֶּה לְהָבִין אֲמִתַּת דְּרָכָיו יִתְבָּרַךְ, כִּי יְשָׁרִים דַּרְכֵי ה' וְכוּ', כִּי עִקַּר הִ

). 
קג. עִקַּר הַנְּקֻדָּה הַקְּדוֹשָׁה, שֶׁהוּא בְּחִינַת צַדִּיק, שֶׁיֵּשׁ בְּכָל אֶחָד מִיִּשְׂרָאֵל (שֶׁעַל־ יְדֵי אוֹר הַנְּקֻדָּה הַזֹּאת נִתְבַּטְּלִין כָּל הַחֲרָפוֹת וַאֲהָבוֹת רָעוֹת וְזוֹכִין לְאַהֲבָה דִּקְדֻשָּׁה), הוּא הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁהִיא יְסוֹד הַכֹּל וְהִיא עִקַּר הַנְּקֻדָּה שֶׁל בְּחִינַת צַדִּיק, בְּחִינַת "וְצַדִּיק בֶּאֱמוּנָתוֹ יִחְיֶה". וְזֶה כָּל מִצְוַת קְרִיאַת־שְׁמַע; וּמֵחֲמַת שֶׁעִקַּר הִתְגַּלּוּת אוֹר הַנְּקֻדָּה הַקְּדוֹשָׁה הוּא עַל־יְדֵי דִּבּוּר־פֶּה דַּיְקָא, עַל־כֵּן צְרִיכִין לוֹמַר קְרִיאַת־שְׁמַע בְּפֶה מָלֵא דַּיְקָא. וְזֶהוּ שֶׁנִּסְמָךְ אַחַר "שְׁמַע יִשְׂרָאֵל", שֶׁהוּא עִקַּר אֱמוּנַת הַיִּחוּד, בְּחִינַת אוֹר הַנְּקֻדָּה הַקְּדוֹשָׁה, כְּתִיב תֵּכֶף אַחַר־כָּךְ "וְאָהַבְתָּ", כִּי עַל־יְדֵי־זֶה זוֹכִין לְאַהֲבָה דִּקְדֻשָּׁה. וְכֵן כָּל פָּרָשַׁת קְרִיאַת־שְׁמַע מְבֹאָר כָּל עִנְיַן הַמְשָׁכַת אוֹר הַנְּקֻדָּה הַקְּדוֹשָׁה, כַּמְבֹאָר בִּפְנִים (הל' מלמדים, הל' ד, אותיות ה, ח). 
קד. כָּל דִּבְרֵי הַצַּדִּיקִים וְהַחֲכָמִים הַנֶּאֱמָרִים בְּרוּחַ־הַקֹּדֶשׁ, בִּפְרָט בְּמַדְרֵגָה גְּבוֹהָה וְנִשְׂגָּבָה, הֵם סוֹבְלִים הַכֹּל, כָּל דִּבְרֵי אֱמֶת שֶׁ

). 
קיט. עִקַּר הַשְּׁלֵמוּת הוּא רַק הָאֱמוּנָה הַקְּדוֹשָׁה, כִּי אֵין שְׁלֵמוּת רַק בִּבְחִינַת אֱמוּנָה, וּבִלְתִּי אֱמוּנָה כָּל הַדְּבָרִים חֲסֵרִים. כִּי בֶּאֱמֶת אִי אֶפְשָׁר לָדַעַת וּלְהַשִּׂיג שׁוּם דָּבָר בַּשְּׁלֵמוּת הַגָּמוּר, וְעַל־כֵּן אֲפִלּוּ מִי שֶׁזּוֹכֶה לְהַשִּׂיג אֵיזֶה הַשָּׂגָה וִידִיעָה, כְּגוֹן שֶׁזּוֹכֶה לְהַשִּׂיג אֵיזֶה כַּוָּנָה בְּאֵיזֶה מִצְוָה, וַאֲפִלּוּ הִשִּׂיג כַּוָּנָה אֲמִתִּית - כְּשֶׁיִּרְצֶה לַעֲשׂוֹת הַמִּצְוָה בְּאוֹתָהּ הַכַּוָּנָה לְבַד, בְּוַדַּאי אֵין זֶה שְׁלֵמוּת, כִּי כִּפְלַיִם לְתוּשִׁיָּה, כִּי גַּם זֹאת הַכַּוָּנָה בְּוַדַּאי אִי אֶפְשָׁר לְהַשִּׂיגָהּ עַד תַּכְלִיתָהּ בִּשְׁלֵמוּת, מִכָּל־שֶׁכֵּן כִּי יֵשׁ שִׁבְעִים פָּנִים לַתּוֹרָה, וְכָל פָּנִים וּפָנִים הוּא כָּלוּל מֵאֲלָפִים וּרְבָבוֹת פֵּרוּשִׁים עַד אֵין קֵץ, וּבְוַדַּאי אֵין מִי שֶׁיּוּכַל לְהַשִּׂיג מִצְוָה אַחַת בַּשְּׁלֵמוּת הַגָּמוּר, כִּי "אֲרֻכָּה מֵאֶרֶץ מִדָּהּ וּרְחָבָה מִנִּי־יָם", וּכְמוֹ שֶׁנֶּאֱמַר: "לְכָל תִּכְלָה רָאִיתִי קֵץ, רְחָבָה מִצְוָתְךָ מְאֹד", וְעַל־כֵּן אִם יִרְצֶה לְקַיֵּם הַמִּצְו?ֹת רַק עִם זֹאת הַכַּוָּנָה לְבַד, בְּוַדַּאי יֶחְסַר הַרְבֵּה, כִּי כַּוָּנַת הַמִּצְוָה הוּא עַד אֵין קֵץ, עַל־כֵּן לְעוֹלָם צָרִיךְ אֱמוּנָה, כִּי אֱמוּנָה הוּא שְׁלֵמוּת, כִּי כְּשֶׁמְּקַיֵּם אֶת הַמִּצְוָה בֶּאֱמוּנָה, שֶׁמַּאֲמִין שֶׁהַשֵּׁם יִתְבָּרַךְ צִוָּה לָנוּ לַעֲשׂוֹת אֶת הַמִּצְוָה הַזֹּאת מִצַּד רְצוֹנוֹ וְטַעְמוֹ, מַה שֶּׁהוּא נֶעְלָם מְאֹד וְאִי אֶפְשָׁר לְהַשִּׂיגוֹ כְּלָל בִּשְׁלֵמוּת, וְאָז בְּזֹאת הַכַּוָּנָה כְּלוּלִים כָּל הַכַּוָּנוֹת שֶׁבָּעוֹלָם בִּשְׁלֵמוּת, כִּי בִּרְצוֹנוֹ יִתְבָּרַךְ שֶׁרָצָה שֶׁנַּעֲשֶׂה זֹאת הַמִּצְוָה, שָׁם כְּלוּלִין כָּל הַכַּוָּנוֹת שֶׁזָּכוּ הַצַּדִּיקִים לְהַשִּׂיג כְּבָר, וּמַה שֶּׁעָתִיד לְהִתְגַּלּוֹת עוֹד בְּיוֹתֵר וְיוֹתֵר לְמַעְלָה לְמַעְלָה עַד אֵין קֵץ, וְהוּא עוֹשֶׂה הַמִּצְוָה עַל דַּעַת זֶה, וְאָז הַמִּצְוָה בִּשְׁלֵמוּת, כִּי בָּזֶה כְּלוּלִים כָּל הַכַּוָּנוֹת עַד אֵין סוֹף. וְעַל־כֵּן אֲפִלּוּ מִי שֶׁזּוֹכֶה לְהַשִּׂיג כַּוָּנָה אֲמִתִּית מַה שֶּׁרָאוּי לְכַוֵּן בֶּאֱמֶת, אֲבָל אַף־עַל־פִּי־כֵן לְעוֹלָם צָרִיךְ לְצָרֵף לָזֶה הָאֱמוּנָה הַקְּדוֹשָׁה, וְאָז יֵשׁ שְׁלֵמוּת לְכַוָּנָתוֹ וּלְמִצְו?ֹתָיו; נִמְצָא, שֶׁעִקַּר הַשְּׁלֵמוּת הוּא רַק אֱמוּנָה לְבָד. וְעַל־כֵּן נִקְרֵאת הָאֱמוּנָה תְּמִימוּת, כְּמוֹ שֶׁנֶּאֱמַר: "תָּמִים תִּהְיֶה עִם ה' אֱלֹקֶיךָ", כִּי שָׁם תַּכְלִית הַשְּׁלֵמוּת וְהַתְּמִימוּת, כִּי בְּהַדַּעַת אִי אֶפְשָׁר לְהַשִּׂיג שׁוּם דָּבָר בִּשְׁלֵמוּת, כִּי־אִם עַל־יְדֵי הָאֱמוּנָה, כִּי מֵאַחַר שֶׁהוּא מַאֲמִין בְּהַשֵּׁם יִתְבָּרַךְ וּבְצַדִּיקָיו וּבְמִצְו?ֹתָיו יִתְבָּרַךְ בֶּאֱמוּנָה שְׁלֵמָה, אָז הוּא שָׁלֵם בְּתַכְלִית הַשְּׁלֵמוּת, כִּי הָאֱמוּנָה הוּא בִּלְתִּי גְבוּל, כִּי הוּא מַאֲמִין בְּהָאֱמֶת שֶׁהוּא עַד אֵין סוֹף, אַף־עַל־פִּי שֶׁאִי אֶפְשָׁר לְהַשִּׂיג בְּדַעַת בְּשׁוּם אֹפֶן, אֲבָל הָאֱמוּנָה מַקֶּפֶת הַכֹּל עַד אֵין סוֹף וְאֵין תַּכְלִית (שם אותיות ט י). 
קכ. צְרִיכִין שֶׁתִּהְיֶה הָאֱמוּנָה בִּשְׁלֵמוּת בְּלִי שׁוּם מוּם וּפְגָם כְּלָל, בִּבְחִינַת "כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ", וְאָז זוֹכֶה לְהַשִּׂיג עַל־יְדֵי־זֶה דַּעַת גָּדוֹל, כִּי הָאֱמוּנָה צְרִיכָה לְהִתְפַּשֵּׁט בְּכָל הָאֵיבָרִים, שֶׁכָּל רְמַח אֵיבָרָיו יִהְיוּ מְלֵאִים מֵאֱמוּנָה שְׁלֵמָה, כִּי הָאֱמוּנָה הוּא בְּחִינַת קוֹמָה שְׁלֵמָה, וּכְשֶׁיֵּשׁ אֵיזֶה חִסָּרוֹן וּפְגָם בְּהָאֱמוּנָה, אֲזַי יֵשׁ אֵיזֶה חִסָּרוֹן וּמוּם בְּאֵיזֶה אֵיבָר כְּפִי הַפְּגָם שֶׁבְּהָאֱמוּנָה, וְאָז אִי אֶפְשָׁר לְהַשִּׂיג הַדַּעַת בִּשְׁלֵמוּת עַל־יְדֵי זֹאת הָאֱמוּנָה שֶׁאֵין לָהּ שְׁלֵמוּת בְּכָל הָרְמַ"ח אֵיבָרִים. אֲבָל כְּשֶׁהָאֱמוּנָה בְּתַכְלִית הַשְּׁלֵמוּת, בִּבְחִינַת "כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ", אֲזַי זוֹכִין תָּמִיד לְדַעַת שָׁלֵם; וַאֲפִלּוּ בְּעֵת שֶׁמִּתְרַחֲקִין מֵהַדַּעַת, עַל־כָּל־זֶה עַל־יְדֵי הָאֱמוּנָה הַשְּׁלֵמָה מְקֻשָּׁרִין וּדְבוּקִין אֵלָיו יִתְבָּרַךְ תָּמִיד, מֵעֵת שֶׁמִּתְרַחֲקִין מֵהַדַּעַת עַד שֶׁחוֹזְרִין וְשָׁבִין לְהַדַּעַת הָאֲמִתִּי שֶׁהוּא בְּח

). 
קכז. כְּמוֹ שֶׁצְּרִיכִין לְהַאֲמִין בִּמְצִיאוּתוֹ וְאַחְדוּתוֹ יִתְבָּרַךְ, כֵּן צְרִיכִין לְהַאֲמִין שֶׁהוּא הַבּוֹרֵא, הוּא הַיּוֹצֵר וְהַמַּנְהִיג, מֶלֶךְ שַׁלִּיט וּמוֹשֵׁל וּמַשְׁגִּיחַ עַל כָּל דָּבָר מֵרֹאשׁ וְעַד סוֹף, כִּי כְּשֶׁאֵינוֹ מַאֲמִין, חַס וְשָׁלוֹם, שֶׁהוּא יִתְבָּרַךְ מוֹשֵׁל בַּכֹּל וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, אָז הוּא כּוֹפֵר וּמְקַצֵּץ בִּנְטִיעוֹת, וְעַל־כֵּן עִקַּר הָאֱמוּנָה הוּא בִּבְחִינַת "וְיָדַעְתָּ הַיּוֹם וְכוּ' כִּי ה' הוּא הָאֱלֹקִים בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת, אֵין עוֹד", כִּי צְרִיכִין לְהַמְלִיכוֹ לְמַעְלָה וּלְמַטָּה וּלְהַאֲמִין שֶׁמַּלְכוּתוֹ בַּכֹּל מָשָׁלָה, וְעַל־יְדֵי־זֶה חוֹזֵר וְנִכְלָל כָּל הַבְּרִיאָה, שֶׁהוּא בְּחִינַת שֶׁלֹּא כְּסֵדֶר, בְּחָכְמָתוֹ יִתְבָּרַךְ, שֶׁהוּא בְּחִינַת כְּסֵדֶר, וְנִתְיַחֵד בְּחִינַת הַמַּלְכוּת שֶׁהוּא בְּחִינַת אֱלֹקִים, בְּשֵׁם הֲוָיָ"ה יִתְבָּרַךְ, שֶׁזֶּה בְּעַצְמוֹ בְּחִינַת "ה' הוּא הָאֱלֹקִים" (שם הל' ה, אותיות ח ט). 
קכח. עִקַּר הִתְגַּלּוּת מַלְכוּתוֹ וּמֶמְשַׁלְתּוֹ יִתְבָּרַךְ הוּא עַל־יְדֵי אֱמוּנָה, כִּי אֱמוּנָה הוּא בְּחִינַת מַלְכוּת כַּמּוּבָא, כִּי בְּשֵׂכֶל אִי אֶפְשָׁר לְהַשִּׂיג אוֹתוֹ יִתְבָּרַךְ וְלֹא דַּרְכֵי הַנְהָגָתוֹ, כִּי־אִם עַל־יְדֵי אֱמוּנָה. וְעִקַּר הָאֱמוּנָה נִמְשֶׁכֶת עַל־יְדֵי הַתּוֹרָה הַקְּדוֹשָׁה שֶׁקִּבַּלְנוּ בִּכְתָב וּבְעַל־פֶּה, וְעִקַּר שְׁלֵמוּת הָאֱמוּנָה הוּא עַל־יְדֵי תּוֹרָה שֶׁבְּעַל־פֶּה, שֶׁבָּזֶה עִקַּר הַהֶבְדֵּל שֶׁל יִשְׂרָאֵל עַל הָאֻמּוֹת, כִּי מִתּוֹרָה שֶׁבִּכְתָב יוֹדְעִין הָעַכּוּ"ם גַּם־כֵּן וְלוֹמְדִין אוֹתָהּ, רַק מִתּוֹרָה שֶׁבְּעַל־פֶּה הֵם רְחוֹקִים לְגַמְרֵי וְכוֹפְרִים בָּהּ. וּכְמוֹ־כֵן בְּעִנְיַן הָאֱמוּנָה הַקְּדוֹשָׁה, כִּי בֶּאֱמֶת גַּם הָאֻמּוֹת כֻּלָּם יֵשׁ לָהֶם אֱמוּנָה בִּמְצִיאוּתוֹ יִתְבָּרַךְ, וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל: דְּקָרוּ לֵהּ אֱלָקָא דֶּאֱלָקַיָּא, רַק שֶׁבִּפְרָטִיּוּת הָאֱמוּנָה, הַיְנוּ לְהַאֲמִין שֶׁהַשֵּׁם יִתְבָּרַךְ מַנְהִיג הָעוֹלָם כִּרְצוֹנוֹ בְּהַשְׁגָּחָתוֹ הַפְּרָטִית, וְכָל הַשִּׁנּוּיִים שֶׁנַּעֲשִׂים בָּעוֹלָם בְּכָל עֵת וּבְכָל רֶגַע, הַכֹּל עַל־יָדוֹ יִתְבָּרַךְ, כִּי גַּם הַטֶּבַע בְּעַצְמָהּ מִתְנַהֶגֶת רַק בִּרְצוֹנוֹ יִתְבָּרַךְ - בְּעִנְיָן זֶה הֵם נְבוּכִים בְּדֵעוֹת זָרוֹת וּכְפִירוֹת גְּדוֹלוֹת, עַד שֶׁמֵּחֲמַת זֶה נִמְצָאִים בֵּינֵיהֶם קְצָת כּוֹפְרִים גְּמוּרִים, אֲבָל הֵם בְּטֵלִים בְּמִעוּטָא, וְהֵם מְבֻזִּים גַּם בְּעֵינֵי הָעַכּוּ"ם בְּעַצְמָן כִּכְלָבִים, כִּי הַכֹּל מוֹדִים בְּעִקַּר הָאֱמוּנָה בּוֹ יִתְבָּרַךְ בִּכְלָל. אֲבָל אֲנַחְנוּ בְּנֵי־יִשְׂרָאֵל, הִבְדִּילָנוּ הַשֵּׁם יִתְבָּרַךְ מִן הַתּוֹעִים וְנָתַן לָנוּ תּוֹרַת אֱמֶת בִּכְתָב וּבְעַל־פֶּה, וְאָנוּ זוֹכִין לֶאֱמוּנָה שְׁלֵמָה בְּכָל הַבְּחִינוֹת, כִּי אָנוּ מַאֲמִינִים בּוֹ יִתְבָּרַךְ, וְשֶׁכָּל הַנְהָגַת הָעוֹלָם בִּפְרָטִיּוּת, הַכֹּל עַל־יָדוֹ יִתְבָּרַךְ. וְזֶה בְּחִינַת תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל־פֶּה, כִּי תּוֹרָה שֶׁבִּכְתָב זֶה בְּחִינַת עִקַּר הָאֱמוּנָה שֶׁבִּכְלָל, וְעַל־כֵּן יוֹדְעִין מִמֶּנָּה גַּם הָאֻמּוֹת, וְתוֹרָה שֶׁבְּעַל־פֶּה זֶה בְּחִינַת שְׁלֵמוּת הָאֱמוּנָה בִּפְרָטִיּוּת, וּמִזֶּה אֵין יוֹדְעִין וּמַאֲמִינִין בְּתַכְלִית הַשְּׁלֵמוּת רַק יִשְׂרָאֵל עַם קָדוֹשׁ. וּבֶאֱמֶת שְׁנֵיהֶם אֶחָד, הַיְנוּ תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל־פֶּה, שֶׁהֵם בְּחִינַת אֱמוּנָה בִּכְלָל וֶאֱמוּנָה בִּפְרָט, שְׁנֵיהֶם אֶחָד וְאִי אֶפְשָׁר לָזֶה בְּלֹא זֶה. וְעַל־כֵּן בֶּאֱמֶת הָאֻמּוֹת הַכּוֹפְרִים בַּתּוֹרָה שֶׁבְּעַל־פֶּה, אֵין לָהֶם שׁוּם חֵלֶק גַּם בַּתּוֹרָה שֶׁבִּכְתָב, כִּי אֵין מְקַיְּמִין אוֹתָהּ, רַק שֶׁיֵּשׁ קְצָת בֵּינֵיהֶם שֶׁיּוֹדְעִין מִמֶּנָּה וְלוֹמְדִים אוֹתָהּ וְיֵשׁ לָהֶם מְעַט אֲחִיזָה בָּהּ. וְכֵן מֵאַחַר שֶׁרְחוֹקִים מֵאֱמוּנָה בִּפְרָטִיּוּת, מִמֵּילָא נִפְגְּמָה אֶצְלָם גַּם הָאֱמוּנָה הַכְּלָלִית, רַק שֶׁבְּהֶעְלֵם גָּדוֹל יֵשׁ בָּהֶם אֵיזֶה נְקֻדָּה שֶׁל אֱמוּנָה הַכְּלָלִית שֶׁיֵּשׁ לָהֶם אֵיזֶה אֲחִיזָה בָּהּ. נִמְצָא, שֶׁעִקַּר הַהֶבְדֵּל וְהַיִּתְרוֹן שֶׁל יִשְׂרָאֵל עַל הָאֻמּוֹת הוּא בִּבְחִינַת תּוֹרָה שֶׁבְּעַל־פֶּה שֶׁהוּא בְּחִינַת אֱמוּנָה הַפְּרָטִית, שֶׁמִּזֶּה הֵ

). 
קמא. יִחוּד קֻדְשָׁא־בְּרִיךְ־הוּא וּשְׁכִינְתֵּהּ אַפִּין בְּאַפִּין, זֶהוּ בְּחִינַת כְּלָלִיּוּת אַחַר הַבְּרִיאָה בְּקֹדֶם הַבְּרִיאָה. כִּי דַע כְּלָל זֶה, שֶׁהַשֵּׁם יִתְבָּרַךְ בְּעַצְמוֹ כִּבְיָכוֹל נִקְרָא קֻדְשָׁא־בְּרִיךְ־הוּא, וְהַמְשָׁכַת חַיּוּתוֹ מַה שֶּׁמְּחַיֶּה כָּל הָעוֹלָמוֹת, זֶהוּ בְּחִינַת שְׁכִינָה. וּבֶאֱמֶת כֹּלָּא חַד, כִּי ה' אֶחָד וּשְׁמוֹ אֶחָד, כִּי חַיּוּתוֹ דָּבוּק בּוֹ יִתְבָּרַךְ בְּאַחְדוּת גָּמוּר, רַק שֶׁבִּשְׁבִיל הַבְּחִירָה נָתַן הַשֵּׁם יִתְבָּרַךְ כִּבְיָכוֹל מָקוֹם לִטְעוֹת כְּדֵי שֶׁיִּהְיֶה בְּחִירָה, עַד שֶׁיֵּשׁ כּוֹפְרִים וּמִינִים שֶׁאֵינָם מַאֲמִינִים בְּהַשְׁגָּחָתוֹ יִתְבָּרַךְ, וְהֵם עוֹשִׂים פֵּרוּד כִּבְיָכוֹל בֵּין קֻדְשָׁא־בְּרִיךְ־הוּא וּשְׁכִינְתֵּהּ, הַיְנוּ בֵּין הַשֵּׁם יִתְבָּרַךְ וּבֵין כְּלָלִיּוּת הָעוֹלָמוֹת, אֲשֶׁר הוּא יִתְבָּרַךְ מְחַיֶּה אֶת כֻּלָּם עַל־יְדֵי שְׁכִינַת עֻזּוֹ כַּנַּ"ל. וּבֶאֱמֶת אִי אֶפְשָׁר לְהָבִין דָּבָר זֶה אֵיךְ הַשֵּׁם יִתְבָּרַךְ שֶׁהוּא מְרוֹמָם עַל כֹּל, הוּא מַנְהִיג וּמְחַיֶּה אֶת כָּל הָעוֹלָם הַגַּשְׁמִי הַזֶּה, וְכֵן אֵיךְ כְּלַל הַבְּרִיאָה נִכְלָל בִּבְחִינַת קֹדֶם הַבְּרִיאָה בְּאַחְדוּת גָּמוּר, בִּבְחִינַת אָב וּבֵן כַּחֲדָא, וְאַף־עַל־פִּי־כֵן תִּתְקַיֵּם הַבְּרִיאָה וְלֹא תִתְבַּטֵּל בַּמְּצִיאוּת - כָּל זֶה קָשֶׁה מְאֹד לְהַשִּׂיג, וַאֲפִלּוּ משֶׁה רַבֵּנוּ, עָלָיו הַשָּׁלוֹם, נִתְקַשָּׁה בָּזֶה, וְהוּא סוֹד קְרִיעַת יַם־סוּף כַּמְבֹאָר בִּפְנִים, וְדָבָר זֶה אִי אֶפְשָׁר לָנוּ לְהַשִּׂיג בְּשׁוּם דַּעַת, רַק בֶּאֱמוּנָה לְבָד; כִּי עַל־יְדֵי בְּחִירַת הָאָדָם, עַל־יְדֵי שֶׁאָנוּ מַטִּין דַּעְתֵּנוּ לְהַאֲמִין בְּהָאֱמֶת שֶׁהַכֹּל נִמְשָׁךְ רַק מֵאַחְדוּתוֹ יִתְבָּרַךְ, וְשֶׁגַּם עַתָּה אַחַר הַבְּרִיאָה הַכֹּל מִתְנַהֵג רַק בְּהַשְׁגָּחָתוֹ יִתְבָּרַךְ לְבַד, עַל־יְדֵי־זֶה בְּעַצְמוֹ נִמְשָׁךְ עָלֵינוּ אוֹר הַשְׁגָּחָתוֹ יִתְבָּרַךְ בִּשְׁלֵמוּת, וְעַל־יְדֵי־זֶה נִכְלָל אַחַר הַבְּרִיאָה בִּבְחִינַת קֹדֶם הַבְּרִיאָה בִּשְׁלֵמוּת גָּדוֹל, וְזֶהוּ עִקַּר שְׁלֵמוּת תִּקּוּן הַבְּרִיאָה כֻּלָּהּ, כַּמְבֹאָר בִּפְנִים (הל' שלוחין, הל' ג). 
קמב. כְּלַל בְּרִיאַת הָעוֹלָם הוּא בְּחִינַת הַמְשָׁכַת רוּחָנִיּוּת אֱלֹקִית לְתוֹךְ צִמְצוּמִים, וְהַכֹּל בִּשְׁבִיל לְגַלּוֹת הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁהוּא בְּחִינַת מַלְכוּת, שֶׁבִּשְׁבִיל זֶה נִבְרָא הַכֹּל, כְּמוֹ שֶׁכָּתוּב: "וְכָל מַעֲשֵׂהוּ בֶּאֱמוּנָה"; אֲבָל אֱמוּנָה מַלְכוּת אִי אֶפְשָׁר לְהִתְגַּלּוֹת בִּשְׁלֵמוּת כִּי־אִם אַחַר הַבְּרִיאָה עַל־יְדֵי מַעֲשֵׂה הַתַּחְתּוֹנִים, כִּי אֵין מֶלֶךְ בְּלֹא עָם. וְכֵן אֱמוּנָה אֵין שַׁיָּךְ כִּי־אִם בְּדָבָר שֶׁאֵין רוֹאִים וּצְרִיכִין לְהַאֲמִין בּוֹ, שֶׁזֶּה רַק אַחַר שֶׁנִּתְרַחֲקָה הַבְּרִיאָה מֵהַמַּאֲצִיל הָעֶלְיוֹן, שֶׁאָז אִי אֶפְשָׁר לִרְאוֹת וּלְהָבִין אֶת הַמַּאֲצִיל יִתְבָּרַךְ, רַק שֶׁצְּרִיכִין לְהַאֲמִין בּוֹ יִתְבָּרַךְ בֶּאֱמוּנָה שְׁלֵמָה. וְעַל־כֵּן בִּתְחִלַּת הַבְּרִיאָה לֹא הָיָה לְהַבְּרִיאָה שְׁלֵמוּת, מֵחֲמַת שֶׁעֲדַיִן לֹא נִתְגַּלָּה מִדַּת הָאֱמוּנָה בִּשְׁלֵמוּת, וְעַל־כֵּן נִבְרָא צָפוֹן חָסֵר, לְהוֹרוֹת שֶׁעֲדַיִן הַבְּרִיאָה חֲסֵרָה, עַד שֶׁיָּבוֹאוּ הַצַּדִּיקִים הַקְּדוֹשִׁים שֶׁהֵם מַמְשִׁיכִים רוּחָנִיּוּת אֱלָקוּת לְתוֹךְ צִמְצוּמִים (שֶׁזֶּה בְּחִינַת רוּחַ צָפוֹן. עַיֵּן פְּנִים), שֶׁעַל־יְדֵי־זֶה נִתְתַּקֶּנֶת הָאֱמוּנָה בִּשְׁלֵמוּת, שֶׁזֶּה עִקַּר תִּקּוּן וּשְׁלֵמוּת כָּל הַבְּרִיאָה

). 
קנ. עִקַּר כְּלֵי הַשֶּׁפַע שֶׁנִּשְׁלָמִין עַל־יְדֵי דִּבּוּרֵי הַתְּפִלָּה הוּא עַל־יְדֵי אֱמוּנָה הַשְּׁלֵמָה, שֶׁהוּא עִקַּר הַכְּלִי לְקַבֵּל כָּל טוּב. וּכְמוֹ שֶׁצָּרִיךְ שֶׁיִּהְיֶה לוֹ אֱמוּנָה שְׁלֵמָה בְּהַשֵּׁם יִתְבָּרַךְ שֶׁהוּא בּוֹרֵא הַכֹּל וּמַנְהִיג וּמוֹשֵׁל וּמַשְׁגִּיחַ, וּבְיָדוֹ לְשַׁנּוֹת הַטֶּבַע כִּרְצוֹנוֹ וּלְהַשְׁפִּיעַ כָּל־טוּב, כְּמוֹ־כֵן צָרִיךְ שֶׁיִּהְיֶה לוֹ אֱמוּנָה בְּעַצְמוֹ, לְהַאֲמִין בֶּאֶמוּנָה שְׁלֵמָה שֶׁהַשֵּׁם יִתְבָּרַךְ שׁוֹמֵעַ וּמַאֲזִין וּמַקְשִׁיב כָּל דִּבּוּר שֶׁל כָּל אֶחָד מִיִּשְׂרָאֵל, אֲפִלּוּ הַגָּרוּעַ שֶׁבַּגְּרוּעִים, כִּי הוּא יִתְבָּרַךְ שׁוֹמֵעַ תְּפִלַּת כָּל פֶּה, וְיֵשׁ כֹּחַ בְּכָל אֶחָד מִיִּשְׂרָאֵל לִפְעֹל בַּקָּשָׁתוֹ בְּרַחֲמִים אֶצְלוֹ יִתְבָּרַךְ, אִם יִתְפַּלֵּל בֶּאֱמֶת אֵלָיו יִתְבָּרַךְ, כְּמוֹ שֶׁכָּתוּב: "קָרוֹב ה' לְכָל קֹרְאָיו, לְכֹל אֲשֶׁר יִקְרָאוּהוּ בֶאֱמֶת". וְכָל זְמַן שֶׁאֵין לוֹ אֱמוּנָה בְּעַצְמוֹ שֶׁיֶּשׁ גַּם לוֹ כֹּחַ לְהַמְשִׁיךְ הַשֶּׁפַע בִּתְפִלָּתוֹ, עֲדַיִן אֵין לוֹ כְּלִי לְקַבֵּל הַשֶּׁפַע, כִּי אֵין לוֹ מָקוֹם וּכְלִי בְּלִבּוֹ לְקַבֵּל הַשֶּׁפַע, מֵאַחַר שֶׁלְּפִי דַעְתּוֹ הוּא רָחוֹק מִלְּקַבֵּל וּלְהַמְשִׁיךְ הַשֶּׁפַע, מֵאַחַר שֶׁאֵינוֹ מַאֲמִין בְּעַצְמוֹ שֶׁתְּפִלָּתוֹ עוֹשָה רשֶׁם. עַל־כֵּן עִקַּר הִתְהַוּוּת הַכְּלִי עַל־יְדֵי הַתְּפִלָּה לְהַמְשִׁיךְ שֶׁפַע וְלִפְעֹל בַּקָּשָׁתוֹ, הוּא עַל־יְדֵי שְׁלֵמוּת אֱמוּנָה בְּכָל הַבְּחִינוֹת, שֶׁמַּאֲמִין שֶׁהוּא כֹּל יָכוֹל, שַׁלִּיט וּמוֹשֵׁל וּמַנְהִיג כִּרְצוֹנוֹ, וְגַם הוּא יִתְבָּרַךְ חַנּוּן וְרַחוּם וְשׁוֹמֵעַ תְּפִלַּת כָּל פֶּה. וְזֶה שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל: לְעוֹלָם יְסַדֵּר אָדָם שִׁבְחוֹ שֶׁל מָקוֹם תְּחִלָּה, וְאַחַר־כָּךְ יִשְׁאַל צְרָכָיו; כִּי עַל־יְדֵי סִדּוּר שְׁבָחָיו שֶׁל מָקוֹם, נִתְחַזְּקָה הָאֱמוּנָה בִּשְׁלֵמוּת בְּכָל הַבְּחִינוֹת הַנַּ"ל, וְעַל־יְדֵי־זֶה נִתְחַזֵּק הָאֱמוּנָה אֶצְלֵנוּ שֶׁיְּרַחֵם גַּם עָלֵינוּ וְיִשְׁמַע תְּפִלָּתֵנוּ וְיַשְׁפִּיעַ לָנוּ כָּל־טוּב, כַּאֲשֶׁר שָׁמַע תְּפִלַּת אֲבוֹתֵינוּ. וְזֶה שֶׁמְּסַיְּמִין שְׁאֵלַת צְרָכָיו בְּבִרְכַּת "שׁוֹמֵעַ תְּפִלָּה", כִּי זֶה הָעִקָּר, לְהַאֲמִין בֶּאֱמוּנָה שְׁלֵמָה שֶׁהַשֵּׁם יִתְבָּרַךְ שׁוֹמֵעַ תְּפִלַּת כָּל פֶּה, שֶׁעַל־יְדֵי־זֶה עִקַּר שְׁלֵמוּת הַכְּלִי לְקַבֵּל הַשֶּׁפַע כַּנַּ"ל (הל' נחלות, הל' ד, אותיות ג ד). 
קנא. עַל־יְדֵי שֶׁמַּאֲמִינִים בִּבְחִינַת חֻקַּת הַתּוֹרָה, דְּהַיְנוּ בִּבְחִינַת הַמַּקִּיפִין הָעֶלְיוֹנִים הַקְּדוֹשִׁים, שֶׁאִי אֶפְשָׁר לַהֲבִינָם, עַל־יְדֵי־זֶה בְּעַצְמוֹ מְאִירִין הַמַּקִּיפִים, וְזוֹכֶה שֶׁיִּתְגַּלֶּה הֶאָרַת הַשֵּׂכֶל בִּשְׁלֵמוּת מַה שֶּׁאֶפְשָׁר לֶאֱנוֹשִׁי לְהָבִין. וְעַל יְדֵי זֶה זוֹכֶה לְהִתְלַהֲבוּת הַלֵּב דִּקְדֻשָּׁה, עַד שֶׁתְּהֵא שַׁלְהֶבֶת הַלֵּב עוֹלָה תָּמִיד מֵאֵלֶיהָ בִּקְדֻשָּׁה גְדוֹלָה, וְנִמְשָׁךְ עָלָיו טָהֳרַת הַפָּרָה אֲדֻמָּה וְנִט

). 
קעה. עִקַּר תִּקּוּן וְהַמְתָּקַת כָּל הַצִּמְצוּמִים וְהַדִּינִים הוּא עַל־יְדֵי אֱמוּנָה, כִּי אֱמוּנָה הוּא בְּחִינַת צִמְצוּם, הַיְנוּ בְּחִינַת צִמְצוּם שֶׁל הַשֵּׂכֶל, וְהַצִּמְצוּם הַקָּדוֹשׁ הַזֶּה הוּא שֹׁרֶשׁ שֶׁל כָּל הַצִּמְצוּמִים שֶׁבָּעוֹלָם, בִּבְחִינַת "וְכָל מַעֲשֵׂהוּ בֶּאֱמוּנָה", כִּי כָּל מַעֲשֵׂה־בְרֵאשִׁית, דְּהַיְנוּ כְּלַל הָעוֹלָם, הֵם בְּחִינַת צִמְצוּמִים, כִּי בְּכָל דָּבָר יֵשׁ צִמְצוּם אַחֵר בְּכַמּוּת וְאֵיכוּת, וְכֻלָּם נִבְרְאוּ עַל־יְדֵי בְּחִינַת אֱמוּנָה שֶׁהוּא בְּחִינַת צִמְצוּם הָעֶלְיוֹן שֹׁרֶשׁ כָּל הַצִּמְצוּמִים שֶׁבָּעוֹלָם; וּכְשֶׁזּוֹכִין לֶאֱמוּנָה, עַל־יְדֵי־זֶה נִכְלָלִין כָּל הַדְּבָרִים שֶׁהֵם בְּחִינַת צִמְצוּמִים בֶּאֱמוּנָה, וְעַל־יְדֵי אֱמוּנָה נִכְלָלִים כֻּלָּם בְּתוֹךְ הַשֵּׂכֶל הַכּוֹלֵל, חָכְמָה עִלָּאָה, בְּחִינַת "אֶבֶן שְׁתִיָּה", שֶׁשָּׁם נִמְתָּקִין כָּל הַצִּמְצוּמִים וְהַדִּינִים. וּמֵחֲמַת שֶׁעִקַּר שְׁלֵמוּת הָאֱמוּנָה הוּא עַל־יְדֵי אֱמוּנַת חֲכָמִים כַּנַּ"ל, נִמְצָא שֶׁעִקַּר הַמְתָּקַת כָּל הַצִּמְצוּמִים וְהַדִּינִים הוּא עַל־יְדֵי אֱמוּנַת חֲכָמִים (שם אותיות ד ה). 
קעו. עִקַּר שְׁלֵמוּת אֱמוּנַת חֲכָמִים הִיא כְּשֶׁזּוֹכֶה לְהַחֲזִיקָם בְּמָמוֹנוֹ, וְעַל־ יְדֵי־זֶה בְּעַצְמוֹ נִמְתָּקִין כָּל הַצִּמְצוּמִים וְהַדִּינִים הַמְלֻבָּשִׁים בְּהַמָּמוֹן שֶׁנִּמְשָׁךְ מִבְּחִינַת שְׂמֹאל שֶׁמִּשָּׁם עִקַּר הַצִּמְצוּם, וְעַל־ יְדֵי־זֶה נִתְתַּקֵּן כָּל מָמוֹנוֹ עַל־יְדֵי הַמָּמוֹן שֶׁנּוֹתֵן לַחֲכַם־הַדּוֹר, שֶׁהוּא בְּעַצְמוֹ בְּחִינַת שֵׂכֶל הַכּוֹלֵל, חָכְמָה עִלָּאָה, שֶׁמִּשָּׁם נִמְתָּק

). 
קפב. כָּל הַהֶזֵּקוֹת שֶׁבָּעוֹלָם נִמְשָׁכִין מִפְּגַם אֱמוּנָה וּמִפְּגַם הַבְּרִית (שם הל' ה, אותיות ב ד). 
קפג. עַל־יְדֵי פְּגַם הַגַּאֲוָה נִפְגָּם הַפַּרְנָסָה דִּקְדֻשָּׁה, וּמִמֵּילָא נִפְגֶּמֶת הָאֱמוּנָה גַּם־כֵּן עַל־יְדֵי־זֶה, כַּמְבֹאָר בִּפְנִים. וְעַל־כֵּן בֶּאֱמֶת אָמְרוּ רַבּוֹתֵינוּ זַ"ל: כָּל הַמִּתְגָּאֶה, כְּאִלּוּ עוֹבֵד עֲבוֹדָה זָרָה. וְכֵן עַל־יְדֵי נִאוּף נִפְגָּם הָאֱמוּנָה, וְכֵן פְּגַם הָאֲכִילָה הוּא פְּגַם הָאֱמוּנָה, וְכֵן עַל־יְדֵי פְּגַם הַמִּשְׁפָּט נִפְגָּם הָאֱמוּנָה. וְעַל־כֵּן אָמְרוּ רַבּוֹתֵינוּ זַ"ל: הַמַּעֲמִיד דַּיָּן שֶׁאֵינוֹ

). 
קפט. עִקַּר כְּלָלִיּוּת הַתּוֹרָה וְהַמִּצְו?ֹת תְּלוּיִים בֶּאֱמוּנָה, כְּמוֹ שֶׁכָּתוּב: "כָּל מִצְו?ֹתֶיךָ אֱמוּנָה"; וְכֵן לְהֵפֶךְ, עִקַּר הַיֵּצֶר הָרָע וְהַתַּאֲווֹת וְהָעֲבֵרוֹת, חַס וְשָׁלוֹם, הֵם בִּבְחִינַת פְּגַם הָאֱמוּנָה, בְּחִינַת אֵל אַחֵר, כְּפִירוֹת. וְעִקַּר אֲחִיזַת הַכְּפִירוֹת שֶׁהוּא הַיֵּצֶר הָרָע, הוּא מִבְּחִינַת קוֹל הַחוֹזֵר; כִּי אִם הָיוּ הַכֹּל שׁוֹמְעִים אֶת הַקּוֹל הַיָּשָׁר בְּעַצְמוֹ, שֶׁהוּא כִּבְיָכוֹל קוֹל ה' בְּעַצְמוֹ שֶׁבָּרָא בּוֹ כָּל הָעוֹלָמוֹת כֻּלָּם, וַעֲדַיִן הוּא מְחַיֶּה וּמְקַיֵּם בּוֹ כָּל הָעוֹלָמוֹת כֻּלָּם, כִּי דְּבָרָיו חָיִים וְקַיָּמִים, וְכָל הַקּוֹלוֹת וְהַדִּבּוּרִים כִּבְיָכוֹל שֶׁבָּהֶם בָּרָא שָׁמַיִם וָאָרֶץ, כְּמוֹ שֶׁכָּתוּב: "בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ" וְכוּ', הֵם חָיִים וְקַיָּמִים גַּם עַכְשָׁו, וְקוֹלוֹ יִתְבָּרַךְ כִּבְיָכוֹל לֹא נִפְסַק עֲדַיִן, וְהֵם מְחַיִּין גַּם עַתָּה כָּל הָעוֹלָמוֹת כֻּלָּם, וּכְמוֹ שֶׁכָּתוּב: "לְעוֹלָם ה' דְּבָרְךָ נִצָּב בַּשָּׁמָיִם" וְכַמּוּבָא בְּשֵׁם הַבַּעַל־שֵׁם־טוֹב זַ"ל. וְאִלּוּ הָיוּ הַכֹּל זוֹכִים לִשְׁמֹעַ הַקּוֹל הַזֶּה שֶׁל הַשֵּׁם יִתְבָּרַךְ שֶׁבּוֹ בָּרָא אֶת הָעוֹלָם וּבוֹ מְקַיֵּם אֶת הָעוֹלָם כַּנַּ"ל, בְּוַדַּאי לֹא הָיָה שׁוּם בְּחִירָה כְּלָל, מֵאַחַר שֶׁהָיוּ הַכֹּל רוֹאִים וְשׁוֹמְעִים שֶׁהוּא יִתְבָּרַךְ בְּעַצְמוֹ מְחַיֶּה אֶת הָעוֹלָם בְּרוּחַ פִּיו. אֲבָל בֶּאֱמֶת זֶה הַקּוֹל בְּעֶצֶם, שֶׁהוּא בְּחִינַת קוֹל הַיָּשָׁר הַנַּ"ל, אִי אֶפְשָׁר לִשְׁמֹעַ, כִּי אִם הָיוּ שׁוֹמְעִין קוֹלוֹ יִתְבָּרַךְ, הָיוּ בְּטֵלִים כֻּלָּם בִּמְצִיאוּת, כִּי אֲפִלּוּ בִּשְׁעַת מַתַּן־תּוֹרָה, שֶׁהָיוּ יִשְׂרָאֵל מְזֻכָּכִים מְאֹד בְּמַדְרֵגָה גְבוֹהָה מְאֹד, אָמְרוּ: "כִּי מִי כָל בָּשָׂר אֲשֶׁר שָׁמַע קוֹל אֱלֹקִים חַיִּים וְכוּ'", וְעַל־כֵּן אִי אֶפְשָׁר לִשְׁמֹעַ אֶת קוֹל הַיָּשָׁר בְּעַצְמוֹ; וְעִקַּר בְּחִינַת הַשָּׂגַת הַקּוֹלוֹת שֶׁשּׁוֹמְעִין מִגְּדֻלָּתוֹ וֶאֱלָקוּתוֹ יִתְבָּרַךְ הוּא מִבְּחִינַת קוֹל הַחוֹזֵר, שֶׁהוּא בְּחִינַת יִרְאָה וָדִין, בְּחִינַת "ה' שָׁמַעְתִּי שִׁמְעֲךָ יָרֵאתִי". וְזֶה בְּחִינַת הַבְּחִירָה, שֶׁמֵּחֲמַת שֶׁעִקַּר הַשְּׁמִיעָה מִגְּדֻלָּתוֹ יִתְבָּרַךְ נִמְשֶׁכֶת מִבְּחִינַת קוֹל הַחוֹזֵר, עַל־כֵּן יֵשׁ בְּחִירָה, כִּי מִי שֶׁהוּא חֲכַם אֱמֶת וּמַטֶּה דַּעְתּוֹ אֶל הָאֱמֶת, כְּמוֹ אֲבוֹת הָעוֹלָם שֶׁהִטּוּ אָזְנָם אֶל הָאֱמֶת עַד שֶׁזָּכוּ לְהָבִין מֵהֵיכָן נִמְשָׁךְ בְּחִינַת זֶה הַקּוֹל הַחוֹזֵר, עַד שֶׁהִשִּׂגוּ וְהֵבִינוּ שֶׁזֶּה הַקּוֹל הַחוֹזֵר אֵין לוֹ מְצִיאוּת בְּעֶצֶם, רַק הָעִקָּר הוּא קוֹל הַיָּשָׁר שֶׁנִּמְשָׁךְ מִמֶּנּוּ יִתְבָּרַךְ, רַק מֵחֲמַת שֶׁהִמְשִׁיכוֹ הוּא יִתְבָּרַךְ לְתוֹךְ בְּחִינַת מְחִצַּת הַצִּמְצוּם הָרִאשׁוֹן, עַל־כֵּן יָצָא הַקּוֹל כִּבְיָכוֹל בִּבְחִינַת הַכָּאָה וַחֲבָטָה לְתוֹךְ בְּחִינַת מְחִצַּת הַצִּמְצוּם, וְעַל־יְדֵי־זֶה נִשְׁמַע קוֹל הַחוֹזֵר הַזֶּה שֶׁהוּא בְּחִינַת הַדִּין, אֲבָל בֶּאֱמֶת, הָעִקָּר הוּא הַקּוֹל הַיָּשָׁר, כִּי זֶה הַקּוֹל הַחוֹזֵר אֵין לוֹ שׁוּם מְצִיאוּת לְבַדּוֹ בְּעֶצֶם, רַק שֶׁהוּא הַחְזָרַת הַקּוֹל הַיָּשָׁר בְּעַצְמוֹ, וְעַל־כֵּן דִּבְּקוּ עַצְמָם רַק לְקוֹל הַיָּשָׁר, שֶׁהוּא בְּחִינַת עֶצֶם חַיּוּתוֹ יִתְבָּרַךְ הַמְלֻבָּשׁ בְּכָל הָעוֹלָמוֹת, וְחָבְרוּ וְיָחֲדוּ יָחַד בְּחִינַת קוֹל הַחוֹזֵר עִם קוֹל הַיָּשָׁר, וְעַל־יְדֵי־זֶה הִפְרִידוּ כָּל אֲחִיזַת הַדִּין וְהַקְּלִפּוֹת שֶׁהֵם הַכְּפִירוֹת הַנֶּאֱחָזִין בִּבְחִינַת קוֹל הַחוֹזֵר, עַל־יְדֵי שֶׁיָּדְעוּ וְהֶאֱמִינוּ שֶׁקּוֹל הַחוֹזֵר אֵין לוֹ שׁוּם מְצִיאוּת בִּפְנֵי עַצְמוֹ, חַס וְשָׁלוֹם, רַק הוּא הַחְזָרַת קוֹל הַיָּשָׁר בְּעַצְמוֹ כַּנַּ"ל. אֲבָל הָאֶפִּיקוֹרְסִים וְהַכּוֹפְרִים אֵינָם מַטִּים דַּעְתָּם אֶל הָאֱמֶת, וְאֵינָם רוֹצִים לִשְׁמֹעַ כִּי־אִם בְּחִינַת קוֹל הַחוֹזֵר בְּעַצְמוֹ, וְאֵינָם מַטִּים דַּעְתָּם כְּלָל לֵידַע וּלְהַאֲמִין בִּתְחִלַּת שֹׁרֶשׁ מְצִיאוּת הַקּוֹל וְהַחַיּוּת הַמְחַיֶּה כָּל הָעוֹלָמוֹת כֻּלָּם, כִּי זֶה דַרְכָּם כֶּסֶל לָמוֹ שֶׁל הַמְחַקְּרִים וְהַפִילוֹסוֹפִים, שֶׁכָּל חָכְמָתָם וַחֲקִירָתָם הַכֹּל בְּכָל עִנְיְנֵי הַבְּרִיאָה, הַיְנוּ בְּמַה שֶׁנַּעֲשָׂה אַחַר הַבְּרִיאָה, לֵידַע וּלְהָבִין מַהוּ הַכֹּחַ וְהַסְּגֻלָּה וְהָרְפוּאָה וְהַטֶּבַע שֶׁל כָּל אֶחָד מִפְּרָטֵי הַבְּרִיאָה, וְהַכֹּל רַק בְּעִנְיָנִים הַגַּשְׁמִיִּים שֶׁל זֶה הָעוֹלָם. וְכֵן תַּכְלִית כַּוָּנָתָם בַּחֲקִירוֹתָם וְהַמְצָאַת חָכְמוֹתֵיהֶם, הַכֹּל רַק בִּשְׁבִיל הַבְלֵי הָעוֹלָם הַזֶּה, בִּשְׁבִיל כָּבוֹד וְהִתְפָּאֲרוּת אוֹ מָמוֹן וְכַיּוֹצֵא, וְאֵין אִישׁ מֵהֶם שָׂם עַל לֵב לָשׂוּם כָּל לִבּוֹ וְדַעְתּוֹ לְדַבֵּק עַצְמוֹ בְּאוֹר הַחַיִּים, לַחְשֹׁב עַל תַּכְלִיתוֹ וְסוֹפוֹ הַנִּצְחִי, וְסוֹף כָּל סוֹף מַה יִּהְיֶה מִמֶּנּוּ; שֶׁזֶּה בְּחִינַת קְדֻשַּׁת חָכְמַת יִשְׂרָאֵל שֶׁקִּבַּלְנוּ מֵאֲבוֹתֵינוּ הַקְּדוֹשִׁים, שֶׁהִיא עִקַּר הַחָכְמָה הָאֲמִתִּית וְהַנִּצְחִית, וְכָל חָכְמָתֵנוּ הוּא לְקַיֵּם אֶת כָּל דִּבְרֵי הַתּוֹרָה הַזֹּאת, שֶׁעַל־יְדֵי־זֶה זוֹכִין לְחַיִּים נִצְחִיִּים וְלַטּוֹב הַנִּצְחִי לְעוֹלָם שֶׁכֻּלּוֹ אָרֹךְ וָטוֹב - רַק זֶה נִקְרָא חָכְמָה בֶּאֱמֶת, כִּי יִשְׂרָאֵל עוֹבְרִים עַל כָּל הַחָכְמוֹת שֶׁלָּהֶם, כִּי אֵינָם רוֹצִים לַחְקֹר כְּלָל בְּעִנְיְנֵי הָעוֹלָם הַגַּשְׁמִי הַזֶּה הָעוֹבֵר כְּהֶרֶף־עַיִן, וְהַלְוַאי וְלֹא הָיִינוּ יוֹדְעִין אֲפִלּוּ מַה שֶּׁיּוֹדֵעַ כָּל אֶחָד וְאֶחָד מֵעִנְיְנֵי תַּאֲווֹת עוֹלָם הַזֶּה וַהֲבָלָיו, כִּי הַלְוַאי הָיִינוּ פּוֹרְשִׁים עַצְמֵנוּ גַּם מֵהֶם וְלִהְיוֹת תְּמִימִים לְגַמְרֵי כְּמוֹ צַדִּיקִים הָרִאשׁוֹנִים, שֶׁיֵּשׁ מֵהֶם שֶׁלֹּא הִכִּירוּ אֲפִלּוּ צוּרַת מַטְבֵּעַ, רַק שֶׁרֹב הָעוֹלָם אֵינָם יְכוֹלִים לַעֲמֹד בָּזֶה, וְאֵין הַקָּדוֹשׁ־בָּרוּךְ־הוּא בָּא בִּטְרֻנְיָא עִם בְּרִיּוֹתָיו, וּבְהֶכְרֵחַ לָדַעַת מַה שֶּׁמֻּכְרָח לְקִיּוּם הָעוֹלָם, דְּהַיְנוּ מַשָּׂא־וּמַתָּן וְכַיּוֹצֵא הַמֻּכְרָחִים בְּיוֹתֵר; אֲבָל לַחְשֹׁב תַּחְבּוּלוֹת בְּעִנְיְנֵי עוֹלָם הַזֶּה יוֹתֵר וְיוֹתֵר בִּשְׁבִיל תַּאֲווֹת עוֹלָם הַזֶּה, אֲפִלּוּ כְּשֶׁמַּמְצִיא חָכְמָה גְדוֹלָה - אֵין שְׁטוּת גָּדוֹל מִזֶּה, מֵאַחַר שֶׁלֹּא יַצְלִיחַ עַל־יְדֵי־זֶה לָעוֹלָם הַנִּצְחִי, כִּי רֻבָּם כְּכֻלָּם נַעֲשִׂים אֶפִּיקוֹרְסִים גְּדוֹלִים עַל־ יְדֵי־זֶה וְאַחֲרִיתָם עֲדֵי אֹבֵד בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, כַּמְבֹאָר בְּמָקוֹם אַחֵר. וְעַל־כֵּן יִשְׂרָאֵל עַם קָדוֹשׁ אֵין חוֹקְרִים כְּלָל בְּעִנְיָנִים הַגַּשְׁמִיִּים שֶׁאֵינָם מֻכְרָחִים לָהֶם כָּל־כָּךְ, רַק שָׂמִים כָּל מְגַמָּתָם לְדַבֵּק עַצְמָם בֵּאלֹקִים חַיִּים עַל־יְדֵי קִיּוּם הַתּוֹרָה וְהַמִּצְו?ֹת, וְהֵם עוֹבְרִים עַל כָּל הַחָכְמוֹת כֻּלָּם, כִּי הֵם יוֹדְעִים הַחָכְמָה הָאֲמִתִּית וְהַנִּצְחִית שֶׁהוּא הָאֱמוּנָה הַקְּדוֹשָׁה, שֶׁיּוֹדְעִים וּמַאֲמִינִים שֶׁכָּל הָעוֹלָם וּמְלֹאוֹ, דּוֹמֵם, צוֹמֵחַ, חַי, מְדַבֵּר וְכוּ' וְכוּ' מֵרֹאשׁ וְעַד סוֹף, הֵם וְכֹל אֲשֶׁר בָּהֶם וְכָל כֹּחוֹתֵיהֶם עִם כָּל דִּקְדּוּקֵיהֶם וּפְרָטֵיהֶם וְכָל מִינֵי חָכְמוֹת וְתַחְבּוּלוֹת שֶׁיֵּשׁ בָּהֶם, הַכֹּל כַּאֲשֶׁר לַכֹּל בָּרָא הַשֵּׁם יִתְבָּרַךְ בִּשְׁמוֹ הַגָּדוֹל וְהוּא מְחַיֶּה אֶת כֻּלָּם בְּכָל עֵת וּבְכָל שָׁעָה, וְכֻלָּם נִבְרְאוּ בִּשְׁבִיל הָאָדָם הַשָּׁפָל כְּדֵי שֶׁיֵּדַע זֹאת בֶּאֱמוּנָה שְׁלֵמָה וְיַעֲסֹק כָּל יָמָיו לְדַבֵּק אֶת עַצְמוֹ בְּהַשֵּׁם יִתְבָּרַךְ הַמְחַיֶּה וּמְקַיֵּם אֶת כֻּלָּם עַל־יְדֵי עֵסֶק הַתּוֹרָה וְהַמִּצְו?ֹת, וְזֹאת הַחָכְמָה שֶׁהִיא הָאֱמוּנָה הָאֲמִתִּית, הִיא עוֹלָה עַל כָּל הַחָכְמוֹת כֻּלָּם. נִמְצָא, שֶׁכָּל חָכְמָתָם שֶׁל הַמְחַקְּרִים הוּא רַק בִּבְחִינַת קוֹל הַחוֹזֵר, שֶׁאֵין שׁוֹמְעִין כְּלָל אֶת קוֹלוֹ יִתְבָּרַךְ בְּעֶצֶם, וְהֵם מַבִּיטִים רַק אַחַר הַבְּרִיאָה, אַחַר הַטֶּבַע לְבַד, וְחוֹקְרִים בְּכָל הָעִנְיָנִים שֶׁאַחַר הַטֶּבַע, אֲבָל אֵין חוֹזְרִין פְּנֵיהֶם לְהַטּוֹת לְבָבָם לְהָבִין וּלְהַשְׂכִּיל הֵיטֵב מִבֶּטֶן מִי יָצָא הַקּוֹל הַזֶּה, כְּדֵי לָשׂוּם כָּל תְּשׁוּקָתָם לִדָּבֵק אֵלָיו יִתְבָּרַךְ, וְהֵם רַק חֲכָמִים לְהָרַע, וּלְהֵיטִיב לֹא יָדָעוּ, וְרוֹצִים לְהַפְרִיד, חַס וְשָׁלוֹם, בְּחִינַת קוֹל הַחוֹזֵר מֵהַקּוֹל הַיָּשָׁר, כְּאִלּוּ קוֹל הַחוֹזֵר, חַס וְשָׁלוֹם, יֶשׁ לוֹ מְצִיאוּת בִּפְנֵי עַצְמוֹ, שֶׁזֶּה בְּחִינַת "וְנִרְגָּן מַפְרִיד אַלּוּף", שֶׁמַּפְרִיד אַלּוּפוֹ שֶׁל עוֹלָם וּמְקַצֵּץ בִּנְטִיעוֹת. וְהֵם כְּמוֹ מִי שֶׁהוּא בַּיַּעַר וְשׁוֹמֵעַ קוֹל הֲבָרָה, וְסוֹבֵר וְטוֹעֶה שֶׁהוּא קוֹל מַמָּשׁ בִּפְנֵי עַצְמוֹ, שֶׁבְּוַדַּאי הוּא אֱוִיל, פֶּתִי, שׁוֹטֶה וּמְשֻׁגָּע, כִּי אֵין שׁוּם מְצִיאוּת לְקוֹל הַחוֹזֵר כְּלָל, רַק הוּא הַמְשָׁכַת וְהַחְזָרַת קוֹל הַיָּשָׁר. כְּמוֹ־כֵן הוּא מַמָּשׁ כָּל חָכְמָתָם, שֶׁחוֹקְרִים אַחַר הַטֶּבַע וְאֵין מַחֲזִירִין פְּנֵיהֶם לְקַשֵּׁר קוֹל הַחוֹזֵר לְקוֹל הַיָּשָׁר, דְּהַיְנוּ לְקַשֵּׁר כָּל הַחָכְמוֹת לְשָׁרְשָׁם, לֵידַע וּלְהַאֲמִין שֶׁהַכֹּל נִמְשָׁךְ מֵאִתּוֹ יִתְבָּרַךְ, וּלְבַלּוֹת כָּל דַּעְתּוֹ וְכָל חָכְמָתוֹ כָּל יָמָיו לְקַשֵּׁר עַצְמוֹ בּוֹ יִתְבָּרַךְ, שֶׁזֶּה עוֹלֶה לְמַעְלָה עַל כָּל הַחָכְמוֹת שֶׁבָּעוֹלָם, וּבוֹ כְּלוּלִים וּטְפֵלִים כָּל הַחָכְמוֹת, וְזוֹכֶה לְחַיִּים נִצְחִיִּים לְעוֹלָם וָעֶד. וְגַם כִּי מִי שֶׁזּוֹכֶה לְדַבֵּק אֶת עַצְמוֹ בְּתַכְלִית הַשְּׁלֵמוּת לְהַחָכְמָה הָאֲמִתִּית שֶׁהוּא הַתְּמִימוּת, לַעֲבֹד אוֹתוֹ יִתְבָּרַךְ בִּתְמִימוּת בְּתוֹרָה וּבַעֲבוֹדָה בִּפְשִׁיטוּת, יָכוֹל לִזְכּוֹת אַחַר־כָּךְ לְהַשִּׂיג גַּם כָּל הַחָכְמוֹת שֶׁבָּעוֹלָם בְּעַצְמָם בְּלִי שׁוּם יְגִיעָה כְּלָל, כְּמוֹ שֶׁכְּבָר הָיוּ כַּמָּה צַּדִּיקִים שֶׁזָּכוּ לָזֶה; אַךְ אֲפִלּוּ מִי שֶׁאֵינוֹ מַגִּיעַ לָזֶה, אֵין צָרִיךְ לָזֶה כְּלָל, וְיָכוֹל לְבַלּוֹת כָּל יָמָיו בְּטוֹב בְּלִי שׁוּם יְדִיעָה מֵחָכְמוֹת אֵלּוּ. וּבָעוֹלָם הַבָּא בְּוַדַּאי אֵינָם נִצְרָכִים לוֹ כְּלָל, אַדְּרַבָּא, אֲנָשִׁים פְּשׁוּטִים שֶׁלֹּא שָׁבְרוּ עֲדַיִן אֶת כָּל הַתַּאֲווֹת, יְכוֹלִים אֵלּוּ הַחָכְמוֹת לַעֲקֹר אוֹתָם מִשְּׁנֵי הָעוֹלָמוֹת, חַס וְשָׁלוֹם, כַּנִּרְאֶה בְּחוּשׁ, כִּי רַק הַצַּדִּיקִים הַגְּדוֹלִים יְכוֹלִים לְהִשְׁתַּמֵּשׁ בָּהֶם לְמַה שֶּׁצְּרִיכִים לַעֲבוֹדָתָם, וְהֵם יְכוֹלִים לְקַשֵּׁר כָּל הַחָכְמוֹת לְשָׁרְשָׁם הָעֶלְיוֹן, כִּי יוֹדְעִים שֶׁהַכֹּל נִמְשָׁךְ מִמֶּנּוּ יִתְבָּרַךְ (שם אותיות יט כ, כז). 
קצ. עִקַּר בְּרִיאַת הָעוֹלָם וְקִיּוּמוֹ הוּא עַל־ יְדֵי בְּחִינַת קוֹל הַשְּׁלִישִׁי, הַמַּכְרִיעַ בֵּין קוֹל הַיָּשָׁר לְקוֹל הַחוֹזֵר, כִּי הוּא כָּלוּל וּמֻרְכָּב מִשְּׁנֵיהֶם; כִּי עֶצֶם קוֹל הַיָּשָׁר בְּעַצְמוֹ, בְּוַדַּאי אִי אֶפְשָׁר לְגַלּוֹת, בִּכְדֵי שֶׁלֹּא יִתְבַּטְּלוּ בִּמְצִיאוּת. וְעַל־כֵּן בִּתְחִלָּה עָלָה בְּמַחֲשָׁבָה לִבְרֹא אֶת הָעוֹלָם בְּמִדַּתשׂ הַדִּין שֶׁהוּא בְּחִינַת קוֹל הַחוֹזֵר; רָאָה שֶׁאֵין הָעוֹלָם מִתְקַיֵּם, כִּי הָיָה מִתְרַבֶּה הָאֶפִּיקוֹרְסוּת מְאֹד וְלֹא הָיָה אֶפְשָׁר לְהָאָדָם לְהַשִּׂיג כְּלָל שֶׁהַכֹּל נִבְרָא וְנִמְשָׁךְ מִמֶּנּוּ יִתְבָּרַךְ, שֶׁזֶּה בְּחִינַת הִתְקַשְּׁרוּת קוֹל הַחוֹזֵר לְקוֹל הַיָּשָׁר, עַל־כֵּן עָמַד וְשִׁתֵּף מִדַּת־ הָרַחֲמִים לְמִדַּת־הַדִּין, שֶׁזֶּה בְּחִינַת קוֹל הַשְּׁלִישִׁי, שֶׁהוּא בְּחִינַת קוֹל הַמֻּרְכָּב מִשְּׁנֵיהֶם, וְעַל־יְדֵי־זֶה יֵשׁ קִיּוּם לְהָעוֹלָם, כִּי עַתָּה יֶשׁ לָנוּ כֹּחַ לְדַבֵּק עַצְמֵנוּ בְּאוֹר הַחַיִּים, לֵידַע וּלְהַשִּׂיג הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁהַכֹּל נִמְשָׁךְ מִמֶּנּוּ יִתְבָּרַךְ. וַאֲפִלּוּ כָּל הַחָכְמוֹת וְעַקְמִימִיּוּת שֶׁבַּלֵּב, הַנִּמְשָׁךְ מִבְּחִינַת קוֹל הַחוֹזֵר שֶׁהוּא בְּחִינַת דִּין, הַכֹּל נִמְשָׁךְ מִמֶּנּוּ יִתְבָּרַךְ בְּעַצְמוֹ בִּשְׁבִיל הַבְּחִירָה, כִּי קוֹל הַחוֹזֵר אֵין לוֹ שׁוּם מְצִיאוּת רַק מִקּוֹל הַיָּשָׁר כַּנַּ"ל. וְזֶה בְּחִינַת הָעֲשָׂרָה מַאֲמָרוֹת שֶׁנִּבְרָא בָּהֶם הָעוֹלָם, וְאָמְרוּ רַבּוֹתֵינוּ זַ"ל: "בְּרֵאשִׁית" נָמֵי מַאֲמָר הוּא, רַק מֵחֲמַת שֶׁ"בְּרֵאשִׁית" הוּא מַאֲמָר הָרִאשׁוֹן, שֶׁהוּא בְּחִינַת קוֹל הַיָּשָׁר שֶׁבּוֹ כְּלוּלִים כָּל הַמַּאֲמָרוֹת כֻּלָּם, עַל־כֵּן הוּא מַאֲמָר סָתוּם, כִּי בְּחִינַת זֶה הַקּוֹל וְהַדִּבּוּר אִי אֶפְשָׁר לִשְׁמֹעַ וּלְהַשִּׂיג כְּלָל, שֶׁלֹּא יִתְבַּטְּלוּ בִּמְצִיאוּת, רַק אַחַר שֶׁיָּצָא הַקּוֹל הַיָּשָׁר שֶׁהוּא בְּחִינַת "בְּרֵאשִׁית" שֶׁכּוֹלֵל הַכֹּל, אָז עַל־יְדֵי בְּחִינַת הַצִּמְצוּם הַקּוֹדֵם לַבְּרִיאָה, נִתְהַוָּה תֵּכֶף בְּחִינַת הַחְזָרַת הַקּוֹל הַיָּשָׁר בִּבְחִינַת הַקּוֹל הַחוֹזֵר, וְאָז הִרְכִּיב הַשֵּׁם יִתְבָּרַךְ הַשְּׁנֵי קוֹלוֹת יַחַד, שֶׁהוּא בְּחִינַת קוֹל הַשְּׁלִישִׁי הַנַּ"ל, וּבוֹ בָרָא הַכֹּל, וְזֶה בְּחִינַת כָּל הַמַּאֲמָרוֹת כֻּלָּם שֶׁנִּבְרְאוּ אַחַר־כָּךְ. וְעַל־ כֵּן עַכְשָׁו זֶה עִקַּר עֲבוֹדָתֵנוּ, לִכְלֹל הַכֹּל בִּבְחִינַת "בְּרֵאשִׁית", לְהַחֲזִיר הַכֹּל לְשָׁרְשׁוֹ, לֵידַע וּלְהַאֲמִין שֶׁהַכֹּל נִמְשָׁךְ מִמֶּנּוּ יִתְבָּרַךְ לְבַד, כִּי אֵין שׁוּם מְצִיאוּת כְּל

). 
ריב. וְאָמַר שֶׁהוֹלֵךְ אֶפִּיקוֹרְסוּת גָּדוֹל עַל הָעוֹלָם, וְכֵן סִפֵּר כַּמָּה פְּעָמִים, שֶׁהוֹלֵךְ וְנִמְשָׁךְ אֶפִּיקוֹרְסוּת גָּדוֹל, בַּעֲו?ֹנוֹתֵינוּ הָרַבִּים, בָּעוֹלָם, אַשְׁרֵי מִי שֶׁיַּחֲזִיק עַצְמוֹ בֶּאֱמוּנָה בְּאֵלּוּ הָעִתִּים! וְאָמַר: אַף־עַל־פִּי שֶׁאֵינוֹ מוֹעִיל כְּלָל מַה שֶּׁהוּא מְסַפֵּר זֹאת, שֶׁיִּהְיֶה אֶפִּיקוֹרְסוּת בָּעוֹלָם וְשֶׁצְּרִיכִין לְהִתְחַזֵּק עַצְמוֹ בֶּאֱמוּנָה, כִּי אַף־עַל־פִּי שֶׁהוּא אוֹמֵר זֹאת, אַף־עַל־פִּי־כֵן מִתְגַּבֶּרֶת הָאֶפִּיקוֹרְסוּת וְהַבִּלְבּוּלִים. כִּי הֲלוֹא גַּם דָּנִיֵּאל וְכַיּוֹצֵא בּוֹ הוֹדִיעוּ מִקֹּדֶם, שֶׁקֹּדֶם שֶׁיָּבוֹא מָשִׁיחַ יִתְבָּרְרוּ וְיִתְלַבְּנוּ וְיִצְטָרְפוּ רַבִּים, וְהִרְשִׁיעוּ רְשָׁעִים וְהַמַּשְׂכִּילִים יָבִינוּ וְכוּ'. וְאִם־כֵּן, מֵאַחַר שֶׁהוֹדִיעַ מִקֹּדֶם שֶׁזֶּה יִהְיֶה הַנִּסָּיוֹן קֹדֶם בִּיאַת מָשִׁיחַ, שֶׁיִּתְבָּרְרוּ וְיִתְלַבְּנוּ וְיִצְטָרְפוּ רַבִּים בֶּאֱמוּנָה, וּמִי שֶׁיִּזְכֶּה לַעֲמֹד בְּנִסָּיוֹן וְיִשָּׁאֵר קַיָּם בֶּאֱמוּנָתוֹ, אַשְׁרֵי לוֹ וְיִזְכֶּה לְכָל טוּב הַמְעֻתָּד לָבוֹא לָנוּ בִּמְהֵרָה בְּיָמֵינוּ, אֲשֶׁר נִבְּאוּ עֲלֵיהֶם כָּל נְבִיאֵינוּ וַחֲכָמֵינוּ מִקֹּדֶם, וְאִם־כֵּן הָיָה רָאוּי שֶׁכָּל אֶחָד יַשְׂכִּיל וְיָחוּס עַל עַצְמוֹ לִשָּׁאֵר קַיָּם חָזָק בֶּאֱמוּנָתוֹ וְלֹא יִהְיֶה לוֹ עוֹד שׁוּם נִסָּיוֹן וְצֵרוּף כְּלָל, מֵאַחַר שֶׁכְּבָר הוֹדִיעוּ זֹאת מִקֹּדֶם. וּבֶאֱמֶת אַף־עַל־פִּי שֶׁהוֹדִיעוּ זֹאת מִקֹּדֶם, אַף־עַל־פִּי־כֵן יִהְיֶה נִסָּיוֹן גָּדוֹל וְרַבִּים יַרְשִׁיעוּ, כְּמוֹ שֶׁכָּתוּב: "וְהִרְשִׁיעוּ רְשָׁעִים", אַךְ אַף־עַל־פִּי־כֵן אֲנִי מוֹדִיעַ זֹאת מִקֹּדֶם בִּשְׁבִיל אוֹתָן מְעַט הַכְּשֵׁרִים, שֶׁיְּחַזְּקוּ עַצְמָן בֶּאֱמוּנָתָן, וּבְוַדַּאי יִהְיֶה לָהֶם מִלְחָמוֹת גְּדוֹלוֹת בְּדַעְתָּן, לְמַעַן יִהְיֶה לָהֶם לְמֵשִׁיב־ נֶפֶשׁ וְהִתְחַזְּקוּת וְהִתְאַמְּצוּת יוֹתֵר, כְּשֶׁיִּרְאוּ שֶׁכְּבָר דִּבְּרוּ מִזֶּה מִקֹּדֶם. 
וְאָמַר: עוֹד יִהְיֶה זְמַן, שֶׁמִּי שֶׁיִּהְיֶה אִישׁ כָּשֵׁר פָּשׁוּט, יִהְיֶה חִדּוּשׁ גָּדוֹל כְּמוֹ הַבַּעַל־שֵׁם־טוֹב זִכְרוֹנוֹ לִבְרָכָה.
